// Generated by tools/build-proverb-compass.mjs from the approved review JSON.
export const PROVERB_COMPASS = {"proverb-01":{"id":"proverb-01","titleEn":"Out of Sight, Out of Mind","titleZh":"眼不見，心不念","version":"2026-10-28.1","items":[{"id":"proverb-01-q01","number":1,"promptEn":"Noah put his model car in a cupboard and soon stopped thinking about it.","promptZh":"諾亞把模型車放進櫃子後，很快便不再想起它。","options":[{"id":"key","text":"Once Noah put his model car in a cupboard, he soon stopped thinking about it—out of sight, out of mind.","reasonZh":"車收進櫃子後，諾亞很快不再想起它；先後關係和注意力的轉移都保留了。","correct":true},{"id":"foil-1","text":"Once Noah put his model car on his display desk, he soon stopped thinking about it—out of sight, out of mind.","reasonZh":"原文是收進櫃子，不是放在展示桌上；可見程度正是這題的線索。","correct":false},{"id":"foil-2","text":"Once Noah put his model car in a cupboard, his visitors soon stopped thinking about it—out of sight, out of mind.","reasonZh":"忘記模型車的是諾亞，原文沒有說訪客的想法。","correct":false},{"id":"foil-3","text":"Once Noah put his model car in a cupboard, he soon remembered to repair it—out of sight, out of mind.","reasonZh":"原文是逐漸不再想起，並沒有記起修理模型車。","correct":false}]},{"id":"proverb-01-q02","number":2,"promptEn":"Grace moved to another school. Some of her old classmates gradually stopped thinking about her.","promptZh":"格蕾絲轉到另一間學校。一些舊同學漸漸不再想起她。","options":[{"id":"key","text":"Grace was gradually out of sight, out of mind for some of her old classmates after she moved to another school.","reasonZh":"一些舊同學在格蕾絲轉校後漸漸淡忘她；沒有把「一些」擴大成所有人。","correct":true},{"id":"foil-1","text":"Grace was gradually out of sight, out of mind for all of her old classmates after she moved to another school.","reasonZh":"some 不等於 all；原文只涉及部分舊同學。","correct":false},{"id":"foil-2","text":"Grace was immediately out of sight, out of mind for some of her old classmates after she moved to another school.","reasonZh":"gradually 是漸漸，不是轉校當天立刻忘記。","correct":false},{"id":"foil-3","text":"Grace was gradually out of sight, out of mind for some of her old classmates before she moved to another school.","reasonZh":"淡忘發生在轉校之後，不能把先後次序倒轉。","correct":false}]},{"id":"proverb-01-q03","number":3,"promptEn":"Oliver’s homework note slipped under his books, so he completely forgot it.","promptZh":"奧利弗的功課便條滑到書本下面，因此他完全忘記了它。","options":[{"id":"key","text":"Once Oliver’s homework note slipped under his books, it was out of sight, out of mind for him.","reasonZh":"便條滑到書本下面，奧利弗因看不見而忘記；不是已完成了功課。","correct":true},{"id":"foil-1","text":"Once Oliver’s homework note slipped onto his open notebook, it was out of sight, out of mind for him.","reasonZh":"原文的便條被書遮住，不是落在打開的筆記本上。","correct":false},{"id":"foil-2","text":"Once Oliver’s homework note slipped under his books, it was out of sight, out of mind for his teacher.","reasonZh":"原文忘記事情的人是奧利弗，不是老師。","correct":false},{"id":"foil-3","text":"Once Oliver’s homework note slipped under his books, it was out of sight, out of mind because he had finished the homework for him.","reasonZh":"原文沒有完成作業的證據；忘記便條不能推出功課完成。","correct":false}]},{"id":"proverb-01-q04","number":4,"promptEn":"The parents put the sweets in the top cupboard, and the children stopped asking for them.","promptZh":"父母把糖果放到高櫃裏，孩子們便不再追問糖果。","options":[{"id":"key","text":"The parents put the sweets in the top cupboard, and the children stopped asking for them—out of sight, out of mind.","reasonZh":"糖果被父母收進高櫃，孩子不再追問；諺語描述的是注意力。","correct":true},{"id":"foil-1","text":"The parents put the sweets in the top cupboard, and the children finished eating them—out of sight, out of mind.","reasonZh":"不再追問不代表已經吃光；糖果仍在高櫃。","correct":false},{"id":"foil-2","text":"The parents put the sweets in the top cupboard, and the parents stopped asking for them—out of sight, out of mind.","reasonZh":"原文失去注意的是孩子，不是把糖果收起的父母。","correct":false},{"id":"foil-3","text":"The parents planned to put the sweets in the top cupboard, and the children stopped asking for them—out of sight, out of mind.","reasonZh":"題目說父母已經收起糖果，不只是計劃這樣做。","correct":false}]},{"id":"proverb-01-q05","number":5,"promptEn":"Chloe’s old family photo was put in a box. She soon stopped thinking about it.","promptZh":"克洛伊的舊家庭照片被放進盒子。她很快便不再想起它。","options":[{"id":"key","text":"Once the old family photo was put in a box, it became a case of out of sight, out of mind for Chloe.","reasonZh":"照片收進盒子後，克洛伊很快淡忘它；沒有說照片損壞。","correct":true},{"id":"foil-1","text":"Once the old family photo was put on the living-room wall, it became a case of out of sight, out of mind for Chloe.","reasonZh":"盒子令照片不在眼前；掛在牆上改變了關鍵情境。","correct":false},{"id":"foil-2","text":"Once the old family photo was put in a box, it became a case of out of sight, out of mind for everyone in the photo.","reasonZh":"題目只說克洛伊淡忘，沒有說照片中的所有人。","correct":false},{"id":"foil-3","text":"Once the old family photo was put in a box, its destruction became a case of out of sight, out of mind for Chloe.","reasonZh":"原文沒有照片被毀的情節，不能把收起當成毀掉。","correct":false}]},{"id":"proverb-01-q06","number":6,"promptEn":"The shop manager moved the broken chair to the back room and then forgot to repair it.","promptZh":"店舖經理把破椅子移到後房，之後便忘記修理它。","options":[{"id":"key","text":"The broken chair was out of sight, out of mind for the shop manager after he moved it to the back room and forgot to repair it.","reasonZh":"經理把破椅子移到後房後忘記維修；被忽略的工作仍未完成。","correct":true},{"id":"foil-1","text":"The broken chair was out of sight, out of mind for the shop manager after he moved it to the back room and finished repairing it.","reasonZh":"原文是忘記維修，不是維修完成；藏起來不等於解決問題。","correct":false},{"id":"foil-2","text":"The broken chair was out of sight, out of mind for the shop manager after he moved it to the front window and forgot to repair it.","reasonZh":"後房減少看見椅子的機會；前方櫥窗不是題目位置。","correct":false},{"id":"foil-3","text":"The broken chair was out of sight, out of mind for the manager because moving it to the back room made it safe to use.","reasonZh":"移到後房不會令破椅變安全；原文維修被忘記，並未完成。","correct":false}]},{"id":"proverb-01-q07","number":7,"promptEn":"The class poster was taken down, and most students stopped thinking about its message.","promptZh":"班級海報被取下後，大部分學生便不再想起海報上的訊息。","options":[{"id":"key","text":"Once the class poster was taken down, its message was out of sight, out of mind for most students.","reasonZh":"海報撤下後，大部分學生淡忘訊息；most 的範圍有保留。","correct":true},{"id":"foil-1","text":"Once the class poster was taken down, its message was out of sight, out of mind for every student.","reasonZh":"most 不保證每位學生都忘記。","correct":false},{"id":"foil-2","text":"Once the class poster was first displayed, its message was out of sight, out of mind for most students.","reasonZh":"原文的原因是撤下海報，不是首次展示。","correct":false},{"id":"foil-3","text":"Once the class poster was taken down, the whole subject they studied was out of sight, out of mind for most students.","reasonZh":"忘記海報訊息不等於忘掉整個學科。","correct":false}]},{"id":"proverb-01-q08","number":8,"promptEn":"Ethan moved an old email to another folder. A few days later, he forgot to reply.","promptZh":"伊森把一封舊電郵移到另一個資料夾。數天後，他忘記了回覆。","options":[{"id":"key","text":"Ethan moved the old email to another folder and forgot to reply a few days later—out of sight, out of mind.","reasonZh":"電郵移到別的資料夾後，伊森數天後忘記回覆；時間和未完成的責任都有交代。","correct":true},{"id":"foil-1","text":"Ethan moved the old email to another folder and forgot to reply before he moved it—out of sight, out of mind.","reasonZh":"忘記回覆在移動後數天發生，不是在移動前。","correct":false},{"id":"foil-2","text":"Ethan moved the old email to another folder and decided to refuse the request a few days later—out of sight, out of mind.","reasonZh":"忘記回覆不等於故意拒絕要求。","correct":false},{"id":"foil-3","text":"Ethan moved the old email to the top of his inbox and forgot to reply a few days later—out of sight, out of mind.","reasonZh":"原文是移到別的資料夾，不是置頂提高可見度。","correct":false}]},{"id":"proverb-01-q09","number":9,"promptEn":"Lily’s plant was hidden behind the curtain, so she forgot to water it.","promptZh":"莉莉的植物被窗簾遮住，因此她忘記了澆水。","options":[{"id":"key","text":"For Lily, the plant behind the curtain was out of sight, out of mind: she forgot to water it.","reasonZh":"窗簾擋住植物，莉莉因此忘記澆水；這是被遮住後忽略照顧。","correct":true},{"id":"foil-1","text":"For Lily, the plant behind the curtain was out of sight, out of mind: she chose to stop growing plants.","reasonZh":"題目只說忘記澆水，不是決定放棄種植物。","correct":false},{"id":"foil-2","text":"For Lily, the plant beside her daily reminder was out of sight, out of mind: she forgot to water it.","reasonZh":"植物藏在窗簾後，不是在每日提示旁。","correct":false},{"id":"foil-3","text":"For the gardener, the plant behind the curtain was out of sight, out of mind: she forgot to water it.","reasonZh":"原文是莉莉忘記，不能把責任換成園丁。","correct":false}]},{"id":"proverb-01-q10","number":10,"promptEn":"Many city residents never visit the distant village. They soon stopped paying attention to its rubbish problem.","promptZh":"許多城市居民從不到訪那個偏遠村莊。他們很快便不再關注當地的垃圾問題。","options":[{"id":"key","text":"The distant village’s rubbish problem was out of sight, out of mind for many city residents who never visit it: they soon stopped paying attention to it.","reasonZh":"許多居民從不去村莊，垃圾問題很快被忽略；問題本身並未因此消失。","correct":true},{"id":"foil-1","text":"The distant village’s rubbish problem was out of sight, out of mind for many city residents who never visit it: they soon had it completely cleared.","reasonZh":"居民停止關注不代表垃圾已清走。","correct":false},{"id":"foil-2","text":"The distant village’s rubbish problem was out of sight, out of mind for every city resident who never visit it: they soon stopped paying attention to it.","reasonZh":"many 是許多人，沒有足夠證據說全體居民。","correct":false},{"id":"foil-3","text":"The distant village’s rubbish problem was out of sight, out of mind for many city residents who regularly work there: they soon stopped paying attention to it.","reasonZh":"原文居民從不去村莊，並非定期在那裏工作。","correct":false}]},{"id":"proverb-01-q11","number":11,"promptEn":"Daniel often forgets food that is kept at the back of the fridge.","promptZh":"丹尼爾經常忘記放在雪櫃後方的食物。","options":[{"id":"key","text":"Food at the back of the fridge is often out of sight, out of mind for Daniel.","reasonZh":"雪櫃後方的食物常被丹尼爾忘記；often 表示經常而非每次。","correct":true},{"id":"foil-1","text":"Food at the back of the fridge is always out of sight, out of mind for Daniel.","reasonZh":"often 不等於 always；不要把常見傾向變成絕對。","correct":false},{"id":"foil-2","text":"Food on the dinner table is often out of sight, out of mind for Daniel.","reasonZh":"原文食物藏在雪櫃後方，不是在餐桌上。","correct":false},{"id":"foil-3","text":"Food at the back of the fridge is often out of sight, out of mind because it has all been eaten.","reasonZh":"原文是忘記食物，沒有說食物已全部吃掉。","correct":false}]},{"id":"proverb-01-q12","number":12,"promptEn":"Ava left her bicycle in the shed for months. She forgot about it until she found it again.","promptZh":"艾娃把單車放在小屋內數個月。她一直忘記了它，直至再次找到它。","options":[{"id":"key","text":"Left in the shed for months, the bicycle was out of sight, out of mind for Ava until she found it again.","reasonZh":"單車在小屋放了數個月，直到艾娃再找到才想起；保留終點 until。","correct":true},{"id":"foil-1","text":"Left in the shed for one afternoon, the bicycle was out of sight, out of mind for Ava until she found it again.","reasonZh":"原文明說數個月，不能縮成一個下午。","correct":false},{"id":"foil-2","text":"Left in the shed for months, the bicycle was out of sight, out of mind for Ava even after she found it again.","reasonZh":"until 表示再找到時情況改變，even after 卻說找到後仍忘記。","correct":false},{"id":"foil-3","text":"Left at the repair shop for months, the bicycle was out of sight, out of mind for Ava until she found it again.","reasonZh":"單車在小屋，不是在維修店；沒有送修的情節。","correct":false}]},{"id":"proverb-01-q13","number":13,"promptEn":"Marcus’s bill has been under a pile of papers, and he has forgotten to pay it.","promptZh":"馬庫斯的帳單一直放在一疊文件下面，而他已忘記繳付。","options":[{"id":"key","text":"Since the bill was placed under a pile of papers, it has been out of sight, out of mind for Marcus: he has forgotten to pay it.","reasonZh":"帳單被文件蓋住，馬庫斯忘了繳費；現在完成式連結過去與目前。","correct":true},{"id":"foil-1","text":"Since the bill was placed under a pile of papers, it has been out of sight, out of mind for Marcus: he has already paid it.","reasonZh":"忘記繳付與已繳清相反，藏起來不會消除帳項。","correct":false},{"id":"foil-2","text":"Since the bill was placed beside his payment reminder, it has been out of sight, out of mind for Marcus: he has forgotten to pay it.","reasonZh":"原文說被文件蓋住，並非擺在付款提示旁。","correct":false},{"id":"foil-3","text":"Before the bill was placed under a pile of papers, it has been out of sight, out of mind for Marcus: he has forgotten to pay it.","reasonZh":"Since 是自從收起之後；Before 把原因與結果次序倒轉。","correct":false}]},{"id":"proverb-01-q14","number":14,"promptEn":"I know I will forget the letter if I put it in a drawer.","promptZh":"我知道，如果把信放進抽屜，我便會忘記它。","options":[{"id":"key","text":"If I put the letter in a drawer, it will be out of sight, out of mind for me.","reasonZh":"把信放進抽屜是尚未實行的條件；will 對應說話者預期會忘記。","correct":true},{"id":"foil-1","text":"Whether or not I put the letter in a drawer, it will be out of sight, out of mind for me.","reasonZh":"原文把放進抽屜列為條件，沒有說不收起也必定忘記。","correct":false},{"id":"foil-2","text":"If I put the letter in a drawer, it has already been out of sight, out of mind for me.","reasonZh":"題目談將來的後果，不能說現在已經發生。","correct":false},{"id":"foil-3","text":"If I put the letter in a drawer, it will be out of sight, out of mind for the person who sent it.","reasonZh":"預計忘信的是收信的說話者，不是寄信的人。","correct":false}]},{"id":"proverb-01-q15","number":15,"promptEn":"I think much less about my phone while it is kept inside my bag during study.","promptZh":"溫習時把電話放在袋裏，我便較少想起它。","options":[{"id":"key","text":"With my phone inside my bag while I study, I think much less about it—out of sight, out of mind.","reasonZh":"溫習時收起電話讓說話者較少想起它；只限這個情境，並非戒掉電話。","correct":true},{"id":"foil-1","text":"With my phone inside my bag for the rest of my life, I think much less about it—out of sight, out of mind.","reasonZh":"原文只談溫習時，不能擴大為一生。","correct":false},{"id":"foil-2","text":"With my phone inside my bag while I study, I never use it again—out of sight, out of mind.","reasonZh":"較少想起不代表從此不用。","correct":false},{"id":"foil-3","text":"With my phone on my open textbook while I study, I think much less about it—out of sight, out of mind.","reasonZh":"收進袋內才是原文的行動，並不是放在打開的課本上。","correct":false}]},{"id":"proverb-01-q16","number":16,"promptEn":"A: Why do you keep the biscuits in a closed cupboard?\nB: I forget about them when I cannot see them.","promptZh":"甲：你為甚麼把餅乾放在關上的櫃子裏？\n乙：我看不見它們時，便會忘記它們。","options":[{"id":"key","text":"For me, biscuits in a closed cupboard are out of sight, out of mind.","reasonZh":"說話者看不見櫃裏的餅乾便忘記；不是因為不喜歡餅乾。","correct":true},{"id":"foil-1","text":"For me, biscuits on an open serving plate are out of sight, out of mind.","reasonZh":"題目強調關上的櫃子，改成敞開的餐碟會失去線索。","correct":false},{"id":"foil-2","text":"For every person, biscuits in a closed cupboard are out of sight, out of mind.","reasonZh":"說話者描述自己，沒有斷言所有人。","correct":false},{"id":"foil-3","text":"For me, biscuits in a closed cupboard are out of sight, out of mind because I dislike their taste.","reasonZh":"原文沒有不喜歡味道；不在眼前才是原因。","correct":false}]},{"id":"proverb-01-q17","number":17,"promptEn":"A: Why did the class forget the science project so quickly?\nB: Its display was removed from the hall.","promptZh":"甲：為甚麼全班這麼快便忘記了那個科學專題？\n乙：因為它的展覽已從大堂移走。","options":[{"id":"key","text":"After the display was removed from the hall, the science project was quickly forgotten by the class—out of sight, out of mind.","reasonZh":"專題展覽撤走後全班很快淡忘；並沒有說他們否定專題的價值。","correct":true},{"id":"foil-1","text":"After the display was moved into the classroom for daily use, the science project was quickly forgotten by the class—out of sight, out of mind.","reasonZh":"撤離大堂不等於轉放課室每天使用。","correct":false},{"id":"foil-2","text":"After the display was removed from the hall, every science lesson was quickly forgotten by the class—out of sight, out of mind.","reasonZh":"題目是某一個專題，不是所有科學課。","correct":false},{"id":"foil-3","text":"After the display was removed from the hall, the science project was deliberately rejected as useless by the class—out of sight, out of mind.","reasonZh":"忘記與刻意判定無用是不同心理行動。","correct":false}]},{"id":"proverb-01-q18","number":18,"promptEn":"The manager rarely checked the bottom drawer, so the files kept there were often forgotten.","promptZh":"經理很少檢查底層抽屜，因此放在裏面的文件經常被忘記。","options":[{"id":"key","text":"The manager rarely checked the bottom drawer, so the files there were often out of sight, out of mind.","reasonZh":"經理很少開底層抽屜，文件常被忘記；rarely 與 often 分別描述行動和後果。","correct":true},{"id":"foil-1","text":"The manager checked every morning the bottom drawer, so the files there were often out of sight, out of mind.","reasonZh":"題目說很少檢查，不是每天早上查看。","correct":false},{"id":"foil-2","text":"The manager rarely checked the bottom drawer, so the files there were invariably out of sight, out of mind.","reasonZh":"often 留有例外；invariably 卻表示每次都如此。","correct":false},{"id":"foil-3","text":"The manager rarely checked the desk surface, so the files there were often out of sight, out of mind.","reasonZh":"文件在底層抽屜，不是桌面上。","correct":false}]},{"id":"proverb-01-q19","number":19,"promptEn":"Ruby’s shopping list fell behind the desk. She has not thought about it since then.","promptZh":"露比的購物清單掉到書桌後面。自此之後，她便沒有再想起它。","options":[{"id":"key","text":"The shopping list has been out of sight, out of mind for Ruby since it fell behind the desk.","reasonZh":"清單掉到桌後至今都沒再被露比想起；since 保留持續至今的意思。","correct":true},{"id":"foil-1","text":"The shopping list will first become out of sight, out of mind for Ruby since it fell behind the desk.","reasonZh":"原文已持續一段時間，不是將來才開始。","correct":false},{"id":"foil-2","text":"The shopping list has been out of sight, out of mind for Ruby since Ruby finished buying everything.","reasonZh":"原文是清單掉到桌後，沒有完成購物的資訊。","correct":false},{"id":"foil-3","text":"The shopping list has been out of sight, out of mind for the shop assistant since it fell behind the desk.","reasonZh":"沒有店員忘記清單的情節；焦點是露比。","correct":false}]},{"id":"proverb-01-q20","number":20,"promptEn":"The staff may forget the notice if it is removed from the wall.","promptZh":"如果通告從牆上移走，員工可能會忘記它。","options":[{"id":"key","text":"Unless the notice stays on the wall, it may become a case of out of sight, out of mind for the staff.","reasonZh":"通告若撤下，員工可能忘記；may 保留風險而不是斷言。","correct":true},{"id":"foil-1","text":"Unless the notice stays on the wall, it will certainly become a case of out of sight, out of mind for the staff.","reasonZh":"may 是可能，certainly 把未確定的結果說成必然。","correct":false},{"id":"foil-2","text":"If the notice stays on the wall, it may become a case of out of sight, out of mind for the staff.","reasonZh":"Unless 表示若不留在牆上；If 把條件倒轉。","correct":false},{"id":"foil-3","text":"Unless the notice stays on the wall, it may become a case of out of sight, out of mind for all visitors.","reasonZh":"題目談員工，沒有對所有訪客作判斷。","correct":false}]},{"id":"proverb-01-q21","number":21,"promptEn":"A: Do your old teammates still send you messages?\nB: Not often. Since I left the club, they seem to have forgotten me.","promptZh":"甲：你的舊隊友仍然會傳訊息給你嗎？\n乙：不常會。我離開球會後，他們似乎已把我忘記。","options":[{"id":"key","text":"Since I left the club, I seem to be out of sight, out of mind for my old teammates.","reasonZh":"說話者離隊後覺得舊隊友似乎淡忘自己；seem 保留推測。","correct":true},{"id":"foil-1","text":"Since I left the club, I have proved that I am out of sight, out of mind for my old teammates.","reasonZh":"seem 並不是已經證明；題目只給訊息變少的跡象。","correct":false},{"id":"foil-2","text":"Before I joined the club, I seem to be out of sight, out of mind for my old teammates.","reasonZh":"情境是離隊以後，不是加入之前。","correct":false},{"id":"foil-3","text":"Since I left the club, I seem to be out of sight, out of mind for my new teammates.","reasonZh":"題目問舊隊友，不是新隊友。","correct":false}]},{"id":"proverb-01-q22","number":22,"promptEn":"After I turned off the application’s notifications, I stopped thinking about opening it.","promptZh":"我關掉應用程式的通知後，便不再想起要打開它。","options":[{"id":"key","text":"I stopped thinking about opening it after I turned off its notifications: for me, the app was out of sight, out of mind.","reasonZh":"關閉通知後不再想起打開應用程式；取消提醒不代表刪除帳戶。","correct":true},{"id":"foil-1","text":"I stopped thinking about opening it after I deleted my account permanently: for me, the app was out of sight, out of mind.","reasonZh":"原文只關通知，沒有永久刪除帳戶。","correct":false},{"id":"foil-2","text":"I found that it had stopped working after I turned off its notifications: for me, the app was out of sight, out of mind.","reasonZh":"不再想起使用，不等於程式故障。","correct":false},{"id":"foil-3","text":"I stopped thinking about opening it before I turned off its notifications: for me, the app was out of sight, out of mind.","reasonZh":"原文先關閉通知，之後才不再想起打開。","correct":false}]},{"id":"proverb-01-q23","number":23,"promptEn":"The customer’s complaint was filed away. The manager then stopped thinking about it.","promptZh":"顧客的投訴被歸檔後，經理便不再想起它。","options":[{"id":"key","text":"Once the customer’s complaint was filed away, it became a case of out of sight, out of mind for the manager.","reasonZh":"投訴被歸檔後經理不再理會；歸檔並不能證明投訴已解決。","correct":true},{"id":"foil-1","text":"Once the customer’s complaint was resolved to the customer's satisfaction, it became a case of out of sight, out of mind for the manager.","reasonZh":"題目沒有顧客滿意或問題解決的證據。","correct":false},{"id":"foil-2","text":"Once the customer’s complaint was filed away, it became a case of out of sight, out of mind for the customer.","reasonZh":"原文失去關注的是經理，不能推斷顧客忘記。","correct":false},{"id":"foil-3","text":"Once the customer’s complaint was filed away, it had never been a case of out of sight, out of mind for the manager.","reasonZh":"原文正是描述歸檔後被忽略，never 否定了這個結果。","correct":false}]},{"id":"proverb-01-q24","number":24,"promptEn":"A: Why was Ben’s library book returned late?\nB: It fell behind the shelf, and he forgot about it.","promptZh":"甲：為甚麼本遲了歸還圖書館書籍？\n乙：那本書掉到書架後面，而他忘記了它。","options":[{"id":"key","text":"The library book was out of sight, out of mind for Ben after it fell behind the shelf, so he returned it late.","reasonZh":"書掉到書架後，本忘了它而遲還；保留遲還這個後果。","correct":true},{"id":"foil-1","text":"The library book was out of sight, out of mind for Ben after it fell behind the shelf, so he renewed it on time.","reasonZh":"原文說遲還，沒有準時續借。","correct":false},{"id":"foil-2","text":"The library book was out of sight, out of mind for Ben after it was displayed on the shelf, so he returned it late.","reasonZh":"書掉在後方，不是陳列在層架上。","correct":false},{"id":"foil-3","text":"The library book was out of sight, out of mind for the librarian after it fell behind the shelf, so he returned it late.","reasonZh":"本是忘記書的人，題目沒有說圖書館員也忘記。","correct":false}]},{"id":"proverb-01-q25","number":25,"promptEn":"Harper does not think about her winter clothes during summer because they are kept in the top cupboard.","promptZh":"夏天時，哈珀不會想起放在高櫃裏的冬季衣物。","options":[{"id":"key","text":"Winter clothes in the top cupboard are out of sight, out of mind for Harper during summer.","reasonZh":"冬衣在高櫃裏，夏天時哈珀不會想起；季節限制是重要線索。","correct":true},{"id":"foil-1","text":"Winter clothes in the top cupboard are out of sight, out of mind for Harper throughout winter.","reasonZh":"原文限定夏天，不是冬天。","correct":false},{"id":"foil-2","text":"All her clothes in the top cupboard are out of sight, out of mind for Harper during summer.","reasonZh":"只涉及冬衣，不是全部衣服。","correct":false},{"id":"foil-3","text":"Winter clothes laid out for tomorrow are out of sight, out of mind for Harper during summer.","reasonZh":"衣物收在高櫃，並非為明天穿着而攤開。","correct":false}]},{"id":"proverb-01-q26","number":26,"promptEn":"Visitors cannot see the litter behind the beach wall, so they rarely think about the problem.","promptZh":"遊客看不到海灘圍牆後的垃圾，因此很少想起這個問題。","options":[{"id":"key","text":"With the litter behind the beach wall out of sight, out of mind, visitors rarely think about the problem.","reasonZh":"圍牆遮住垃圾，遊客很少想到問題；垃圾沒有因看不見而消失。","correct":true},{"id":"foil-1","text":"With the litter behind the beach wall out of sight, out of mind, visitors know the problem has been solved.","reasonZh":"少想起不代表知道問題已解決。","correct":false},{"id":"foil-2","text":"With the litter on the main beach path out of sight, out of mind, visitors rarely think about the problem.","reasonZh":"垃圾藏在圍牆後，不是在主要步道上。","correct":false},{"id":"foil-3","text":"With the litter behind the beach wall out of sight, out of mind, the cleaning staff rarely think about the problem.","reasonZh":"題目談遊客的注意力，不能改成清潔人員。","correct":false}]},{"id":"proverb-01-q27","number":27,"promptEn":"A: Why did you put the game controller in the drawer?\nB: I do not want to think about playing games while I revise.","promptZh":"甲：你為甚麼把遊戲手掣放進抽屜？\n乙：溫習時，我不想經常想着玩遊戲。","options":[{"id":"key","text":"I hope the controller will be out of sight, out of mind in the drawer while I revise.","reasonZh":"把手掣收起是為了減少溫習時的誘惑；希望達到的效果不能寫成已證實。","correct":true},{"id":"foil-1","text":"I have proved the controller will be out of sight, out of mind in the drawer while I revise.","reasonZh":"原文只說目的，沒有證明計劃成功。","correct":false},{"id":"foil-2","text":"I hope the controller will be out of sight, out of mind in the drawer after I finish revising.","reasonZh":"原文想減少溫習期間的分心，不是溫習之後。","correct":false},{"id":"foil-3","text":"I hope the controller will be out of sight, out of mind on top of my notes while I revise.","reasonZh":"收在抽屜裏，不是放在筆記上。","correct":false}]},{"id":"proverb-01-q28","number":28,"promptEn":"Even after Priya moved abroad, Sam called her every week and never forgot her.","promptZh":"即使普莉雅搬到外國，森姆仍每星期致電給她，從沒有忘記她。","options":[{"id":"key","text":"Sam called Priya every week and never forgot her: her move abroad did not mean out of sight, out of mind for him.","reasonZh":"森姆每週聯絡而從未忘記普莉雅；這是諺語不適用的反例。","correct":true},{"id":"foil-1","text":"Sam called Priya every week and gradually forgot her: her move abroad did not mean out of sight, out of mind for him.","reasonZh":"原文明說 never forgot，不能改成逐漸忘記。","correct":false},{"id":"foil-2","text":"Sam called Priya only once a year and never forgot her: her move abroad did not mean out of sight, out of mind for him.","reasonZh":"題目是每星期致電，不是每年一次。","correct":false},{"id":"foil-3","text":"Sam called Priya every week and never forgot her: her move abroad inevitably meant out of sight, out of mind for him.","reasonZh":"這個例子證明不一定淡忘；inevitably 反而說必然淡忘。","correct":false}]},{"id":"proverb-01-q29","number":29,"promptEn":"After the warning sign was removed, the building manager forgot about the unfinished repair.","promptZh":"警告牌被移走後，大廈經理忘記了尚未完成的維修。","options":[{"id":"key","text":"The unfinished repair was out of sight, out of mind for the building manager once the warning sign was removed.","reasonZh":"告示撤走令未完成的維修被經理忘記；未完成是必要限制。","correct":true},{"id":"foil-1","text":"The completed repair was out of sight, out of mind for the building manager once the warning sign was removed.","reasonZh":"原文維修尚未完成，不能改成已完成。","correct":false},{"id":"foil-2","text":"The unfinished repair was out of sight, out of mind for the building manager once daily warning notices began.","reasonZh":"題目是撤下提醒，不是開始每天提醒。","correct":false},{"id":"foil-3","text":"The unfinished repair was out of sight, out of mind for every resident once the warning sign was removed.","reasonZh":"只知道經理忘記，不能推斷每位住戶。","correct":false}]},{"id":"proverb-01-q30","number":30,"promptEn":"The teacher said the pupils stopped thinking about their reading logs after the books were put away.","promptZh":"老師說，閱讀紀錄冊被收起後，學生便不再想起它們。","options":[{"id":"key","text":"The teacher said that once the reading logs were put away, they were out of sight, out of mind for the pupils.","reasonZh":"保留老師轉述：收起閱讀紀錄冊後，是學生不再想起它們。","correct":true},{"id":"foil-1","text":"The teacher said that once the reading logs were put away, they were out of sight, out of mind for the teacher.","reasonZh":"老師是報告情況的人，忘記的是學生。","correct":false},{"id":"foil-2","text":"The teacher said that while the reading logs were being used each morning, they were out of sight, out of mind for the pupils.","reasonZh":"題目是收起後，不是每天早上使用期間。","correct":false},{"id":"foil-3","text":"The pupils proved that once the reading logs were put away, they were out of sight, out of mind for the pupils.","reasonZh":"原文是老師轉述，不是學生提出證明。","correct":false}]},{"id":"proverb-01-q31","number":31,"promptEn":"Although Olivia meant to reply, newer messages covered the message and she soon forgot it.","promptZh":"雖然奧莉維亞本來打算回覆，但較新的訊息把它蓋過，她很快便忘記了。","options":[{"id":"key","text":"Although Olivia meant to reply, the message was soon out of sight, out of mind for her after newer messages covered it.","reasonZh":"奧莉維亞本想回覆，但新訊息把舊訊息蓋住，她很快忘記；有意回覆與忘記可以並存。","correct":true},{"id":"foil-1","text":"Although Olivia intended to ignore the sender, the message was soon out of sight, out of mind for her after newer messages covered it.","reasonZh":"原文說她打算回覆，不是刻意無視對方。","correct":false},{"id":"foil-2","text":"Although Olivia meant to reply, the message was soon out of sight, out of mind for her after she pinned it to the top.","reasonZh":"新訊息掩蓋它，不是她把它置頂。","correct":false},{"id":"foil-3","text":"Although Olivia meant to reply, the message was only after several years out of sight, out of mind for her after newer messages covered it.","reasonZh":"原文 soon，不能拖成數年後。","correct":false}]},{"id":"proverb-01-q32","number":32,"promptEn":"The spare keys were kept in a box at the back of the cupboard, so the family forgot where they were.","promptZh":"後備鎖匙放在櫃子深處的盒子裏，因此家人忘記了它們的位置。","options":[{"id":"key","text":"With the spare keys in a box at the back of the cupboard, the family forgot where they were—out of sight, out of mind.","reasonZh":"鎖匙收在櫃子深處的盒子，家人忘記位置；沒有證據指鎖匙已丟掉。","correct":true},{"id":"foil-1","text":"With the spare keys in a box at the back of the cupboard, the family threw them away—out of sight, out of mind.","reasonZh":"忘記位置不等於丟掉物件。","correct":false},{"id":"foil-2","text":"With the spare keys in a box beside the front-door handle, the family forgot where they were—out of sight, out of mind.","reasonZh":"原文的位置不常看見，不是門把旁。","correct":false},{"id":"foil-3","text":"With the spare keys in a box at the back of the cupboard, the landlord forgot where they were—out of sight, out of mind.","reasonZh":"原文是家人忘記，不是業主。","correct":false}]},{"id":"proverb-01-q33","number":33,"promptEn":"The family cares for the front garden every week, but they often forget the small garden behind the house because they rarely see it.","promptZh":"家人每星期都照顧前花園，但因為很少看見屋後的小花園，所以經常忘記它。","options":[{"id":"key","text":"The front garden gets care every week, but the small garden behind the house is often out of sight, out of mind for the family.","reasonZh":"前花園每週受照顧，屋後小花園卻常被忽略；兩者不能混為一談。","correct":true},{"id":"foil-1","text":"The front garden gets care once a year, but the small garden behind the house is often out of sight, out of mind for the family.","reasonZh":"原文前花園每週有人照顧，不是每年一次。","correct":false},{"id":"foil-2","text":"The front garden gets care every week, but the small garden behind the house is always out of sight, out of mind for the family.","reasonZh":"often 不等於毫無例外地每次。","correct":false},{"id":"foil-3","text":"The front garden gets care every week, but the well-kept front garden is often out of sight, out of mind for the family.","reasonZh":"被忽略的是屋後花園，不是受照顧的前花園。","correct":false}]},{"id":"proverb-01-q34","number":34,"promptEn":"A: Why did passengers stop using the lost-property form?\nB: It disappeared from the station website.","promptZh":"甲：為甚麼乘客不再使用失物申報表格？\n乙：因為它從車站網站消失了。","options":[{"id":"key","text":"The form disappeared from the station website and passengers stopped using it, but this alone does not prove it was out of sight, out of mind.","reasonZh":"表格不再可用只能證明使用停止，未足以證明乘客已忘記；這題刻意檢查證據界線。","correct":true},{"id":"foil-1","text":"The form disappeared from the station website and passengers stopped using it, but this alone proves it was out of sight, out of mind.","reasonZh":"無法使用也會令使用量歸零，不能直接證明忘記。","correct":false},{"id":"foil-2","text":"The form remained on the station website and passengers stopped using it, but this alone does not prove it was out of sight, out of mind.","reasonZh":"原文表格已從網站消失，不是一直保留。","correct":false},{"id":"foil-3","text":"The form disappeared from the station website and passengers kept submitting it daily, but this alone does not prove it was out of sight, out of mind.","reasonZh":"原文明說乘客停止使用，不能改為每天提交。","correct":false}]},{"id":"proverb-01-q35","number":35,"promptEn":"The managers regularly visited the main office. Workers in the far office rarely received calls and felt forgotten.","promptZh":"經理經常到訪主要辦公室。偏遠辦公室的員工很少收到來電，並感到被遺忘。","options":[{"id":"key","text":"The managers regularly visited the main office, but distant workers rarely received calls and seemed to be out of sight, out of mind.","reasonZh":"主辦公室獲常探訪，遠處員工少收來電而感到被忘記；seemed 避免替經理斷言內心。","correct":true},{"id":"foil-1","text":"The managers regularly visited the main office, but distant workers rarely received calls and were proved to be out of sight, out of mind.","reasonZh":"題目給員工的感受，不是對經理內心的證明。","correct":false},{"id":"foil-2","text":"The managers regularly visited the main office, but distant workers received calls every day and seemed to be out of sight, out of mind.","reasonZh":"原文很少接到電話，不是每天接到。","correct":false},{"id":"foil-3","text":"The managers regularly visited both offices, but distant workers rarely received calls and seemed to be out of sight, out of mind.","reasonZh":"經理常去的是主辦公室，不能擴大到兩間。","correct":false}]},{"id":"proverb-01-q36","number":36,"promptEn":"People living far away may stop thinking about the flood problem if they receive no regular updates.","promptZh":"如果沒有收到定期更新，住在遠方的人可能會不再想起水災問題。","options":[{"id":"key","text":"Without regular updates, the flood problem could become a case of out of sight, out of mind for people living far away.","reasonZh":"沒有定期消息，遠方的人可能淡忘水災；could 保留未確定性。","correct":true},{"id":"foil-1","text":"Without regular updates, the flood problem has certainly become a case of out of sight, out of mind for people living far away.","reasonZh":"可能發生不等於已確實發生。","correct":false},{"id":"foil-2","text":"With frequent personal reminders, the flood problem could become a case of out of sight, out of mind for people living far away.","reasonZh":"缺少更新才是題目條件，不是頻繁收到個人提醒。","correct":false},{"id":"foil-3","text":"Without regular updates, every problem in the country could become a case of out of sight, out of mind for people living far away.","reasonZh":"原文只談水災，不是全國所有問題。","correct":false}]},{"id":"proverb-01-q37","number":37,"promptEn":"Mr Wong may forget his daily medicine if the reminder card is removed.","promptZh":"如果提示卡被移走，黃先生可能會忘記每天服藥。","options":[{"id":"key","text":"If the reminder card is removed, Mr Wong’s daily medicine may become a case of out of sight, out of mind.","reasonZh":"提示卡若被撤下，黃先生可能忘記每天服藥；不是藥物失效。","correct":true},{"id":"foil-1","text":"If the reminder card is removed, Mr Wong’s daily medicine must already be a case of out of sight, out of mind.","reasonZh":"may 表示可能；must already 把風險改成已發生的確定事實。","correct":false},{"id":"foil-2","text":"If the reminder card is removed, Mr Wong’s weekly hospital appointment may become a case of out of sight, out of mind.","reasonZh":"題目是每日服藥，不是每週覆診。","correct":false},{"id":"foil-3","text":"Even if the reminder card is checked each morning, Mr Wong’s daily medicine may become a case of out of sight, out of mind.","reasonZh":"原文的條件是移走提示卡，不是每天查看提示卡。","correct":false}]},{"id":"proverb-01-q38","number":38,"promptEn":"A: Will I forget my old neighbours after I move away?\nB: Not necessarily. You can continue calling them.","promptZh":"甲：我搬走後，會不會忘記以前的鄰居？\n乙：不一定。你可以繼續致電給他們。","options":[{"id":"key","text":"Moving away does not have to mean out of sight, out of mind if you stay in contact.","reasonZh":"搬走不必然淡忘鄰居；保持聯絡能抵抗這種傾向。","correct":true},{"id":"foil-1","text":"Moving away always means out of sight, out of mind if you stay in contact.","reasonZh":"原文 not necessarily 明確否定必然淡忘。","correct":false},{"id":"foil-2","text":"Moving away does not have to mean out of sight, out of mind because contact is impossible.","reasonZh":"對話建議繼續致電，並非聯絡不可能。","correct":false},{"id":"foil-3","text":"Deliberately ending every friendship does not have to mean out of sight, out of mind if you stay in contact.","reasonZh":"搬家與故意結束所有友誼不是一回事。","correct":false}]},{"id":"proverb-01-q39","number":39,"promptEn":"The children forgot the toys at the back of the cupboard until they cleaned the room.","promptZh":"孩子們忘記了櫃子後方的玩具，直至他們整理房間。","options":[{"id":"key","text":"The toys at the back of the cupboard were out of sight, out of mind until the children cleaned the room.","reasonZh":"玩具一直被忘到整理房間才重現注意；until 是狀態結束點。","correct":true},{"id":"foil-1","text":"The toys at the back of the cupboard were out of sight, out of mind even after the children found them while cleaning.","reasonZh":"原文整理房間時才想起，不是找到後仍忘記。","correct":false},{"id":"foil-2","text":"The toys in the children's hands were out of sight, out of mind until the children cleaned the room.","reasonZh":"玩具收在櫃子後方，不是在手上。","correct":false},{"id":"foil-3","text":"All their possessions at the back of the cupboard were out of sight, out of mind until the children cleaned the room.","reasonZh":"題目只談那些玩具，不是孩子全部物品。","correct":false}]},{"id":"proverb-01-q40","number":40,"promptEn":"The reporter said that city residents often ignore problems in small villages because they never see them.","promptZh":"記者表示，城市居民因為從未看見小村莊的問題，所以經常忽略它們。","options":[{"id":"key","text":"The reporter said that village problems can be out of sight, out of mind for city residents who never see them and often ignore them.","reasonZh":"記者指出城市居民常忽略沒看過的村莊問題；注意力不足不等於問題不存在。","correct":true},{"id":"foil-1","text":"The reporter said that village problems can be out of sight, out of mind for city residents who never see them and have completely solved them.","reasonZh":"忽略問題不是解決問題。","correct":false},{"id":"foil-2","text":"The reporter said that village problems can be out of sight, out of mind for city residents who inspect them every week and often ignore them.","reasonZh":"原文從未看見，不是每星期實地檢查。","correct":false},{"id":"foil-3","text":"The reporter denied that village problems can be out of sight, out of mind for city residents who never see them and often ignore them.","reasonZh":"原文記者作出這個觀察，並沒有否認。","correct":false}]},{"id":"proverb-01-q41","number":41,"promptEn":"After the school moved the suggestion box behind a door, the staff stopped checking the pupils’ ideas.","promptZh":"學校把意見箱移到門後後，員工便不再查看學生的意見。","options":[{"id":"key","text":"Once the suggestion box was moved behind a door, pupils’ ideas were out of sight, out of mind: the staff stopped checking them.","reasonZh":"意見箱移到門後，員工不再看學生建議；不是學生停止提出建議。","correct":true},{"id":"foil-1","text":"Once the suggestion box was moved behind a door, pupils’ ideas were out of sight, out of mind: the pupils stopped having ideas.","reasonZh":"原文停止的是員工查看，不是學生思考。","correct":false},{"id":"foil-2","text":"Once the suggestion box was moved at the reception counter, pupils’ ideas were out of sight, out of mind: the staff stopped checking them.","reasonZh":"原文移到門後，不是接待處當眼位置。","correct":false},{"id":"foil-3","text":"Once the suggestion box was moved behind a door, staff salaries were out of sight, out of mind: the staff stopped checking them.","reasonZh":"題目被忽略的是學生意見，並非員工薪金。","correct":false}]},{"id":"proverb-01-q42","number":42,"promptEn":"A: Why does the night team feel forgotten?\nB: The managers visit only during the day and hardly ever see them.","promptZh":"甲：為甚麼夜班團隊覺得自己被遺忘？\n乙：經理只在日間到訪，幾乎從不見到他們。","options":[{"id":"key","text":"The night team feels forgotten and can be out of sight, out of mind for managers who visit only during the day.","reasonZh":"只在日間探訪的經理很少見夜班，夜班因而感到被忘記；沒有判斷工作質素。","correct":true},{"id":"foil-1","text":"The night team feels forgotten and can be out of sight, out of mind for managers who meet the night team every evening.","reasonZh":"原文經理只在日間到訪，幾乎見不到夜班。","correct":false},{"id":"foil-2","text":"The night team has stopped doing its work and can be out of sight, out of mind for managers who visit only during the day.","reasonZh":"感到被遺忘不等於停止工作。","correct":false},{"id":"foil-3","text":"The night team feels forgotten and is guaranteed to be out of sight, out of mind for managers who visit only during the day.","reasonZh":"can 表示可能適用，不能保證所有這類經理都忘記夜班。","correct":false}]},{"id":"proverb-01-q43","number":43,"promptEn":"Zoe removed the shopping application from her home screen, and she then thought less often about online shopping.","promptZh":"佐伊把購物應用程式從主畫面移除，之後便較少想起網上購物。","options":[{"id":"key","text":"Zoe thought less often about shopping after she removed the app from her home screen—out of sight, out of mind.","reasonZh":"佐伊移除主畫面的圖示後較少想起購物；不是購物程式已刪除。","correct":true},{"id":"foil-1","text":"Zoe thought less often about shopping after she removed the app from every device she owns—out of sight, out of mind.","reasonZh":"原文只移除主畫面圖示，沒說從所有裝置刪除。","correct":false},{"id":"foil-2","text":"Zoe lost the ability to shop online after she removed the app from her home screen—out of sight, out of mind.","reasonZh":"較少想起與不能上網購物不同。","correct":false},{"id":"foil-3","text":"Zoe thought less often about shopping long before she removed the app from her home screen—out of sight, out of mind.","reasonZh":"題目先移除圖示，之後才較少想起購物。","correct":false}]},{"id":"proverb-01-q44","number":44,"promptEn":"The safety notice was taken down, and the workers forgot about the loose step. Someone later nearly fell.","promptZh":"安全告示被取下後，工人忘記了鬆脫的梯級。其後有人差點跌倒。","options":[{"id":"key","text":"Once the safety notice was taken down, the loose step was out of sight, out of mind for the workers until someone nearly fell.","reasonZh":"告示撤下後工人忘記鬆脫梯級，直到有人差點跌倒；危險仍在。","correct":true},{"id":"foil-1","text":"Once the safety notice was taken down, the loose step was out of sight, out of mind for the workers until someone fell and broke a leg.","reasonZh":"差點跌倒並不等於跌斷腿，不能增加傷勢。","correct":false},{"id":"foil-2","text":"Once the safety notice was taken down, the newly repaired step was out of sight, out of mind for the workers until someone nearly fell.","reasonZh":"原文仍是鬆脫的梯級，不是剛修好的梯級。","correct":false},{"id":"foil-3","text":"While staff checked the safety notice daily, the loose step was out of sight, out of mind for the workers until someone nearly fell.","reasonZh":"原文撤走提醒，不是員工每天查看告示。","correct":false}]},{"id":"proverb-01-q45","number":45,"promptEn":"Aaron moved away and rarely appeared in the group chat. Some friends gradually stopped thinking about him.","promptZh":"亞倫搬走後，很少在群組對話出現。一些朋友逐漸不再想起他。","options":[{"id":"key","text":"For some of his friends, Aaron was gradually out of sight, out of mind after he moved and rarely appeared in the group chat.","reasonZh":"亞倫搬走且少在群組出現，一些朋友漸忘他；some 和 gradually 都重要。","correct":true},{"id":"foil-1","text":"For all his friends, Aaron was gradually out of sight, out of mind after he moved and rarely appeared in the group chat.","reasonZh":"some 只指一部分朋友。","correct":false},{"id":"foil-2","text":"For some of his friends, Aaron was instantly out of sight, out of mind after he moved and rarely appeared in the group chat.","reasonZh":"gradually 是逐漸，不是瞬間。","correct":false},{"id":"foil-3","text":"For some of his friends, Aaron was gradually out of sight, out of mind after he moved and posted every hour in the group chat.","reasonZh":"原文很少在群組出現，不是每小時發訊息。","correct":false}]},{"id":"proverb-01-q46","number":46,"promptEn":"The charity must continue sharing updates, or its supporters may forget the families it helps.","promptZh":"慈善機構必須繼續發放最新消息，否則支持者可能會忘記受助家庭。","options":[{"id":"key","text":"Unless the charity keeps sharing updates, the families it helps may become out of sight, out of mind for its supporters.","reasonZh":"慈善機構若不持續更新，受助家庭可能被支持者淡忘；是預防風險。","correct":true},{"id":"foil-1","text":"Unless the charity keeps sharing updates, the families it helps are certain to become out of sight, out of mind for its supporters.","reasonZh":"may 是風險，並非確定結果。","correct":false},{"id":"foil-2","text":"Whenever the charity shares an update, the families it helps may become out of sight, out of mind for its supporters.","reasonZh":"原文缺少更新才有風險，不是每次更新都引致淡忘。","correct":false},{"id":"foil-3","text":"Unless the charity keeps sharing updates, the families it helps may become out of sight, out of mind for the families themselves.","reasonZh":"可能忘記受助家庭的是支持者，不是家庭忘記自己。","correct":false}]},{"id":"proverb-01-q47","number":47,"promptEn":"A: Once the boxes are moved into storage, will the manager remember to search for the missing items?\nB: Maybe not. He rarely thinks about things he cannot see.","promptZh":"甲：箱子移到貨倉後，經理仍會記得尋找遺失物品嗎？\n乙：可能不會。他很少想起自己看不到的東西。","options":[{"id":"key","text":"The missing items may become a case of out of sight, out of mind for the manager once the boxes are in storage, so he might not remember to search for them.","reasonZh":"箱子入倉後，經理可能不再想起搜尋失物；may 保留對話的 maybe not。","correct":true},{"id":"foil-1","text":"The missing items will definitely become a case of out of sight, out of mind for the manager once the boxes are in storage, so he might not remember to search for them.","reasonZh":"原文 maybe not，不能改成肯定忘記。","correct":false},{"id":"foil-2","text":"The missing items may become a case of out of sight, out of mind for the manager before the boxes are moved, so he might not remember to search for them.","reasonZh":"原文預測入倉後的風險，不是搬動前。","correct":false},{"id":"foil-3","text":"The missing items may become a case of out of sight, out of mind for the manager once the boxes are in storage, so he might not remember having found them all.","reasonZh":"題目問是否記得尋找，並沒有已找齊失物的事實。","correct":false}]},{"id":"proverb-01-q48","number":48,"promptEn":"Some people miss their friends more when they are away, but other people slowly forget them.","promptZh":"有些人在朋友不在身邊時會更加掛念他們，但另一些人則會逐漸忘記他們。","options":[{"id":"key","text":"Some people miss absent friends more, but for others, absence means out of sight, out of mind as they slowly forget them.","reasonZh":"有些人更思念遠方朋友，另一些人逐漸淡忘；諺語只描述後者。","correct":true},{"id":"foil-1","text":"Some people miss absent friends more, but for everyone, absence means out of sight, out of mind as they slowly forget them.","reasonZh":"原文特別區分兩類人，不是所有人都淡忘。","correct":false},{"id":"foil-2","text":"Some people always forget absent friends immediately, but for others, absence means out of sight, out of mind as they slowly forget them.","reasonZh":"原文第一類人更思念朋友，改成即時忘記會抹掉對比。","correct":false},{"id":"foil-3","text":"Some people miss absent friends more, but for others, absence means out of sight, out of mind as they overnight forget them.","reasonZh":"原文 gradually/slowly，並非一夜之間。","correct":false}]},{"id":"proverb-01-q49","number":49,"promptEn":"A community worker warned that older neighbours who rarely leave home may gradually be forgotten by other local residents.","promptZh":"一名社區工作者警告，甚少外出的年長鄰居可能會逐漸被其他居民遺忘。","options":[{"id":"key","text":"The community worker warned that older neighbours who rarely leave home may gradually be forgotten—out of sight, out of mind for other residents.","reasonZh":"社區工作者警告少出門的長者可能漸被鄰里忘記；這是關注風險，不是責怪長者。","correct":true},{"id":"foil-1","text":"The community worker warned that older neighbours who rarely leave home have all been completely forgotten—out of sight, out of mind for other residents.","reasonZh":"可能逐漸發生不能改成所有人已被完全忘記。","correct":false},{"id":"foil-2","text":"The community worker warned that older neighbours who organise daily neighbourhood meetings may gradually be forgotten—out of sight, out of mind for other residents.","reasonZh":"原文是甚少外出，並非每天組織鄰里聚會。","correct":false},{"id":"foil-3","text":"The community worker celebrated that older neighbours who rarely leave home may gradually be forgotten—out of sight, out of mind for other residents.","reasonZh":"原文是警告風險，不是慶祝被忽略。","correct":false}]},{"id":"proverb-01-q50","number":50,"promptEn":"The families were still fixing their homes after the flood. However, when the flood disappeared from the news, many people stopped thinking about them.","promptZh":"水災後，這些家庭仍在修理房屋。然而，當水災不再出現在新聞後，許多人便不再想起他們。","options":[{"id":"key","text":"Even though the families were still fixing their homes, they were soon out of sight, out of mind for many people once the flood disappeared from the news.","reasonZh":"新聞停報後人們淡忘災民，但他們仍在修房；看不見不等於需要消失。","correct":true},{"id":"foil-1","text":"Even though the families were finished all repairs, they were soon out of sight, out of mind for many people once the flood disappeared from the news.","reasonZh":"原文維修仍在進行，不是全部完成。","correct":false},{"id":"foil-2","text":"Even though the families were still fixing their homes, they were soon out of sight, out of mind for every neighbour once the flood disappeared from the news.","reasonZh":"many 不等於每一位鄰居，原文也未限於鄰居。","correct":false},{"id":"foil-3","text":"Even though the families were still fixing their homes, they were soon out of sight, out of mind for many people while daily reports kept showing their needs.","reasonZh":"題目是新聞停止報道，不是每天報道需要。","correct":false}]},{"id":"proverb-01-x01","number":51,"theme":"space","promptEn":"After a satellite stopped sending images of a storm, viewers gradually forgot it, although the storm continued.","promptZh":"衛星停止傳回風暴影像後，觀眾逐漸淡忘風暴，但風暴仍在持續。","options":[{"id":"key","text":"Without the satellite images, the storm became out of sight, out of mind for viewers who gradually forgot it, though it was still active.","reasonZh":"缺少影像令關注減少；風暴並未結束。","correct":true},{"id":"foil-1","text":"Without the satellite images, the storm became out of sight, out of mind for viewers who gradually forgot it, though it was already over.","reasonZh":"原文仍持續，不能當成結束。","correct":false},{"id":"foil-2","text":"Without the satellite images, the storm became out of sight, out of mind for viewers who carefully monitored it, though it was still active.","reasonZh":"原文是淡忘，不是密切監測。","correct":false},{"id":"foil-3","text":"With hourly satellite images, the storm became out of sight, out of mind for viewers who gradually forgot it, though it was still active.","reasonZh":"原文停止傳回，不是每小時更新。","correct":false}]},{"id":"proverb-01-x02","number":52,"theme":"museum","promptEn":"A museum moved a donated sculpture into storage. Staff stopped discussing it, but the donor still asked about it monthly.","promptZh":"博物館把捐贈雕塑入倉後，員工不再討論；捐贈者仍每月詢問。","options":[{"id":"key","text":"The stored sculpture was out of sight, out of mind for staff, but not for the donor who asked about it monthly.","reasonZh":"員工淡忘，但捐贈者持續關注；不能把兩方混同。","correct":true},{"id":"foil-1","text":"The stored sculpture was out of sight, out of mind for staff, and equally for the donor who asked about it monthly.","reasonZh":"捐贈者每月問，沒有淡忘。","correct":false},{"id":"foil-2","text":"The stored sculpture was out of sight, out of mind for staff, but not for the donor who asked about it once a decade.","reasonZh":"原文明說每月。","correct":false},{"id":"foil-3","text":"The newly exhibited sculpture was out of sight, out of mind for staff, but not for the donor who asked about it monthly.","reasonZh":"雕塑入倉，不是剛展出。","correct":false}]},{"id":"proverb-01-x03","number":53,"theme":"accessibility","promptEn":"When an accessibility request disappeared from a project dashboard, the developers forgot it. The barrier remained.","promptZh":"無障礙功能的要求從專案看板消失後，開發人員忘了它；障礙依然存在。","options":[{"id":"key","text":"The accessibility request became out of sight, out of mind after leaving the dashboard; the developers forgot it, while the barrier still needed work.","reasonZh":"要求被忘不代表障礙解決，正需要恢復關注。","correct":true},{"id":"foil-1","text":"The accessibility request became out of sight, out of mind after leaving the dashboard; the developers forgot it, while the barrier had been fully removed.","reasonZh":"原文障礙仍在。","correct":false},{"id":"foil-2","text":"The accessibility request became out of sight, out of mind while highlighted in every daily meeting; the developers forgot it, while the barrier still needed work.","reasonZh":"原文是從看板消失，非每天重點討論。","correct":false},{"id":"foil-3","text":"The accessibility request became out of sight, out of mind after leaving the dashboard; the users stopped needing it, while the barrier still needed work.","reasonZh":"開發人員忘記不等於使用者不再需要。","correct":false}]},{"id":"proverb-01-x04","number":54,"theme":"language","promptEn":"A learner stopped seeing her vocabulary cards after moving them into an opaque pouch and soon forgot to practise.","promptZh":"學習者把字卡放進不透明袋後不再看見，很快忘了練習。","options":[{"id":"key","text":"Inside the opaque pouch, the cards were out of sight, out of mind, and she soon forgot to practise.","reasonZh":"物件被遮住後忘了練習，因果完整。","correct":true},{"id":"foil-1","text":"Inside the transparent stand on her desk, the cards were out of sight, out of mind, and she soon forgot to practise.","reasonZh":"不透明袋不是桌面透明架。","correct":false},{"id":"foil-2","text":"Inside the opaque pouch, the cards were out of sight, out of mind, and she soon mastered every word.","reasonZh":"忘記練習不代表全部學會。","correct":false},{"id":"foil-3","text":"Inside the opaque pouch, the cards were out of sight, out of mind, and she only ten years later forgot to practise.","reasonZh":"原文很快，不是十年後。","correct":false}]},{"id":"proverb-01-x05","number":55,"theme":"energy","promptEn":"The household’s electricity meter is hidden, but a weekly message keeps everyone aware of consumption.","promptZh":"電錶雖藏在看不見的位置，每週訊息仍讓家人留意用電量。","options":[{"id":"key","text":"The hidden meter is not a case of out of sight, out of mind: weekly messages keep consumption in view.","reasonZh":"提醒維持注意，說明實體看不見未必淡忘。","correct":true},{"id":"foil-1","text":"The hidden meter is a clear case of out of sight, out of mind: weekly messages keep consumption in view.","reasonZh":"持續關注是反例，不是淡忘。","correct":false},{"id":"foil-2","text":"The hidden meter is not a case of out of sight, out of mind: yearly messages keep consumption in view.","reasonZh":"原文每週更新。","correct":false},{"id":"foil-3","text":"The hidden meter is not a case of out of sight, out of mind: weekly messages prove electricity use is zero.","reasonZh":"關注用量不代表用量為零。","correct":false}]},{"id":"proverb-01-x06","number":56,"theme":"heritage","promptEn":"Without annual visits, young relatives may gradually forget the family’s ancestral village.","promptZh":"如果沒有每年探訪，年輕親屬可能逐漸淡忘家族的祖村。","options":[{"id":"key","text":"Without annual visits, the ancestral village may become out of sight, out of mind for younger relatives.","reasonZh":"may 保留風險，沒有斷言必然忘祖。","correct":true},{"id":"foil-1","text":"Without annual visits, the ancestral village has certainly become out of sight, out of mind for younger relatives.","reasonZh":"原文是未來可能性。","correct":false},{"id":"foil-2","text":"Without daily visits, the ancestral village may become out of sight, out of mind for younger relatives.","reasonZh":"原文每年一次，不是每天。","correct":false},{"id":"foil-3","text":"Without annual visits, the ancestral village may become out of sight, out of mind for every member of the family.","reasonZh":"原文只談年輕親屬。","correct":false}]},{"id":"proverb-01-x07","number":57,"theme":"research","promptEn":"A laboratory removed an unresolved anomaly from its meeting list. Researchers stopped investigating it.","promptZh":"實驗室把未解異常從會議清單移走，研究員便不再調查。","options":[{"id":"key","text":"The unresolved anomaly became out of sight, out of mind after leaving the meeting list, rather than being explained, as researchers stopped investigating.","reasonZh":"停止調查不能當成已解釋異常。","correct":true},{"id":"foil-1","text":"The unresolved anomaly became out of sight, out of mind after leaving the meeting list, because it had been explained, as researchers stopped investigating.","reasonZh":"原文未解，不是解決後移除。","correct":false},{"id":"foil-2","text":"The unresolved anomaly became out of sight, out of mind after leaving the meeting list, rather than being explained, as researchers verified it every day.","reasonZh":"原文停止調查。","correct":false},{"id":"foil-3","text":"The unresolved anomaly became out of sight, out of mind after leaving the laboratory altogether, rather than being explained, as researchers stopped investigating.","reasonZh":"原文從清單移走，沒有說異常現象本身消失。","correct":false}]},{"id":"proverb-01-x08","number":58,"theme":"sport","promptEn":"A captain keeps the injured goalkeeper in the weekly team call so the team will not forget him.","promptZh":"隊長每週通話仍邀請受傷守門員，以免隊友忘記他。","options":[{"id":"key","text":"Keeping the goalkeeper in weekly calls helps prevent “out of sight, out of mind” while he is away.","reasonZh":"主動保持接觸用來預防淡忘，非表示球員已被遺忘。","correct":true},{"id":"foil-1","text":"Keeping the goalkeeper in weekly calls proves the inevitability of “out of sight, out of mind” while he is away.","reasonZh":"預防措施不證明淡忘必然發生。","correct":false},{"id":"foil-2","text":"Keeping the goalkeeper in hourly calls helps prevent “out of sight, out of mind” while he is away.","reasonZh":"原文每週，不是每小時。","correct":false},{"id":"foil-3","text":"Keeping the goalkeeper in weekly calls helps prevent “out of sight, out of mind” because he has retired forever.","reasonZh":"只是受傷暫離，沒有永久退休。","correct":false}]},{"id":"proverb-01-x09","number":59,"theme":"food","promptEn":"A café stopped displaying the seasonal soup. Customers rarely thought to order it, although it was still available.","promptZh":"咖啡店不再展示季節湯，顧客很少想起點它，但店內仍有供應。","options":[{"id":"key","text":"The soup was out of sight, out of mind after its display disappeared, though customers could still order it; they rarely thought to order it.","reasonZh":"沒有展示令少想起，不代表停售。","correct":true},{"id":"foil-1","text":"The soup was out of sight, out of mind after its display disappeared, though customers could no longer order it; they rarely thought to order it.","reasonZh":"原文仍有供應。","correct":false},{"id":"foil-2","text":"The soup was out of sight, out of mind after its display disappeared, though customers could still order it; they ordered it more often.","reasonZh":"原文很少想起，不是更常點。","correct":false},{"id":"foil-3","text":"The soup was out of sight, out of mind after its price was doubled, though customers could still order it; they rarely thought to order it.","reasonZh":"原文沒提加價，原因是展示消失。","correct":false}]},{"id":"proverb-01-x10","number":60,"theme":"volunteering","promptEn":"After the shelter stopped posting about older animals, enquiries about them fell. They still needed homes.","promptZh":"收容所停止發布年老動物的消息後，相關查詢減少；牠們仍需要家。","options":[{"id":"key","text":"The older animals risk becoming out of sight, out of mind when updates stop; fewer enquiries do not mean they have found homes.","reasonZh":"查詢減少可能反映失去注意，不能推論全已被領養。","correct":true},{"id":"foil-1","text":"The older animals are proven to be out of sight, out of mind when updates stop; fewer enquiries do not mean they have found homes.","reasonZh":"資料支持風險，沒有證明每個人都淡忘。","correct":false},{"id":"foil-2","text":"The older animals risk becoming out of sight, out of mind when updates stop; fewer enquiries prove they have found homes.","reasonZh":"查詢少不能證明已找到家。","correct":false},{"id":"foil-3","text":"The all shelter animals risk becoming out of sight, out of mind when updates stop; fewer enquiries do not mean they have found homes.","reasonZh":"原文只談年老動物。","correct":false}]}],"guide":{"meaning":{"zh":"人或事情不再出現在眼前，便容易被淡忘或忽略。","en":"People or things may receive less thought or attention when they are no longer regularly seen."},"model":{"zh":"Maya 把未回覆的邀請塞進文件夾後便忘了它：不在眼前，就不再放在心上。","en":"Maya tucked the unanswered invitation into a folder and forgot about it—out of sight, out of mind."},"picture":{"zh":"想像聚光燈移開：事情仍在，只是注意力不再照到它。","en":"Picture a spotlight moving away: the thing remains, but attention no longer falls on it."},"boundary":{"zh":"不在眼前不代表不存在、已解決或必然被忘記。持續聯絡的人可以是反例。","en":"Being unseen does not mean being gone, solved, or inevitably forgotten. Continued contact can provide a counterexample."},"where":{"zh":"適合解釋疏忽或提醒人維持關注。對感到孤單的人，直接說這句可能顯得冷漠。","en":"Use it to explain neglect or the need for reminders. Said directly to someone who feels lonely, it may sound uncaring."},"tone":{"zh":"日常的觀察，也可帶惋惜或警告；不是「不用理會」的建議。","en":"A conversational observation, sometimes regretful or cautionary—not advice to stop caring."},"checks":[{"zh":"有「接觸減少 → 注意力減少」的線索嗎？","en":"Is there evidence of less contact leading to less attention?"},{"zh":"我有把被忽略誤說成已解決嗎？","en":"Am I confusing neglect with resolution?"},{"zh":"這句會不會令對方覺得被輕視？","en":"Could this wording make someone feel dismissed?"}],"readAloud":{"zh":"我們把借來的望遠鏡收進閣樓後便忘記歸還：眼不見，心不念。","en":"We put the borrowed telescope in the attic and forgot to return it—out of sight, out of mind."},"choices":{"2":{"prompt":{"zh":"哪個線索最能支持這句諺語？","en":"Which evidence best supports this proverb?"},"options":[{"zh":"水管漏水的提示從維修看板移走後，員工漸漸忘記跟進。","en":"After the leak reminder vanished from the maintenance board, staff gradually forgot to follow up.","reasonZh":"提醒消失後注意力減少，兩個環節都有證據；漏水仍可能存在。","correct":true},{"zh":"員工把漏水提示移走，因為水管已修妥並通過測試。","en":"Staff removed the leak reminder because the pipe had been repaired and tested.","reasonZh":"移走提示是完成維修的結果，不是因看不見而忘記。","correct":false},{"zh":"員工雖看不到隱藏的水管，仍每天查看漏水監測器。","en":"Although the pipe is hidden, staff check the leak monitor every day.","reasonZh":"實體看不見，但關注持續；不支持淡忘。","correct":false}]},"3":{"prompt":{"zh":"一位居家休養的同事說：「大家好像忘了我。」哪個回應最體貼？","en":"A colleague recovering at home says, “Everyone seems to have forgotten me.” Which response is most considerate?"},"options":[{"zh":"「你不在辦公室，我們確實少了聯絡。對不起，我星期五再打給你。」","en":"“We have been in touch less while you’re away. I’m sorry; I’ll call again on Friday.”","reasonZh":"承認疏忽並提出具體關心，比用諺語把淡忘說成理所當然更體貼。","correct":true},{"zh":"「眼不見，心不念嘛。你不來，自然沒人想起你。」","en":"“Out of sight, out of mind. If you’re not here, naturally nobody thinks of you.”","reasonZh":"這把對方的孤單當成必然，容易顯得冷漠。","correct":false},{"zh":"「眼不見，心不念；這證明你根本不需要同事。」","en":"“Out of sight, out of mind; that proves you don’t need colleagues.”","reasonZh":"諺語不證明對方沒有社交需要，推論也否定了他的感受。","correct":false}]},"5":{"prompt":{"zh":"社區電台停止報道海灣污染後，捐款逐漸減少，污染卻仍在。哪句最貼切？","en":"Donations fell after local radio stopped covering bay pollution, although the pollution remained. Which line fits?"},"options":[{"zh":"「報道一停，問題便不在眼前、也不在心上；我們需要持續更新。」","en":"“Once the reports stopped, the problem was out of sight, out of mind; we need regular updates.”","reasonZh":"把停止接觸和減少關注連起來，同時保留問題未解決。","correct":true},{"zh":"「報道一停，問題便不在眼前、也不在心上，證明海灣已經乾淨。」","en":"“Once the reports stopped, the problem was out of sight, out of mind, proving the bay was clean.”","reasonZh":"注意力消失不能證明污染清除，與仍有污染矛盾。","correct":false},{"zh":"「報道一停，問題便不在眼前、也不在心上，所以所有聽眾都更關注它。」","en":"“Once the reports stopped, the problem was out of sight, out of mind, so every listener cared more.”","reasonZh":"更關注與 out of mind 的意思相反，也無所有聽眾的證據。","correct":false}]},"6":{"prompt":{"zh":"Tariq 搬到外地後仍每週與祖母視像通話。這能支持哪個判斷？","en":"Tariq moved away but still video-calls his grandmother every week. What does this support?"},"options":[{"zh":"距離不必然造成淡忘；保持聯絡可以抵抗這種傾向。","en":"Distance does not inevitably cause forgetting; regular contact can resist the tendency.","reasonZh":"持續每週聯絡是反例，說明諺語並非絕對規律。","correct":true},{"zh":"只要不是住在一起，就必然是「眼不見，心不念」。","en":"Living apart necessarily means “out of sight, out of mind.”","reasonZh":"原文仍每週聯絡，不能把居住距離直接等同淡忘。","correct":false},{"zh":"一次沒有淡忘，就證明從來沒有人會因缺少接觸而忘記。","en":"One case of remembering proves that lack of contact never makes anyone forget.","reasonZh":"一個反例只能否定必然性，不能否定這種傾向可能存在。","correct":false}]}}}},"proverb-02":{"id":"proverb-02","titleEn":"Every Man Has His Price","titleZh":"人人都有價碼","version":"2026-10-28.1","items":[{"id":"proverb-02-q01","number":1,"promptEn":"The businessman believed that anyone could be persuaded to act dishonestly if enough money was offered.","promptZh":"那名商人認為，只要有人出足夠的錢，任何人都可以被說服做不誠實的事。","options":[{"id":"key","text":"The businessman believed that every man has his price: enough money could buy anyone’s honesty.","reasonZh":"商人相信足夠金錢能收買任何人；句子把這當成他的信念。","correct":true},{"id":"foil-1","text":"The businessman proved that every man has his price: enough money could buy anyone’s honesty.","reasonZh":"相信不等於證明。","correct":false},{"id":"foil-2","text":"The businessman believed that every man has his price: enough money could pay anyone’s ordinary salary.","reasonZh":"諺語涉及出賣原則，不是正常薪金。","correct":false},{"id":"foil-3","text":"Everyone he met believed that every man has his price: enough money could buy anyone’s honesty.","reasonZh":"不能把一人的信念套在所有認識的人身上。","correct":false}]},{"id":"proverb-02-q02","number":2,"promptEn":"The gang leader said that nobody would stay loyal if the reward became large enough.","promptZh":"那名幫派首領說，只要報酬夠高，沒有人會一直保持忠誠。","options":[{"id":"key","text":"“Every man has his price,” said the gang leader, claiming that a large enough reward would overcome anyone’s loyalty.","reasonZh":"首領聲稱高報酬足以打破任何人的忠誠，保留引述立場。","correct":true},{"id":"foil-1","text":"“Every man has his price,” said the gang leader, demonstrating conclusively that a large enough reward would overcome anyone’s loyalty.","reasonZh":"聲稱不是確證。","correct":false},{"id":"foil-2","text":"“Every man has his price,” said the gang leader, claiming that a large enough reward would reward everyone’s loyal service.","reasonZh":"收買背叛不同於獎勵忠誠服務。","correct":false},{"id":"foil-3","text":"“Every man has his price,” said every gang member, claiming that a large enough reward would overcome anyone’s loyalty.","reasonZh":"只有首領發言，沒有全體成員的立場。","correct":false}]},{"id":"proverb-02-q03","number":3,"promptEn":"According to the reporter, the politician thought that any person could be bought.","promptZh":"據記者所說，那名政治人物認為任何人都可以被收買。","options":[{"id":"key","text":"According to the reporter, the politician believed that every man has his price: anyone could be bought.","reasonZh":"記者轉述政治人物的信念；不是記者自己承認可被收買。","correct":true},{"id":"foil-1","text":"According to the reporter, the reporter believed that every man has his price: anyone could be bought.","reasonZh":"把被報道者的想法錯歸給記者。","correct":false},{"id":"foil-2","text":"According to the reporter, the politician believed that every man has his price: anyone should receive a fair wage.","reasonZh":"可被收買不是應獲公平工資。","correct":false},{"id":"foil-3","text":"According to the reporter, the politician had conclusively proved that every man has his price: anyone could be bought.","reasonZh":"原文只有信念，沒有普遍證明。","correct":false}]},{"id":"proverb-02-q04","number":4,"promptEn":"The shop owner thought even honest inspectors would change their minds for enough money. He trusted money more than principles.","promptZh":"店主認為，只要金額足夠，就連誠實的檢查員也會改變主意。他相信金錢多於原則。","options":[{"id":"key","text":"Trusting money more than principles, the shop owner believed that every man has his price, even honest inspectors.","reasonZh":"店主認為連誠實檢查員也能收買，並非敘述檢查員已收錢。","correct":true},{"id":"foil-1","text":"Trusting money only for legitimate wages, the shop owner believed that every man has his price, even honest inspectors.","reasonZh":"原文是金錢壓過原則，不是合法薪金用途。","correct":false},{"id":"foil-2","text":"Trusting money more than principles, the shop owner had proved that every man has his price, even honest inspectors.","reasonZh":"沒有證據顯示所有人已接受賄賂。","correct":false},{"id":"foil-3","text":"Trusting money more than principles, the shop owner believed that every man has his price, but never honest inspectors.","reasonZh":"even 包括誠實檢查員；but never 把他們排除。","correct":false}]},{"id":"proverb-02-q05","number":5,"promptEn":"Liam said that anyone’s loyalty could be bought with the right offer.","promptZh":"利亞姆說，只要條件合適，任何人的忠誠都可以被收買。","options":[{"id":"key","text":"Liam said that every man has his price: the right offer could buy anyone’s loyalty.","reasonZh":"利亞姆把忠誠視為可收買；保留 said 的發言者。","correct":true},{"id":"foil-1","text":"Liam said that every man has his price: the right offer could set everyone’s hourly wage.","reasonZh":"諺語不是時薪定價。","correct":false},{"id":"foil-2","text":"Liam’s friends all agreed that every man has his price: the right offer could buy anyone’s loyalty.","reasonZh":"原文沒有朋友一致同意。","correct":false},{"id":"foil-3","text":"Liam said that every man has his price: every small offer would buy anyone’s loyalty.","reasonZh":"條件合適不等於隨便一筆小錢都行。","correct":false}]},{"id":"proverb-02-q06","number":6,"promptEn":"The film presents a dark idea: no person’s principles are completely safe from money.","promptZh":"這齣電影提出一個陰暗的想法：沒有人的原則能完全不受金錢影響。","options":[{"id":"key","text":"The film presents the dark idea that every man has his price, with money threatening anyone’s principles.","reasonZh":"電影呈現陰暗觀點；不是以電影證明全人類都如此。","correct":true},{"id":"foil-1","text":"The film establishes the scientific fact that every man has his price, with money threatening anyone’s principles.","reasonZh":"故事觀點不是科學定律。","correct":false},{"id":"foil-2","text":"The film presents the dark idea that every man has his price, with money guaranteeing everyone a fair wage.","reasonZh":"重點是原則受收買，不是薪酬公平。","correct":false},{"id":"foil-3","text":"The film presents the cheerful compliment that every man has his price, with money threatening anyone’s principles.","reasonZh":"這是犬儒想法，不是愉快的讚美。","correct":false}]},{"id":"proverb-02-q07","number":7,"promptEn":"Some people think everyone has a point at which money becomes more important than honesty.","promptZh":"有些人認為，每個人都有一個金錢會變得比誠實更重要的臨界點。","options":[{"id":"key","text":"Some people think that every man has his price: honesty can lose to money if the offer is large enough.","reasonZh":"有些人的想法是金額達到門檻就會放棄誠實；不代表全體共識。","correct":true},{"id":"foil-1","text":"All people think that every man has his price: honesty can lose to money if the offer is large enough.","reasonZh":"some 不等於 all。","correct":false},{"id":"foil-2","text":"Some people have proved that every man has his price: honesty can lose to money if the offer is large enough.","reasonZh":"想法未經普遍證明。","correct":false},{"id":"foil-3","text":"Some people think that every man has his price: honesty deserves a decent salary if the offer is large enough.","reasonZh":"放棄誠實不同於以誠實工作換取薪水。","correct":false}]},{"id":"proverb-02-q08","number":8,"promptEn":"The dishonest coach was sure he could buy anyone’s support. He only needed to offer enough.","promptZh":"那名不誠實的教練肯定自己可以收買任何人的支持；他只需要提出足夠高的條件。","options":[{"id":"key","text":"The dishonest coach was sure that every man has his price and that a sufficient offer could buy anyone’s support.","reasonZh":"教練自信能收買支持；不是已經成功買通所有人。","correct":true},{"id":"foil-1","text":"The dishonest coach had proved to everyone that every man has his price and that a sufficient offer could buy anyone’s support.","reasonZh":"自信不等於向所有人證實。","correct":false},{"id":"foil-2","text":"The dishonest coach was sure that every man has his price and that a sufficient offer could pay every player fairly.","reasonZh":"買通支持不是公平支付球員薪金。","correct":false},{"id":"foil-3","text":"The dishonest coach was sure that every man has his price and that any tiny offer could buy anyone’s support.","reasonZh":"足夠的金額不等於任意小額。","correct":false}]},{"id":"proverb-02-q09","number":9,"promptEn":"“Offer him more,” the dealer said. “Anyone can be bought.”","promptZh":"「再多給他一點吧，」那名商人說。「任何人都可以被收買。」","options":[{"id":"key","text":"“Offer him more—every man has his price,” the dealer said, treating the refusal as something a bigger bribe could overcome.","reasonZh":"加碼反映商人相信拒絕能被金錢突破，不是尊重不可收買的原則。","correct":true},{"id":"foil-1","text":"“Offer him more—every man has his price,” the dealer said, treating the refusal as something no amount of money could overcome.","reasonZh":"這會把商人的信念反轉。","correct":false},{"id":"foil-2","text":"“Offer him more—every man has his price,” the man being bribed admitted, treating the refusal as something a bigger bribe could overcome.","reasonZh":"原文是出價者說，不是受賄對象承認。","correct":false},{"id":"foil-3","text":"“Offer him more—every man has his price,” the dealer said, treating the refusal as something a fair hourly wage could overcome.","reasonZh":"賄賂不是正常時薪。","correct":false}]},{"id":"proverb-02-q10","number":10,"promptEn":"The novel’s villain believes that enough money can make any person betray their values.","promptZh":"小說中的反派相信，只要金額足夠，任何人都會背棄自己的價值觀。","options":[{"id":"key","text":"The novel’s villain believes that every man has his price: enough money can make anyone betray their values.","reasonZh":"反派相信金錢能換取背叛；這是角色觀點。","correct":true},{"id":"foil-1","text":"Every reader of the novel believes that every man has his price: enough money can make anyone betray their values.","reasonZh":"不能替所有讀者宣稱同意。","correct":false},{"id":"foil-2","text":"The novel’s villain proves as a universal fact that every man has his price: enough money can make anyone betray their values.","reasonZh":"角色相信不等於普遍事實。","correct":false},{"id":"foil-3","text":"The novel’s villain believes that every man has his price: enough money can make anyone receive fair payment for honest work.","reasonZh":"出賣價值觀不是誠實工作的報酬。","correct":false}]},{"id":"proverb-02-q11","number":11,"promptEn":"At first, Nora thought everyone could be bribed if the offer was high enough.","promptZh":"最初，諾拉認為只要出價夠高，任何人都可以被賄賂。","options":[{"id":"key","text":"At first, Nora believed that every man has his price and that a high enough offer could bribe anyone.","reasonZh":"At first 保留最初的立場，沒有替她現在的想法下結論。","correct":true},{"id":"foil-1","text":"To this day, Nora believed that every man has his price and that a high enough offer could bribe anyone.","reasonZh":"原文只說最初，沒有現在仍相信的證據。","correct":false},{"id":"foil-2","text":"At first, Nora believed that every man has his price and that a high enough offer could support anyone through a fair wage.","reasonZh":"bribe 是收買，不是公平薪金支持。","correct":false},{"id":"foil-3","text":"At first, Nora demonstrated beyond doubt that every man has his price and that a high enough offer could bribe anyone.","reasonZh":"信念不能改成無疑證明。","correct":false}]},{"id":"proverb-02-q12","number":12,"promptEn":"The boss does not accept a final refusal. He still thinks nobody is completely beyond the reach of money.","promptZh":"老闆不接受最後的拒絕。他仍然認為沒有人能完全不受金錢影響。","options":[{"id":"key","text":"The boss still thinks that every man has his price, so he refuses to accept a final no.","reasonZh":"老闆仍相信加碼有效，拒絕把 no 當成最後答案。","correct":true},{"id":"foil-1","text":"The boss no longer thinks that every man has his price, so he refuses to accept a final no.","reasonZh":"still 是仍然，並非不再相信。","correct":false},{"id":"foil-2","text":"The boss still thinks that every man has his price, so he has learned to respect a final no.","reasonZh":"原文不接受最後拒絕，並非學會尊重。","correct":false},{"id":"foil-3","text":"The boss still thinks that every man has his price, so he refuses to accept a request for ordinary wages.","reasonZh":"這是收買被拒，不是員工要求正常工資。","correct":false}]},{"id":"proverb-02-q13","number":13,"promptEn":"The speaker will argue that all people can be bought if the offer is large enough.","promptZh":"那名講者將會主張，只要出價夠高，所有人都可以被收買。","options":[{"id":"key","text":"The speaker will argue that every man has his price and that anyone can be bought with a large enough offer.","reasonZh":"will argue 是將要提出的論點，不是已完成的證明。","correct":true},{"id":"foil-1","text":"The speaker has already proved that every man has his price and that anyone can be bought with a large enough offer.","reasonZh":"時態和證據強度都被改動。","correct":false},{"id":"foil-2","text":"The speaker will argue that every man has his price and that anyone can be paid a fair salary with a large enough offer.","reasonZh":"bought 在此是收買，而不是合理薪金。","correct":false},{"id":"foil-3","text":"The speaker will argue that every man has his price and that anyone can be bought with the smallest possible offer.","reasonZh":"原文需要足夠大的報酬，不是最低金額。","correct":false}]},{"id":"proverb-02-q14","number":14,"promptEn":"The detective has seen many people accept bribes. He has always believed that nobody is completely safe from temptation.","promptZh":"那名偵探見過很多人收受賄賂；他一直相信沒有人能完全抵抗誘惑。","options":[{"id":"key","text":"After seeing many bribes accepted, the detective still holds his longstanding belief that every man has his price.","reasonZh":"多次目睹賄賂與他一直持有的信念一致，不能寫成剛開始相信。","correct":true},{"id":"foil-1","text":"After seeing many bribes accepted, the detective still holds his newly adopted belief that every man has his price.","reasonZh":"原文 has always believed，不是新信念。","correct":false},{"id":"foil-2","text":"After seeing every bribe in history accepted, the detective still holds his longstanding belief that every man has his price.","reasonZh":"many 不能擴大成歷史上每次賄賂。","correct":false},{"id":"foil-3","text":"After seeing many bribes accepted, the detective still holds his longstanding conclusive proof that every man has his price.","reasonZh":"眾多案例仍不足以證明任何人都會收受賄賂。","correct":false}]},{"id":"proverb-02-q15","number":15,"promptEn":"A: Why does Victor keep raising the offer? B: He thinks anyone will agree when enough money is offered.","promptZh":"甲：為甚麼維克托不斷提高出價？乙：他認為只要金額足夠，任何人都會答應。","options":[{"id":"key","text":"Victor keeps raising the offer because he thinks every man has his price and will agree at a high enough amount.","reasonZh":"加碼行動與維克托的信念連結；沒有說對方已答應。","correct":true},{"id":"foil-1","text":"Victor keeps raising the offer because he has proved every man has his price and will agree at a high enough amount.","reasonZh":"原文是維克托相信，不是證明。","correct":false},{"id":"foil-2","text":"Victor keeps raising the offer because he thinks every man has his price and has already accepted the first offer.","reasonZh":"原文未說已接受首筆出價。","correct":false},{"id":"foil-3","text":"Victor keeps reducing the offer because he thinks every man has his price and will agree at a high enough amount.","reasonZh":"題目說持續提高，不是降低出價。","correct":false}]},{"id":"proverb-02-q16","number":16,"promptEn":"Does Marcus really believe that anyone can be bought?","promptZh":"馬庫斯真的相信任何人都可以被收買嗎？","options":[{"id":"key","text":"Does Marcus really believe that every man has his price—that anyone can be bought?","reasonZh":"保留疑問句，並把 price 理解為收買門檻。","correct":true},{"id":"foil-1","text":"Marcus certainly believes that every man has his price—that anyone can be bought?","reasonZh":"提問不等於確認他的信念。","correct":false},{"id":"foil-2","text":"Does Marcus really believe that every man has his price—that everyone deserves a salary?","reasonZh":"原文問能否收買，不是薪金權利。","correct":false},{"id":"foil-3","text":"Does everyone Marcus knows really believe that every man has his price—that anyone can be bought?","reasonZh":"原文只問馬庫斯本人。","correct":false}]},{"id":"proverb-02-q17","number":17,"promptEn":"People often repeat a cynical saying which claims that everyone can be bribed.","promptZh":"人們經常重複一句很悲觀的說法，聲稱所有人都可以被賄賂。","options":[{"id":"key","text":"People often repeat the cynical saying “every man has his price,” which claims that anyone can be bribed.","reasonZh":"常被重複的犬儒說法不因此成為事實。","correct":true},{"id":"foil-1","text":"People always repeat the cynical saying “every man has his price,” which claims that anyone can be bribed.","reasonZh":"often 不等於每次。","correct":false},{"id":"foil-2","text":"People often repeat the cynical saying “every man has his price,” which proves that anyone can be bribed.","reasonZh":"諺語聲稱一件事，不會自動證明它。","correct":false},{"id":"foil-3","text":"People often repeat the respectful compliment “every man has his price,” which claims that anyone can be bribed.","reasonZh":"質疑人人的操守不是尊重的讚美。","correct":false}]},{"id":"proverb-02-q18","number":18,"promptEn":"Grace refuses to accept the claim that everyone can be bought.","promptZh":"格蕾絲拒絕接受「所有人都可以被收買」這個說法。","options":[{"id":"key","text":"Grace refuses to believe that every man has his price; she rejects the claim that everyone can be bought.","reasonZh":"格蕾絲拒絕人人可被收買的主張。","correct":true},{"id":"foil-1","text":"Grace is eager to prove that every man has his price; she rejects the claim that everyone can be bought.","reasonZh":"拒絕相信與熱衷證明相反。","correct":false},{"id":"foil-2","text":"Grace refuses to believe that every man has his price; she rejects the claim that anyone deserves an honest wage.","reasonZh":"她反對的是收買論，並非誠實工作應獲報酬。","correct":false},{"id":"foil-3","text":"Everyone in her town refuses to believe that every man has his price; she rejects the claim that everyone can be bought.","reasonZh":"不能把她的立場擴大到全鎮。","correct":false}]},{"id":"proverb-02-q19","number":19,"promptEn":"The lawyer knew money could influence many people, but he rejected the idea that it could influence everyone.","promptZh":"那名律師知道金錢可以影響很多人，但他不接受金錢可以影響所有人的想法。","options":[{"id":"key","text":"The lawyer knew money could influence many people, but he rejected the idea that every man has his price.","reasonZh":"many 與 everyone 的範圍差異構成律師的立場。","correct":true},{"id":"foil-1","text":"The lawyer knew money could influence nobody, but he rejected the idea that every man has his price.","reasonZh":"律師承認可影響許多人，並非無人。","correct":false},{"id":"foil-2","text":"The lawyer knew money could influence many people, but he endorsed the idea that every man has his price.","reasonZh":"他否定普遍主張，不是支持。","correct":false},{"id":"foil-3","text":"The lawyer had no idea whether money could influence many people, but he rejected the idea that every man has his price.","reasonZh":"原文明說他知道金錢能影響許多人。","correct":false}]},{"id":"proverb-02-q20","number":20,"promptEn":"A: The agent says the judge will agree if we offer enough. B: That is a terrible belief about people.","promptZh":"甲：那名代理人說，只要我們出價夠高，法官便會答應。乙：這種看法實在把人想得太差。","options":[{"id":"key","text":"The agent seems to believe that every man has his price, expecting enough money to secure the judge’s agreement.","reasonZh":"這是代理人的推斷；對話另一人批評這種信念。","correct":true},{"id":"foil-1","text":"Both speakers seems to believe that every man has his price, expecting enough money to secure the judge’s agreement.","reasonZh":"另一位說話者批評這信念，不是雙方同意。","correct":false},{"id":"foil-2","text":"The agent seems to believe that every man has his price, having already obtained enough money to secure the judge’s agreement.","reasonZh":"原文是預期同意，並非已得到。","correct":false},{"id":"foil-3","text":"The agent seems to believe that every man has his price, expecting a stronger legal argument to secure the judge’s agreement.","reasonZh":"代理人提的是出價，而非法律論證。","correct":false}]},{"id":"proverb-02-q21","number":21,"promptEn":"A: Why did the criminal offer the guard more and more money? B: He thought everyone had an amount they would accept.","promptZh":"甲：為甚麼那名罪犯向守衛提出愈來愈高的金額？乙：他認為每個人都有一個會接受的價碼。","options":[{"id":"key","text":"The criminal kept offering the guard more money, believing that every man has his price.","reasonZh":"不斷加碼反映罪犯的想法，沒有說守衛最終收錢。","correct":true},{"id":"foil-1","text":"The criminal kept offering the guard more money, conclusively proving that every man has his price.","reasonZh":"出價本身不能證明對方會接受。","correct":false},{"id":"foil-2","text":"The criminal stopped offering the guard more money, believing that every man has his price.","reasonZh":"原文持續加碼，不是停止。","correct":false},{"id":"foil-3","text":"The guard kept offering the guard more money, believing that every man has his price.","reasonZh":"持有這信念的是行賄者，不是守衛。","correct":false}]},{"id":"proverb-02-q22","number":22,"promptEn":"A wealthy buyer kept increasing his offer. He believed even a loyal worker could be persuaded to betray the company.","promptZh":"一名富有的買家不斷提高出價。他相信就連忠誠的員工也可以被說服背叛公司。","options":[{"id":"key","text":"The wealthy buyer acted as if every man has his price, raising his offer to make a loyal worker betray the company.","reasonZh":"出價者相信忠誠可被買走；betray 的目的有保留。","correct":true},{"id":"foil-1","text":"The wealthy buyer acted as if every man has his price, raising his offer after successfully making a loyal worker betray the company.","reasonZh":"原文沒有說成功令工人背叛。","correct":false},{"id":"foil-2","text":"The wealthy buyer acted as if every man has his price, raising his offer to make a loyal worker remain loyal to the company.","reasonZh":"收買目的正是背叛，不是維持忠誠。","correct":false},{"id":"foil-3","text":"The wealthy buyer acted as if every man has his price, withdrawing his offer to make a loyal worker betray the company.","reasonZh":"原文提高出價，不是撤回。","correct":false}]},{"id":"proverb-02-q23","number":23,"promptEn":"The character laughs at honesty and says that a large enough reward can break anyone’s principles.","promptZh":"那個角色嘲笑誠實，並說只要報酬夠高，任何人的原則都會被打破。","options":[{"id":"key","text":"The character laughs at honesty because he believes every man has his price and enough money can break anyone’s principles.","reasonZh":"角色嘲笑誠實，因他相信金錢能打破原則。","correct":true},{"id":"foil-1","text":"The character respectfully celebrates honesty because he believes every man has his price and enough money can break anyone’s principles.","reasonZh":"嘲笑不是尊重地讚揚。","correct":false},{"id":"foil-2","text":"The character laughs at honesty because he proves beyond dispute every man has his price and enough money can break anyone’s principles.","reasonZh":"角色的判斷不構成普遍證明。","correct":false},{"id":"foil-3","text":"The character laughs at honesty because he believes every man has his price and enough money can pay everyone for honest work.","reasonZh":"違背原則與誠實工作報酬不同。","correct":false}]},{"id":"proverb-02-q24","number":24,"promptEn":"Why does the businessman never accept a final no? He believes a better offer will change anyone’s answer.","promptZh":"為甚麼那名商人從不接受最後的拒絕？他相信提出更好的條件便能改變任何人的答案。","options":[{"id":"key","text":"The businessman never accepts a final no: he believes every man has his price and a better offer will change any answer.","reasonZh":"不接受最後拒絕是其加碼信念的結果。","correct":true},{"id":"foil-1","text":"The businessman always respects a final no: he believes every man has his price and a better offer will change any answer.","reasonZh":"原文不接受，並非尊重最後拒絕。","correct":false},{"id":"foil-2","text":"The businessman never accepts a final no: he has demonstrated universally every man has his price and a better offer will change any answer.","reasonZh":"一人相信不能改成普遍驗證。","correct":false},{"id":"foil-3","text":"The businessman never accepts a final no: he believes every man has his price and a polite thank-you will change any answer.","reasonZh":"題目指提高利益，不是禮貌道謝。","correct":false}]},{"id":"proverb-02-q25","number":25,"promptEn":"A: I would never sell my friend’s secret. B: The villain says you would if the offer were high enough.","promptZh":"甲：我絕不會出賣朋友的秘密。乙：那個反派說，只要出價夠高，你便會這樣做。","options":[{"id":"key","text":"The villain says “every man has his price,” predicting that a high enough offer would make the speaker sell a friend’s secret.","reasonZh":"是反派的預測；說話者自己宣稱絕不出賣朋友。","correct":true},{"id":"foil-1","text":"The speaker says “every man has his price,” predicting that a high enough offer would make the speaker sell a friend’s secret.","reasonZh":"把反派觀點錯歸給反對它的人。","correct":false},{"id":"foil-2","text":"The villain says “every man has his price,” reporting a completed sale that a high enough offer would make the speaker sell a friend’s secret.","reasonZh":"原文只是預測，不是已售出秘密。","correct":false},{"id":"foil-3","text":"The villain says “every man has his price,” predicting that any token payment would make the speaker sell a friend’s secret.","reasonZh":"足夠高的出價不等於象徵性小額。","correct":false}]},{"id":"proverb-02-q26","number":26,"promptEn":"Ethan offered the nurse money, but she reported him at once. His belief that anyone could be bought was clearly wrong.","promptZh":"伊森向護士提出金錢，但她立即舉報了他。他那種「任何人都可以被收買」的想法明顯是錯的。","options":[{"id":"key","text":"Ethan believed that every man has his price, but the nurse reported his offer at once and showed his belief was wrong.","reasonZh":"護士立即舉報，構成反例，而不是接受賄賂。","correct":true},{"id":"foil-1","text":"Ethan believed that every man has his price, but the nurse accepted his offer at once and showed his belief was wrong.","reasonZh":"原文是舉報，不是收錢。","correct":false},{"id":"foil-2","text":"Ethan believed that every man has his price, but the nurse reported his offer only after months of negotiation and showed his belief was wrong.","reasonZh":"原文立刻舉報，沒有數月談判。","correct":false},{"id":"foil-3","text":"Ethan believed that every man has his price, but the nurse reported his offer at once and showed his belief was correct.","reasonZh":"拒收並舉報反駁了人人可收買的主張。","correct":false}]},{"id":"proverb-02-q27","number":27,"promptEn":"The officer turned down every offer. This challenges the cynical idea that everybody can be bribed.","promptZh":"那名人員拒絕了所有出價。這件事挑戰了「所有人都可以被賄賂」這個悲觀想法。","options":[{"id":"key","text":"The officer’s refusal of every offer challenges the saying “every man has his price.”","reasonZh":"所有出價都被拒，挑戰人人可被收買的觀點。","correct":true},{"id":"foil-1","text":"The officer’s refusal of only the first offer challenges the saying “every man has his price.”","reasonZh":"原文每次都拒絕，不是只拒絕首次。","correct":false},{"id":"foil-2","text":"The officer’s refusal of every offer confirms the saying “every man has his price.”","reasonZh":"拒絕是反例，不是支持證據。","correct":false},{"id":"foil-3","text":"The officer’s acceptance of every offer challenges the saying “every man has his price.”","reasonZh":"原文沒有收受賄賂。","correct":false}]},{"id":"proverb-02-q28","number":28,"promptEn":"The play asks a difficult question: can every person be persuaded to betray their values for the right reward?","promptZh":"這齣戲提出一個難題：只要報酬合適，每個人都會被說服背棄自己的價值觀嗎？","options":[{"id":"key","text":"The play asks whether every man has his price—whether the right reward can make anyone betray their values.","reasonZh":"戲劇提出問題，沒有給出肯定結論。","correct":true},{"id":"foil-1","text":"The play conclusively proves that every man has his price—whether the right reward can make anyone betray their values.","reasonZh":"提問不是證明。","correct":false},{"id":"foil-2","text":"The play asks whether every man has his price—whether the right reward can make anyone earn a reasonable salary.","reasonZh":"背棄價值觀不是正常薪酬。","correct":false},{"id":"foil-3","text":"The play asks whether every man has his price—whether any tiny reward can make anyone betray their values.","reasonZh":"原文所需是合適報酬，不是任意小額。","correct":false}]},{"id":"proverb-02-q29","number":29,"promptEn":"A: Do you think Daniel will betray us for money? B: No. I do not accept the idea that everyone can be bought.","promptZh":"甲：你認為丹尼爾會為了錢背叛我們嗎？乙：不。我不接受所有人都可以被收買這個想法。","options":[{"id":"key","text":"“No, I do not believe every man has his price,” I replied when asked whether Daniel would betray us for money.","reasonZh":"回答者否定會被收買的普遍主張，對 Daniel 的回答也是 no。","correct":true},{"id":"foil-1","text":"“Yes, I firmly believe every man has his price,” I replied when asked whether Daniel would betray us for money.","reasonZh":"把否定立場倒轉。","correct":false},{"id":"foil-2","text":"“No, I do not believe every man has his price,” I replied when asked whether Daniel would work honestly for us for money.","reasonZh":"題目是背叛，不是正常工作。","correct":false},{"id":"foil-3","text":"“No, I do not believe every man has his price,” Daniel admitted when asked whether Daniel would betray us for money.","reasonZh":"回答者不是 Daniel 自己承認。","correct":false}]},{"id":"proverb-02-q30","number":30,"promptEn":"The article warns that believing everyone can be bought may lead powerful people to treat others badly.","promptZh":"文章警告，若相信所有人都可以被收買，掌權者可能會惡劣地對待他人。","options":[{"id":"key","text":"The article warns that believing every man has his price may lead powerful people to mistreat others.","reasonZh":"文章警告這種信念可能引致濫權，不是鼓勵收買。","correct":true},{"id":"foil-1","text":"The article celebrates that believing every man has his price may lead powerful people to mistreat others.","reasonZh":"警告與慶祝的態度相反。","correct":false},{"id":"foil-2","text":"The article warns that believing every man has his price has always led powerful people to mistreat others.","reasonZh":"may 不是每次必然發生。","correct":false},{"id":"foil-3","text":"The article warns that believing every man has his price may lead powerful people to respect everyone’s principles.","reasonZh":"原文負面結果是待人不善，不是尊重原則。","correct":false}]},{"id":"proverb-02-q31","number":31,"promptEn":"Although the mayor had seen many cases of bribery, she still refused to believe that all people could be bought.","promptZh":"雖然市長見過很多賄賂個案，她仍然拒絕相信所有人都可以被收買。","options":[{"id":"key","text":"Although the mayor had seen many bribes accepted, she still rejected the claim that every man has his price.","reasonZh":"即使見過許多案例，市長仍不接受普遍結論。","correct":true},{"id":"foil-1","text":"Although the mayor had seen many bribes accepted, she still endorsed the claim that every man has his price.","reasonZh":"原文拒絕相信，不是贊同。","correct":false},{"id":"foil-2","text":"Although the mayor had seen all bribes ever offered accepted, she still rejected the claim that every man has his price.","reasonZh":"不能把 many 擴大到所有賄賂。","correct":false},{"id":"foil-3","text":"Although the mayor had never encountered bribery, she still rejected the claim that every man has his price.","reasonZh":"市長見過許多賄賂案例，不是從未遇到。","correct":false}]},{"id":"proverb-02-q32","number":32,"promptEn":"The gang kept making larger offers because its leader believed nobody would remain honest forever.","promptZh":"那個幫派不斷提高出價，因為首領相信沒有人會永遠保持誠實。","options":[{"id":"key","text":"The gang kept increasing its offers because its leader believed that every man has his price.","reasonZh":"反覆加碼由首領的信念驅動，不是交易成功的紀錄。","correct":true},{"id":"foil-1","text":"The gang kept withdrawing its offers because its leader believed that every man has his price.","reasonZh":"原文增加出價，不是收回。","correct":false},{"id":"foil-2","text":"The gang kept increasing its offers because its leader had conclusively proved that every man has his price.","reasonZh":"相信不等於證明全人類都可收買。","correct":false},{"id":"foil-3","text":"The gang kept increasing its offers because the people refusing its offers believed that every man has his price.","reasonZh":"原文信念屬於首領，不是拒絕者。","correct":false}]},{"id":"proverb-02-q33","number":33,"promptEn":"A: Why are they offering the witness a house now? B: Their leader thinks everybody has an amount they will accept.","promptZh":"甲：為甚麼他們現在向證人提出送一所房子？乙：他們的首領認為每個人都有一個會接受的價碼。","options":[{"id":"key","text":"Offering the witness a house reflects their leader’s belief that every man has his price.","reasonZh":"房屋也是利益；price 不限於現鈔，但這仍只是首領的信念。","correct":true},{"id":"foil-1","text":"Offering the witness an ordinary salary reflects their leader’s belief that every man has his price.","reasonZh":"原文提出的是房屋，不是薪金。","correct":false},{"id":"foil-2","text":"Offering the witness a house reflects their leader’s conclusive proof that every man has his price.","reasonZh":"出價不等於對方已接受，更非普遍證明。","correct":false},{"id":"foil-3","text":"Offering the witness a house reflects the witness’s belief that every man has his price.","reasonZh":"不能把出價者的信念當成證人的信念。","correct":false}]},{"id":"proverb-02-q34","number":34,"promptEn":"Most of the team trusted people’s principles, but Colin believed anyone could be bought.","promptZh":"團隊大部分成員都相信人的原則，但科林認為任何人都可以被收買。","options":[{"id":"key","text":"Most teammates trusted people’s principles, but Colin believed that every man has his price.","reasonZh":"Colin 的立場與大部分隊友相反；保留兩方。","correct":true},{"id":"foil-1","text":"All teammates, including Colin, trusted people’s principles, but Colin believed that every man has his price.","reasonZh":"原文 Colin 不同意其他人的立場。","correct":false},{"id":"foil-2","text":"Most teammates dismissed people’s principles, but Colin believed that every man has his price.","reasonZh":"大部分隊友相信原則，不是輕視。","correct":false},{"id":"foil-3","text":"Most teammates trusted people’s principles, and everyone else believed that every man has his price.","reasonZh":"把少數人的觀點錯擴成所有人。","correct":false}]},{"id":"proverb-02-q35","number":35,"promptEn":"The first two officials refused the bribe. The businessman did not stop, because he thought a higher amount would eventually work.","promptZh":"首兩名官員拒絕了賄賂。那名商人沒有停手，因為他認為更高的金額最終會奏效。","options":[{"id":"key","text":"Even after two officials refused, the businessman kept trying a higher offer, believing that every man has his price.","reasonZh":"兩次拒絕未改變商人的信念；沒有成功收買的結論。","correct":true},{"id":"foil-1","text":"Even after two officials accepted, the businessman kept trying a higher offer, believing that every man has his price.","reasonZh":"原文兩人拒收。","correct":false},{"id":"foil-2","text":"Even after two officials refused, the businessman gave up on a higher offer, believing that every man has his price.","reasonZh":"原文商人沒有放棄。","correct":false},{"id":"foil-3","text":"Even after two officials refused, the businessman kept trying a higher offer, thereby proving that every man has his price.","reasonZh":"加碼不能證明信念是真的。","correct":false}]},{"id":"proverb-02-q36","number":36,"promptEn":"The documentary does not say that everyone can be bought. It asks whether enough money can overcome anyone’s principles.","promptZh":"這齣紀錄片沒有說所有人都可以被收買；它探問足夠的金錢是否能勝過任何人的原則。","options":[{"id":"key","text":"The documentary asks whether every man has his price; it does not claim that everyone can be bought.","reasonZh":"紀錄片在探問普遍主張，不是宣布主張成立。","correct":true},{"id":"foil-1","text":"The documentary proves that every man has his price; it does not claim that everyone can be bought.","reasonZh":"探問與證明不同。","correct":false},{"id":"foil-2","text":"The documentary asks whether every man has his price; it confidently declares that everyone can be bought.","reasonZh":"原文明確說沒有宣稱人人可收買。","correct":false},{"id":"foil-3","text":"The documentary asks whether every man has his price; it does not claim that anyone can be paid for legitimate work.","reasonZh":"題目討論收買，不是工作薪酬。","correct":false}]},{"id":"proverb-02-q37","number":37,"promptEn":"A: Martin says the guard will agree when the offer reaches NT$50,000. B: Martin has a very low opinion of human honesty.","promptZh":"甲：馬丁說，當出價達到新台幣五萬元時，守衛便會答應。乙：馬丁對人的誠信看得很低。","options":[{"id":"key","text":"Martin thinks every man has his price, expecting the guard to agree at NT$50,000.","reasonZh":"NT$50,000 是 Martin 估計守衛會接受的金額，未必成真。","correct":true},{"id":"foil-1","text":"Martin thinks every man has his price, having already persuaded the guard to agree at NT$50,000.","reasonZh":"預期不是已說服。","correct":false},{"id":"foil-2","text":"Martin thinks every man has his price, expecting the guard to agree at NT$5,000.","reasonZh":"數字不能少一個零。","correct":false},{"id":"foil-3","text":"The guard admits every man has his price, expecting the guard to agree at NT$50,000.","reasonZh":"沒有守衛承認可收買的發言。","correct":false}]},{"id":"proverb-02-q38","number":38,"promptEn":"The dealer smiled and said that anyone could be bought if the offer was high enough.","promptZh":"那名商人笑着說，只要出價夠高，任何人都可以被收買。","options":[{"id":"key","text":"“Every man has his price,” the dealer said with a smile, claiming that a high enough offer could buy anyone.","reasonZh":"保留微笑、發言者和犬儒主張；微笑不會令收買變成讚美。","correct":true},{"id":"foil-1","text":"“Every man has his price,” the dealer said with a smile, proving conclusively that a high enough offer could buy anyone.","reasonZh":"聲稱不是普遍證明。","correct":false},{"id":"foil-2","text":"“Every man has his price,” the dealer said in tears, claiming that a high enough offer could buy anyone.","reasonZh":"原文說微笑，不是流淚。","correct":false},{"id":"foil-3","text":"“Every man has his price,” the dealer said with a smile, claiming that a high enough offer could pay everyone fairly for work.","reasonZh":"可收買與公平工作報酬不同。","correct":false}]},{"id":"proverb-02-q39","number":39,"promptEn":"If the director truly thinks no employee will stay loyal when enough money is offered, he has a very negative view of people.","promptZh":"如果那名主管真的認為，只要有人出足夠的錢，沒有員工會保持忠誠，那麼他對人的看法便十分負面。","options":[{"id":"key","text":"If the director truly believes every man has his price, he has a negative view of employees’ loyalty.","reasonZh":"If 保留條件；質疑忠誠是負面觀點。","correct":true},{"id":"foil-1","text":"Since the director truly believes every man has his price, he has a negative view of employees’ loyalty.","reasonZh":"原文是假設，不是已證實董事如此相信。","correct":false},{"id":"foil-2","text":"If the director truly believes every man has his price, he has a respectful and positive view of employees’ loyalty.","reasonZh":"把所有人當可收買是犬儒，而非尊重。","correct":false},{"id":"foil-3","text":"If the director truly believes every man has his price, he has a negative view of employees’ ordinary wage levels.","reasonZh":"題目是忠誠，不是薪金市場水平。","correct":false}]},{"id":"proverb-02-q40","number":40,"promptEn":"A: You think I will betray my team for more money. B: I admit that I believe everyone has an amount that will make them change their mind.","promptZh":"甲：你認為我會為了更多錢背叛團隊。乙：我承認，我相信每個人都有一個會使自己動搖的價碼。","options":[{"id":"key","text":"“I admit I believe every man has his price,” I said, expecting enough money to make you betray your team.","reasonZh":"回答者承認自己的想法，沒有說被問者承認會背叛。","correct":true},{"id":"foil-1","text":"“You admit you believe every man has his price,” I said, expecting enough money to make you betray your team.","reasonZh":"錯換了承認信念的人。","correct":false},{"id":"foil-2","text":"“I admit I believe every man has his price,” I said, having already proved enough money to make you betray your team.","reasonZh":"預測不能當成已證明。","correct":false},{"id":"foil-3","text":"“I admit I believe every man has his price,” I said, expecting enough money to make you earn a fair wage from your team.","reasonZh":"背叛與誠實工作取酬不同。","correct":false}]},{"id":"proverb-02-q41","number":41,"promptEn":"A lesson about bribes shows a dishonest business owner offering larger and larger payments because he assumes everyone can be bought.","promptZh":"一課有關賄賂的教材描述一名不誠實的店主不斷提高金額，因為他假定所有人都可以被收買。","options":[{"id":"key","text":"The lesson portrays a dishonest owner who believes every man has his price and keeps increasing his bribes.","reasonZh":"教材描寫角色的想法，不表示教材支持該想法。","correct":true},{"id":"foil-1","text":"The lesson endorses as a role model a dishonest owner who believes every man has his price and keeps increasing his bribes.","reasonZh":"描寫不等於樹為榜樣。","correct":false},{"id":"foil-2","text":"The lesson portrays a dishonest owner who believes every man has his price and keeps increasing his legitimate salaries.","reasonZh":"原文是賄賂，不是合法薪金。","correct":false},{"id":"foil-3","text":"The lesson portrays a dishonest owner who proves universally every man has his price and keeps increasing his bribes.","reasonZh":"角色信念不是普遍真理。","correct":false}]},{"id":"proverb-02-q42","number":42,"promptEn":"The detective notices that the criminal never asks whether people are honest; he only asks how much money they want.","promptZh":"那名偵探留意到，罪犯從不問別人是否誠實，只問他們想要多少錢。","options":[{"id":"key","text":"The detective recognises the criminal’s belief that every man has his price: the criminal asks only how much, not whether people are honest.","reasonZh":"偵探識別罪犯的信念；only how much 顯示罪犯預設都能收買。","correct":true},{"id":"foil-1","text":"The detective recognises his own proven conclusion that every man has his price: the criminal asks only how much, not whether people are honest.","reasonZh":"原文觀察的是罪犯，不是偵探證實自己的結論。","correct":false},{"id":"foil-2","text":"The detective recognises the criminal’s belief that every man has his price: the criminal asks only whether people are honest, not whether people are honest.","reasonZh":"原文罪犯不問誠實與否，只問價碼。","correct":false},{"id":"foil-3","text":"The detective adopts the criminal’s belief that every man has his price: the criminal asks only how much, not whether people are honest.","reasonZh":"識別他人的想法不等於採納。","correct":false}]},{"id":"proverb-02-q43","number":43,"promptEn":"The repeated offers reveal a belief that no person’s loyalty is beyond money.","promptZh":"一次又一次的出價顯示，有人相信沒有人的忠誠能超越金錢。","options":[{"id":"key","text":"The repeated offers reveal a belief that every man has his price, with no one’s loyalty considered beyond money.","reasonZh":"反覆出價顯示出價者的信念，不代表人人真有價碼。","correct":true},{"id":"foil-1","text":"The repeated offers establish a universal fact that every man has his price, with no one’s loyalty considered beyond money.","reasonZh":"揭露想法不是確立事實。","correct":false},{"id":"foil-2","text":"The repeated offers reveal a belief that every man has his price, with only dishonest people’s loyalty considered beyond money.","reasonZh":"原文 no person，不限於早已不誠實的人。","correct":false},{"id":"foil-3","text":"The completed payments to everyone reveal a belief that every man has his price, with no one’s loyalty considered beyond money.","reasonZh":"原文是多次出價，並非所有人收款。","correct":false}]},{"id":"proverb-02-q44","number":44,"promptEn":"A: The manager says the worker’s first refusal means nothing. B: Why? A: He thinks a bigger reward will change the answer.","promptZh":"甲：經理說，那名員工第一次拒絕並不代表甚麼。乙：為甚麼？甲：他認為更大的報酬會改變答案。","options":[{"id":"key","text":"The manager dismisses the worker’s first refusal, acting on the belief that every man has his price and a bigger reward will work.","reasonZh":"經理把首次拒絕視為可被加碼改變。","correct":true},{"id":"foil-1","text":"The manager respects as final the worker’s first refusal, acting on the belief that every man has his price and a bigger reward will work.","reasonZh":"原文不把拒絕當回事，並非尊重為最終決定。","correct":false},{"id":"foil-2","text":"The manager dismisses the worker’s accepted offer, acting on the belief that every man has his price and a bigger reward will work.","reasonZh":"工人拒絕了，不是接受。","correct":false},{"id":"foil-3","text":"The manager dismisses the worker’s first refusal, acting on the belief that every man has his price and a smaller reward will work.","reasonZh":"原文是更大報酬，不是減少。","correct":false}]},{"id":"proverb-02-q45","number":45,"promptEn":"The judge said that many people can be tempted, but it is wrong to claim that everyone can be bought.","promptZh":"法官說，很多人可能會受到誘惑，但聲稱所有人都可以被收買是錯誤的。","options":[{"id":"key","text":"The judge accepted that many people can be tempted but rejected “every man has his price” as a claim about everyone.","reasonZh":"承認 many 不代表承認 everyone；這正是法官的區分。","correct":true},{"id":"foil-1","text":"The judge accepted that no people can be tempted but rejected “every man has his price” as a claim about everyone.","reasonZh":"法官承認許多人受誘惑。","correct":false},{"id":"foil-2","text":"The judge accepted that many people can be tempted but endorsed “every man has his price” as a claim about everyone.","reasonZh":"法官否定普遍主張，不是支持。","correct":false},{"id":"foil-3","text":"The judge accepted that many people can be tempted but rejected “every man has his price” as a rule about fair wages.","reasonZh":"這不是工資規則，而是收買的普遍主張。","correct":false}]},{"id":"proverb-02-q46","number":46,"promptEn":"In the novel, the villain measures loyalty only in money and never accepts that a person may refuse every offer.","promptZh":"在小說中，反派只用金錢衡量忠誠，從不接受有人可能拒絕所有出價。","options":[{"id":"key","text":"In the novel, the villain measures loyalty only in money, acting as if every man has his price.","reasonZh":"這是小說反派的行事假設；未宣告所有角色都接受錢。","correct":true},{"id":"foil-1","text":"In the novel, the villain measures loyalty mainly in friendship, acting as if every man has his price.","reasonZh":"原文 only money，並非友誼。","correct":false},{"id":"foil-2","text":"In the novel, the villain measures loyalty only in money, scientifically demonstrating that every man has his price.","reasonZh":"角色行動不是科學證明。","correct":false},{"id":"foil-3","text":"In the novel, the narrator and every reader measures loyalty only in money, acting as if every man has his price.","reasonZh":"沒有敘事者及全體讀者的立場資料。","correct":false}]},{"id":"proverb-02-q47","number":47,"promptEn":"A: Why did she tear up the cheque? B: She wanted to show that her honesty was not for sale.","promptZh":"甲：她為甚麼撕掉支票？乙：她想表明自己的誠信不是用來出售的。","options":[{"id":"key","text":"By tearing up the cheque, she rejects “every man has his price” and shows that her honesty is not for sale.","reasonZh":"撕支票表明拒絕出售操守，成為普遍主張的反例。","correct":true},{"id":"foil-1","text":"By cashing the cheque, she rejects “every man has his price” and shows that her honesty is not for sale.","reasonZh":"撕毀與兌現支票相反。","correct":false},{"id":"foil-2","text":"By tearing up the cheque, she supports “every man has his price” and shows that her honesty is not for sale.","reasonZh":"拒收挑戰收買論，不是支持。","correct":false},{"id":"foil-3","text":"By tearing up the cheque, she rejects “every man has his price” and shows that every person’s honesty is not for sale.","reasonZh":"她的行動只能直接說明自己的操守，不能證明人人都不可收買。","correct":false}]},{"id":"proverb-02-q48","number":48,"promptEn":"The story suggests, rather than proves, that nobody may be completely safe from a large enough reward.","promptZh":"這個故事只是暗示，而不是證明，沒有人能完全抵抗足夠大的報酬。","options":[{"id":"key","text":"The story suggests that every man has his price, without proving that everyone can be bought.","reasonZh":"suggests 與 proves 的差別是這題核心。","correct":true},{"id":"foil-1","text":"The story conclusively proves that every man has his price, without proving that everyone can be bought.","reasonZh":"原文只暗示。","correct":false},{"id":"foil-2","text":"The story suggests that every man has his price, while conclusively proving that everyone can be bought.","reasonZh":"不能把沒有證明改成證明。","correct":false},{"id":"foil-3","text":"The story suggests that every man has his price, without proving that everyone earns a fair wage.","reasonZh":"故事談原則受誘惑，不是公平工資。","correct":false}]},{"id":"proverb-02-q49","number":49,"promptEn":"The businessman failed to buy the teacher’s silence. The final scene therefore questions his belief that no one is beyond bribery.","promptZh":"那名商人未能用金錢換取老師保持沉默。因此，最後一幕質疑了他那種「沒有人不能被賄賂」的信念。","options":[{"id":"key","text":"The teacher refuses the businessman’s money, so the final scene questions his belief that every man has his price.","reasonZh":"拒絕買沉默的錢，是對商人信念的挑戰。","correct":true},{"id":"foil-1","text":"The teacher accepts the businessman’s money, so the final scene questions his belief that every man has his price.","reasonZh":"老師沒有收錢。","correct":false},{"id":"foil-2","text":"The teacher refuses the businessman’s money, so the final scene confirms his belief that every man has his price.","reasonZh":"反例質疑普遍主張，不是證實。","correct":false},{"id":"foil-3","text":"The teacher refuses the businessman’s money, so the final scene questions the teacher’s admitted belief that every man has his price.","reasonZh":"信念屬於商人，沒有老師承認的內容。","correct":false}]},{"id":"proverb-02-q50","number":50,"promptEn":"A company director keeps offering a worker more money to hide a serious safety problem. The worker refuses and reports it, showing that the director’s negative view of people is not always correct.","promptZh":"一名公司主管不斷向員工提出更多金錢，要求他隱瞞嚴重的安全問題。員工拒絕並作出舉報，顯示主管對人性的負面看法並非總是正確。","options":[{"id":"key","text":"Although the director acts as if every man has his price, the worker refuses the money and reports the safety problem.","reasonZh":"工人拒收並舉報，反駁董事用錢掩蓋安全問題的假設。","correct":true},{"id":"foil-1","text":"Although the director acts as if every man has his price, the worker accepts the money and reports the safety problem.","reasonZh":"原文拒收。","correct":false},{"id":"foil-2","text":"Although the director acts as if every man has his price, the worker refuses the money and hides the safety problem.","reasonZh":"工人舉報問題，不是掩蓋。","correct":false},{"id":"foil-3","text":"Although the worker acts as if every man has his price, the director refuses the money and reports the safety problem.","reasonZh":"原文董事試圖收買、工人拒收舉報；這句交換了兩人的角色。","correct":false}]},{"id":"proverb-02-x01","number":51,"theme":"science","promptEn":"A company offers a researcher a private grant to hide unfavourable results, assuming a large enough grant will persuade anyone.","promptZh":"公司以私人資助換取研究員隱瞞不利結果，假設只要金額夠大，誰都會答應。","options":[{"id":"key","text":"The company acts as if every man has his price, trying to buy silence about unfavourable results.","reasonZh":"用利益換隱瞞反映收買假設；未說研究員答應。","correct":true},{"id":"foil-1","text":"The company acts as if every man has his price, having already secured silence about unfavourable results.","reasonZh":"嘗試不等於成功。","correct":false},{"id":"foil-2","text":"The company acts as if every man has his price, trying to buy honest publication of all results.","reasonZh":"目的為隱瞞，不是公開。","correct":false},{"id":"foil-3","text":"The company proves conclusively that every man has his price, trying to buy silence about unfavourable results.","reasonZh":"公司行動不是普遍證明。","correct":false}]},{"id":"proverb-02-x02","number":52,"theme":"elections","promptEn":"A donor assumes every candidate will abandon a promise for sufficient funding. One candidate rejects the offer.","promptZh":"捐款者認為每名候選人都會為足夠資助放棄承諾，其中一人拒絕。","options":[{"id":"key","text":"The donor assumes every man has his price, but the candidate’s refusal challenges that view.","reasonZh":"捐款者的犬儒立場受到拒絕的反例挑戰。","correct":true},{"id":"foil-1","text":"The donor assumes every man has his price, but the candidate’s refusal confirms that view.","reasonZh":"拒絕不支持人人可收買。","correct":false},{"id":"foil-2","text":"The candidate assumes every man has his price, but the candidate’s refusal challenges that view.","reasonZh":"主張屬捐款者，不是候選人。","correct":false},{"id":"foil-3","text":"The donor assumes every man has his price, but the candidate’s acceptance challenges that view.","reasonZh":"原文拒絕，沒有接受。","correct":false}]},{"id":"proverb-02-x03","number":53,"theme":"family","promptEn":"An uncle says a cousin will disclose a private family letter for a valuable watch; the cousin refuses.","promptZh":"叔叔認為堂姊會為名貴手錶公開私人家書；堂姊拒絕了。","options":[{"id":"key","text":"The uncle’s “every man has his price” assumption fails here when the cousin refuses the watch.","reasonZh":"price 可是禮物，不限現金；拒絕顯示假設在本例不成立。","correct":true},{"id":"foil-1","text":"The uncle’s “every man has his price” assumption succeeds here when the cousin refuses the watch.","reasonZh":"堂姊沒有出賣家書。","correct":false},{"id":"foil-2","text":"The uncle’s “every man has his price” assumption fails here when the cousin accepts the watch.","reasonZh":"原文明說拒絕。","correct":false},{"id":"foil-3","text":"The uncle’s “every man has his price” assumption fails here when the cousin refuses ordinary payment for published work.","reasonZh":"不是已公開作品的正常稿費，而是私隱交換。","correct":false}]},{"id":"proverb-02-x04","number":54,"theme":"arts","promptEn":"A sponsor believes every juror can be persuaded to ignore quality for an expensive holiday.","promptZh":"贊助者認為昂貴假期足以令每位評審不顧作品質素。","options":[{"id":"key","text":"The sponsor believes every man has his price, treating a holiday as a way to buy the jurors’ decisions.","reasonZh":"用假期收買評審決定，不是一般旅費安排。","correct":true},{"id":"foil-1","text":"The sponsor has demonstrated every man has his price, treating a holiday as a way to buy the jurors’ decisions.","reasonZh":"只有信念，沒有全體接受的事實。","correct":false},{"id":"foil-2","text":"The sponsor believes every man has his price, treating a holiday as a way to reimburse legitimate travel expenses.","reasonZh":"回報是改變判斷，非正常報銷。","correct":false},{"id":"foil-3","text":"The sponsor believes every man has his price, treating a holiday as a way to buy only already corrupt jurors’ decisions.","reasonZh":"原文主張每位，未限於早已貪污者。","correct":false}]},{"id":"proverb-02-x05","number":55,"theme":"sport","promptEn":"A reporter asks whether every man has his price after a club tries to pay a rival to lose. The article gives no answer.","promptZh":"球會試圖付錢令對手故意輸球後，記者問是否人人都有價碼；文章沒有回答。","options":[{"id":"key","text":"The report asks whether every man has his price; the attempted payment alone does not settle the question.","reasonZh":"提出問題與嘗試收買，都不是普遍定論。","correct":true},{"id":"foil-1","text":"The report proves that every man has his price; the attempted payment alone does not settle the question.","reasonZh":"原文明說未回答。","correct":false},{"id":"foil-2","text":"The report asks whether every man has his price; the accepted payment alone does not settle the question.","reasonZh":"題目只說試圖支付。","correct":false},{"id":"foil-3","text":"The report asks whether every man has his price; the attempted payment alone conclusively settles the question.","reasonZh":"單次嘗試不能解決普遍問題。","correct":false}]},{"id":"proverb-02-x06","number":56,"theme":"publicservice","promptEn":"A clerk rejects a luxury car offered for changing a queue position. The giver had assumed nobody could resist it.","promptZh":"有人想送豪華車換取插隊，職員拒絕；送禮者原以為沒人抗拒得到。","options":[{"id":"key","text":"The giver assumed every man has his price, but the clerk refused to sell fair treatment for a car.","reasonZh":"拒收維護公平，挑戰送禮者的假設。","correct":true},{"id":"foil-1","text":"The giver assumed every man has his price, but the clerk agreed to sell fair treatment for a car.","reasonZh":"職員拒絕了。","correct":false},{"id":"foil-2","text":"The clerk assumed every man has his price, but the clerk refused to sell fair treatment for a car.","reasonZh":"假設屬送禮者。","correct":false},{"id":"foil-3","text":"The giver assumed every man has his price, but the clerk refused to sell fair treatment for a normal salary.","reasonZh":"利益是豪華車，非工作薪金。","correct":false}]},{"id":"proverb-02-x07","number":57,"theme":"technology","promptEn":"A hacker offers increasing sums for a private password, convinced that no employee will hold out forever.","promptZh":"駭客不斷加錢索取私人密碼，相信沒有員工會永遠拒絕。","options":[{"id":"key","text":"The hacker’s rising offers reflect the belief that every man has his price; they do not prove a password was sold.","reasonZh":"加價反映意圖，不表示交易完成。","correct":true},{"id":"foil-1","text":"The hacker’s rising offers reflect the belief that every man has his price; they prove a password was sold.","reasonZh":"原文未說有人出售密碼。","correct":false},{"id":"foil-2","text":"The hacker’s falling offers reflect the belief that every man has his price; they do not prove a password was sold.","reasonZh":"原文不斷提高。","correct":false},{"id":"foil-3","text":"The hacker’s rising offers reflect the scientific finding that every man has his price; they do not prove a password was sold.","reasonZh":"這是駭客的假設，不是研究結果。","correct":false}]},{"id":"proverb-02-x08","number":58,"theme":"education","promptEn":"A tutor is offered a gift to leak exam questions but reports the request. The parent thought anyone would agree for enough.","promptZh":"家長以禮物要求導師洩露試題，導師舉報。家長原以為利益足夠誰都會答應。","options":[{"id":"key","text":"The parent thought every man has his price, yet the tutor reported the request instead of leaking the questions.","reasonZh":"舉報與家長預期相反，沒有把正常補習與洩題混同。","correct":true},{"id":"foil-1","text":"The parent thought every man has his price, yet the tutor accepted the gift instead of leaking the questions.","reasonZh":"原文導師舉報。","correct":false},{"id":"foil-2","text":"The parent thought every man has his price, yet the tutor reported the request after leaking the questions.","reasonZh":"沒有先洩露試題的資料。","correct":false},{"id":"foil-3","text":"The tutor thought every man has his price, yet the tutor reported the request instead of leaking the questions.","reasonZh":"收買假設屬家長。","correct":false}]},{"id":"proverb-02-x09","number":59,"theme":"history","promptEn":"A historian describes a ruler who assumed every adviser could be bought. She does not endorse the ruler’s view.","promptZh":"歷史學者描述一位認為所有顧問都能被收買的統治者，但不贊同其看法。","options":[{"id":"key","text":"The historian attributes “every man has his price” to the ruler without endorsing the belief herself.","reasonZh":"歸屬觀點不是作者認同，保持敘述距離。","correct":true},{"id":"foil-1","text":"The historian attributes “every man has his price” to the ruler while endorsing the belief herself.","reasonZh":"原文學者不贊同。","correct":false},{"id":"foil-2","text":"The historian attributes “every man has his price” to all historians without endorsing the belief herself.","reasonZh":"觀點屬統治者，不是所有歷史學者。","correct":false},{"id":"foil-3","text":"The historian verifies as universal fact “every man has his price” to the ruler without endorsing the belief herself.","reasonZh":"歷史描述不是普遍驗證。","correct":false}]},{"id":"proverb-02-x10","number":60,"theme":"environment","promptEn":"An inspector turns down money to conceal illegal dumping. This is one counterexample to a developer’s claim that everyone can be bought.","promptZh":"巡查員拒收掩蓋非法傾倒的錢，成為發展商「人人可收買」主張的一個反例。","options":[{"id":"key","text":"The inspector’s refusal challenges “every man has his price,” but does not show that every inspector is beyond bribery.","reasonZh":"一個反例否定「人人」的絕對性，不能反推所有人皆清廉。","correct":true},{"id":"foil-1","text":"The inspector’s refusal supports “every man has his price,” but does not show that every inspector is beyond bribery.","reasonZh":"拒絕是反例。","correct":false},{"id":"foil-2","text":"The inspector’s refusal challenges “every man has his price,” but proves that every inspector is beyond bribery.","reasonZh":"個人拒絕不能證明全體清廉。","correct":false},{"id":"foil-3","text":"The inspector’s acceptance challenges “every man has his price,” but does not show that every inspector is beyond bribery.","reasonZh":"巡查員拒絕掩蓋非法傾倒的款項，沒有接受。","correct":false}]}],"guide":{"meaning":{"zh":"這是一種犬儒的主張：只要利益夠大，任何人都會出賣原則或忠誠。","en":"A cynical claim that anyone can be persuaded to betray their principles or loyalty for a sufficient reward."},"model":{"zh":"掮客認為連裁判也能買通，便說：「人人都有價碼。」","en":"“Every man has his price,” the fixer said, convinced that even the referee could be bought."},"picture":{"zh":"想像有人把價錢牌掛在「誠實」上；那是他看人的方式，不是大家真的待價而沽。","en":"Imagine someone attaching a price tag to honesty: that is the speaker’s view, not proof that everyone is for sale."},"boundary":{"zh":"不是談正常薪金、商品價格或只談男性。這句傳統說法可指任何人，但不能當成已證實的普遍真理。","en":"It is not about ordinary wages, product prices, or men alone. The traditional wording can refer to anyone, but it is not a proven universal truth."},"where":{"zh":"適合分析反派、賄賂或犬儒立場。若要保持距離，說「他相信……」或「這個故事質疑……」。","en":"Useful for analysing villains, bribery, or cynical attitudes. Attribute it with “he believes…” or “the story questions…” when distancing yourself."},"tone":{"zh":"犬儒、懷疑人的操守；當面對人說，可能像指控他可以被收買。","en":"Cynical and distrustful of integrity; addressed to someone directly, it may sound like an accusation of being corruptible."},"checks":[{"zh":"是否涉及放棄原則，而不只是正常報酬？","en":"Does this involve compromising principles rather than ordinary payment?"},{"zh":"是誰相信這句話？我有保留他的立場嗎？","en":"Whose belief is this, and have I preserved that attribution?"},{"zh":"我有把出價、猜測或故事，錯當成普遍證明嗎？","en":"Am I treating an offer, prediction, or story as universal proof?"}],"readAloud":{"zh":"製片人以為人人都有價碼，但評論員拒絕收錢修改評論。","en":"The producer assumed every man has his price, but the critic refused payment to change her review."},"choices":{"2":{"prompt":{"zh":"哪個情境真正涉及這句諺語的意思？","en":"Which situation involves the proverb’s figurative meaning?"},"options":[{"zh":"承包商認為只要給足利益，任何評審都會偷偷改分。","en":"A contractor thinks a sufficient reward would make any judge secretly change the scores.","reasonZh":"用利益換取違反公正的行動，符合收買原則的意思。","correct":true},{"zh":"承包商根據工時給每位工人公平薪金。","en":"A contractor pays each worker a fair wage based on hours worked.","reasonZh":"公平工作報酬沒有出賣原則，不是這裏的 price。","correct":false},{"zh":"承包商比較三家商店的工具售價。","en":"A contractor compares tool prices at three shops.","reasonZh":"商品售價是字面價格，沒有涉及人的操守。","correct":false}]},"3":{"prompt":{"zh":"你的同學拒絕收禮替人作弊。有人對她說：「Every man has his price。」這句聽來怎樣？","en":"Your classmate refuses a gift to help someone cheat. Someone says to her, “Every man has his price.” How does it sound?"},"options":[{"zh":"像在質疑她的誠信，暗示再多給一點她就會答應。","en":"It questions her integrity, implying that a larger offer would win her over.","reasonZh":"即使使用 man，仍可指她；主張人人可收買容易帶指控。","correct":true},{"zh":"像在稱讚她絕對不會被收買。","en":"It praises her as completely beyond bribery.","reasonZh":"意思正好相反：這句質疑是否有人真能拒絕所有誘惑。","correct":false},{"zh":"只是中性地詢問她補習每小時收多少錢。","en":"It neutrally asks her hourly tutoring rate.","reasonZh":"作弊情境涉及原則，不是正常補習收費。","correct":false}]},"5":{"prompt":{"zh":"委員拒收免費旅程後，遊說者仍打算送更昂貴的禮物。哪句描述最準確？","en":"After a committee member rejects a free trip, a lobbyist plans a more expensive gift. Which description fits?"},"options":[{"zh":"「遊說者仍按『人人都有價碼』的想法行事，儘管委員已拒絕。」","en":"“The lobbyist still acts as if every man has his price, despite the member’s refusal.”","reasonZh":"描述出價者的假設，沒有宣稱委員已收禮。","correct":true},{"zh":"「委員已證明人人都有價碼，因為她拒絕了免費旅程。」","en":"“The member has proved every man has his price by refusing the free trip.”","reasonZh":"拒絕不是接受，不能用作證明可收買。","correct":false},{"zh":"「遊說者已放棄人人都有價碼的想法，所以他打算送更貴的禮物。」","en":"“The lobbyist has abandoned the belief that every man has his price, so he plans a costlier gift.”","reasonZh":"繼續加碼正反映他仍持有假設，並非放棄。","correct":false}]},"6":{"prompt":{"zh":"展覽中一名守衛拒絕所有偷畫報酬。哪個結論沒有越過證據？","en":"A gallery guard rejects every offer to help steal a painting. Which conclusion stays within the evidence?"},"options":[{"zh":"這名守衛的拒絕挑戰「人人都有價碼」，但不證明所有人都不可收買。","en":"This guard’s refusal challenges “every man has his price,” without proving that nobody can be bribed.","reasonZh":"一個拒絕者足以挑戰「人人」，卻不能證明相反的「無人」。","correct":true},{"zh":"這證明只要再提高報酬，他必定答應。","en":"This proves he must agree if the reward rises further.","reasonZh":"拒絕沒有提供未來一定接受的證據。","correct":false},{"zh":"這證明這句話只能用於買賣畫作，不能談其他原則。","en":"This proves the saying concerns only paintings, not other principles.","reasonZh":"畫作只是本例場景，諺語不限於藝術品。","correct":false}]}}}},"proverb-03":{"id":"proverb-03","titleEn":"Once Bitten, Twice Shy","titleZh":"一朝被蛇咬，十年怕草繩","version":"2026-10-28.1","items":[{"id":"proverb-03-q01","number":1,"promptEn":"The bakery delivered my birthday cake a day late last year. I now check the delivery date carefully before ordering from it.","promptZh":"那間餅店去年遲了一天才送到我的生日蛋糕。我現在向它訂購前，會仔細確認送貨日期。","options":[{"id":"key","text":"Once bitten, twice shy: last year the bakery delivered my cake a day late, so I now check the delivery date before ordering from it.","reasonZh":"去年蛋糕遲送一天，現在訂購前查日期；經歷與後續防範連成因果。","correct":true},{"id":"foil-1","text":"Once bitten, twice shy: last year the bakery delivered my cake a week early, so I now check the delivery date before ordering from it.","reasonZh":"原文遲一天，不是早一星期。","correct":false},{"id":"foil-2","text":"Once bitten, twice shy: last year the bakery delivered my cake a day late, so I now check the delivery date only after paying from it.","reasonZh":"原文訂購前確認，不是付款後才問。","correct":false},{"id":"foil-3","text":"Once bitten, twice shy: last year the bakery delivered my cake a day late, so I now avoid every bakery forever before ordering from it.","reasonZh":"原文仍可向同店訂購，只加強確認。","correct":false}]},{"id":"proverb-03-q02","number":2,"promptEn":"An online seller sent Nina a damaged phone. She now reads every customer review before buying another phone online.","promptZh":"一名網上賣家把損壞了的電話寄給 Nina。她現在網購另一部電話前，會閱讀每一則顧客評論。","options":[{"id":"key","text":"After receiving a damaged phone, Nina now reads every customer review before buying another phone online—once bitten, twice shy.","reasonZh":"損壞電話令 Nina 網購前讀每則評論；沒有停止所有網購。","correct":true},{"id":"foil-1","text":"After receiving a damaged phone, Nina now reads only the seller’s slogan before buying another phone online—once bitten, twice shy.","reasonZh":"原文是每則顧客評論，不是賣家的口號。","correct":false},{"id":"foil-2","text":"After receiving a damaged phone, Nina now reads every customer review after buying another phone online—once bitten, twice shy.","reasonZh":"先查評論再買，不能倒轉。","correct":false},{"id":"foil-3","text":"After receiving a phone she had damaged herself, Nina now reads every customer review before buying another phone online—once bitten, twice shy.","reasonZh":"原文賣家寄來已損壞的電話，並非 Nina 自己弄壞。","correct":false}]},{"id":"proverb-03-q03","number":3,"promptEn":"Omar’s previous group partner did none of the work. Omar is therefore careful about choosing the same partner again.","promptZh":"Omar 上次的小組伙伴完全沒有工作。因此，Omar 對再次選擇同一名伙伴十分謹慎。","options":[{"id":"key","text":"Omar’s partner did none of the work, so he is careful about choosing the same partner again—once bitten, twice shy.","reasonZh":"Omar 對再次選同一位不做事的伙伴謹慎；沒有推論所有人都不可靠。","correct":true},{"id":"foil-1","text":"Omar’s partner did most of the work, so he is careful about choosing the same partner again—once bitten, twice shy.","reasonZh":"原文伙伴完全沒工作。","correct":false},{"id":"foil-2","text":"Omar’s partner did none of the work, so he is careful about choosing any partner whatsoever again—once bitten, twice shy.","reasonZh":"原文針對同一伙伴，不是拒絕所有人。","correct":false},{"id":"foil-3","text":"Omar’s partner did none of the work, so he is eager to choose without checking the same partner again—once bitten, twice shy.","reasonZh":"謹慎與不作考慮便急於選擇相反。","correct":false}]},{"id":"proverb-03-q04","number":4,"promptEn":"The family’s hotel room was dirty on their last holiday. They now check recent photographs before booking a room.","promptZh":"這個家庭上次旅行時入住的酒店房間十分骯髒。他們現在訂房前會查看近期照片。","options":[{"id":"key","text":"After the dirty hotel room on their last holiday, the family now checks recent photographs before booking—once bitten, twice shy.","reasonZh":"髒房間是先前壞經驗，近期照片是現在訂房前的檢查。","correct":true},{"id":"foil-1","text":"After the dirty hotel room on their last holiday, the family now checks only the oldest photographs before booking—once bitten, twice shy.","reasonZh":"原文近期照片，不是只看最舊的。","correct":false},{"id":"foil-2","text":"After the dirty hotel room on their last holiday, the family now checks recent photographs after checking out—once bitten, twice shy.","reasonZh":"防範在訂房前，不是退房後。","correct":false},{"id":"foil-3","text":"After the perfectly clean hotel room on their last holiday, the family now checks recent photographs before booking—once bitten, twice shy.","reasonZh":"乾淨房間抹掉了導致戒心的壞經驗。","correct":false}]},{"id":"proverb-03-q05","number":5,"promptEn":"I lent a friend money, but the friend never repaid me. I will not lend that person more money.","promptZh":"我曾借錢給一名朋友，但對方一直沒有還錢。我不會再借錢給那個人。","options":[{"id":"key","text":"My friend never repaid me, so I will not lend that friend more money—once bitten, twice shy.","reasonZh":"朋友未還錢，說話者拒絕再借給同一人；不是拒絕所有朋友。","correct":true},{"id":"foil-1","text":"My friend never repaid me, so I will not lend every friend I have more money—once bitten, twice shy.","reasonZh":"原文只針對未還錢的朋友。","correct":false},{"id":"foil-2","text":"My friend repaid me early, so I will not lend that friend more money—once bitten, twice shy.","reasonZh":"未償還與提早還清相反。","correct":false},{"id":"foil-3","text":"My friend never repaid me, so I have promised to lend that friend more money—once bitten, twice shy.","reasonZh":"拒絕再借，不是承諾借出。","correct":false}]},{"id":"proverb-03-q06","number":6,"promptEn":"Eva’s writing app once lost an important piece of work. She now saves an extra copy of every document.","promptZh":"Eva 的寫作應用程式曾遺失一份重要文件。她現在會為每份文件額外保存一個副本。","options":[{"id":"key","text":"Eva’s app lost an important piece of work; once bitten, twice shy, she now saves an extra copy of every document.","reasonZh":"Eva 曾遺失重要作品，因此每份文件多存一份；every 的範圍保留。","correct":true},{"id":"foil-1","text":"Eva’s app lost an important piece of work; once bitten, twice shy, she now saves an extra copy of only unimportant documents.","reasonZh":"原文每份文件，不只不重要的。","correct":false},{"id":"foil-2","text":"Eva’s app lost an important piece of work; once bitten, twice shy, she now saves just the original copy of every document.","reasonZh":"extra 是額外副本，原檔本身不算。","correct":false},{"id":"foil-3","text":"Eva’s app made all her work safer; once bitten, twice shy, she now saves an extra copy of every document.","reasonZh":"原先的事故是遺失，不是改善安全。","correct":false}]},{"id":"proverb-03-q07","number":7,"promptEn":"Hana paid for ten lessons, but the tutor repeatedly cancelled them. She now books only one lesson at a time.","promptZh":"Hana 支付了十堂課的費用，但導師多次取消課堂。她現在每次只會預訂一堂課。","options":[{"id":"key","text":"Since her tutor repeatedly cancelled lessons from her prepaid block of ten, Hana books only one lesson at a time—once bitten, twice shy.","reasonZh":"Hana 預付十堂卻被多次取消，改為每次一堂；仍會上課。","correct":true},{"id":"foil-1","text":"Since her tutor repeatedly cancelled one free lesson, Hana books only one lesson at a time—once bitten, twice shy.","reasonZh":"原文十堂已付費，不是一堂免費課。","correct":false},{"id":"foil-2","text":"Since her tutor repeatedly cancelled lessons from her prepaid block of ten, Hana books a full year of lessons at a time—once bitten, twice shy.","reasonZh":"縮小承諾才符合原文的防範。","correct":false},{"id":"foil-3","text":"Since her tutor always delivered lessons from her prepaid block of ten, Hana books only one lesson at a time—once bitten, twice shy.","reasonZh":"原文導師多次取消，非每次如期授課。","correct":false}]},{"id":"proverb-03-q08","number":8,"promptEn":"Ben felt ill after eating at that restaurant. He is now unwilling to eat there again.","promptZh":"Ben 在那間餐廳吃東西後感到不適。他現在不願再次到那裏用膳。","options":[{"id":"key","text":"It is a case of once bitten, twice shy for Ben: after feeling ill there, he is unwilling to eat at the restaurant again.","reasonZh":"Ben 在該餐廳吃後不適，因而不願再去；不能擴大到不再吃任何食物。","correct":true},{"id":"foil-1","text":"It is a case of once bitten, twice shy for Ben: after feeling ill there, he is unwilling to eat at any restaurant ever again.","reasonZh":"原文只說那間餐廳。","correct":false},{"id":"foil-2","text":"It is a case of once bitten, twice shy for Ben: before he had ever eaten there, he is unwilling to eat at the restaurant again.","reasonZh":"戒心是壞經驗之後，不是從未去過。","correct":false},{"id":"foil-3","text":"It is a case of once bitten, twice shy for Ben: after feeling ill there, he is eager to eat at the restaurant again.","reasonZh":"原文不願意，並非熱切想去。","correct":false}]},{"id":"proverb-03-q09","number":9,"promptEn":"The cheap paint we bought began to fall off the wall within a month. We will choose a better brand next time.","promptZh":"我們購買的廉價油漆在一個月內便開始從牆上剝落。下次我們會選擇較好的品牌。","options":[{"id":"key","text":"The paint peeled within a month, so we will choose a better brand next time—once bitten, twice shy.","reasonZh":"油漆一個月內剝落，下次改選較好品牌；保留時間與計劃。","correct":true},{"id":"foil-1","text":"The paint peeled after twenty years, so we will choose a better brand next time—once bitten, twice shy.","reasonZh":"剝落時間是品質問題的線索，不能改為二十年後。","correct":false},{"id":"foil-2","text":"The paint peeled within a month, so we will choose the same cheap paint without checking next time—once bitten, twice shy.","reasonZh":"原文決定較好品牌，不是毫不檢查繼續用舊款。","correct":false},{"id":"foil-3","text":"The paint peeled within a month, so we will choose a better brand before this purchase—once bitten, twice shy.","reasonZh":"計劃在下次實行，不是之前已做。","correct":false}]},{"id":"proverb-03-q10","number":10,"promptEn":"Amir once bought a fake concert ticket. He now buys tickets only from official websites.","promptZh":"Amir 曾經買到一張假音樂會門票。他現在只會在官方網站購買門票。","options":[{"id":"key","text":"As the saying goes, once bitten, twice shy: after buying a fake concert ticket, Amir now buys tickets only from official websites.","reasonZh":"Amir 買過假票後只向官方網站購票；仍可參與音樂會。","correct":true},{"id":"foil-1","text":"As the saying goes, once bitten, twice shy: after buying a fake concert ticket, Amir now buys tickets from whichever site is cheapest.","reasonZh":"原文明定只用官方網站，不是只看價格。","correct":false},{"id":"foil-2","text":"As the saying goes, once bitten, twice shy: after buying a valid concert ticket, Amir now buys tickets only from official websites.","reasonZh":"假票才是壞經驗，真票沒有這項問題。","correct":false},{"id":"foil-3","text":"As the saying goes, once bitten, twice shy: after buying a fake concert ticket, Amir has stopped buying any tickets only from official websites.","reasonZh":"原文繼續購票，只改變渠道。","correct":false}]},{"id":"proverb-03-q11","number":11,"promptEn":"Priya once missed a flight because her bus arrived very late. She will leave home much earlier next time.","promptZh":"Priya 曾因巴士嚴重延誤而錯過航班。下次她會提早很多離開家中。","options":[{"id":"key","text":"After missing a flight because her bus was late, Priya will leave home much earlier next time—once bitten, twice shy.","reasonZh":"Priya 因遲到巴士錯過航班，決定下次提早很多出門。","correct":true},{"id":"foil-1","text":"After missing a flight because she chose to sleep late, Priya will leave home much earlier next time—once bitten, twice shy.","reasonZh":"原文原因是巴士延誤，非故意睡懶覺。","correct":false},{"id":"foil-2","text":"After missing a flight because her bus was late, Priya will leave home at the same time next time—once bitten, twice shy.","reasonZh":"原文會提早很多，不是維持原定時間。","correct":false},{"id":"foil-3","text":"After missing a flight because her bus was late, Priya has always left home much earlier next time—once bitten, twice shy.","reasonZh":"將來的改變不等於一向如此。","correct":false}]},{"id":"proverb-03-q12","number":12,"promptEn":"Marcus’s previous manager changed his pay after he had accepted the job. Marcus may refuse another job unless the pay is confirmed in writing.","promptZh":"Marcus 的上一名經理在他接受工作後更改了薪金。除非薪金以書面確認，否則 Marcus 可能會拒絕另一份工作。","options":[{"id":"key","text":"His previous manager changed his pay after he accepted the job; once bitten, twice shy, Marcus may refuse another job unless the pay is confirmed in writing.","reasonZh":"上一份工的薪金被事後更改，所以 Marcus 可能要求書面確認才接受另一份工。","correct":true},{"id":"foil-1","text":"His previous manager changed his pay after he accepted the job; once bitten, twice shy, Marcus has definitely refused another job unless the pay is confirmed in writing.","reasonZh":"may 只是可能，不能改成已確實拒絕。","correct":false},{"id":"foil-2","text":"His previous manager changed his pay after he accepted the job; once bitten, twice shy, Marcus may refuse another job even if the pay is confirmed in writing.","reasonZh":"unless 保留可接受的條件，even if 表示條件也無用。","correct":false},{"id":"foil-3","text":"His previous manager changed his pay before he applied for the job; once bitten, twice shy, Marcus may refuse another job unless the pay is confirmed in writing.","reasonZh":"原文接受後才改薪，不是申請前。","correct":false}]},{"id":"proverb-03-q13","number":13,"promptEn":"I had lost all my photographs when my only storage drive stopped working. By the following year, I was keeping two copies of every photograph.","promptZh":"我唯一的儲存裝置失靈時，所有照片都遺失了。到了下一年，我已開始為每張照片保存兩個副本。","options":[{"id":"key","text":"By the following year, after my only storage drive failed and I lost all my photographs, I was keeping two copies of every photograph—once bitten, twice shy.","reasonZh":"唯一儲存裝置壞掉導致全失；到了下一年，每張照片都有兩份。","correct":true},{"id":"foil-1","text":"Before the drive had ever failed, after my only storage drive failed and I lost all my photographs, I was keeping two copies of every photograph—once bitten, twice shy.","reasonZh":"原文是事故後，到下一年已養成習慣。","correct":false},{"id":"foil-2","text":"By the following year, after my only storage drive failed and I lost all my photographs, I was keeping one copy of selected photographs—once bitten, twice shy.","reasonZh":"原文每張兩份，不是部分照片一份。","correct":false},{"id":"foil-3","text":"By the following year, after my spare drive worked perfectly, I was keeping two copies of every photograph—once bitten, twice shy.","reasonZh":"原文唯一裝置失靈，不能換成備用裝置正常。","correct":false}]},{"id":"proverb-03-q14","number":14,"promptEn":"A: Why will you not pay for a full year at the new gym? B: The last gym closed only two months after I joined.","promptZh":"甲：你為甚麼不願支付新健身中心一整年的費用？乙：我加入上一間健身中心後僅兩個月，它便倒閉了。","options":[{"id":"key","text":"My last gym closed two months after I joined; once bitten, twice shy, I will not pay for a full year at the new gym.","reasonZh":"舊健身中心入會兩個月便倒閉，說話者因此不願預付新中心整年費用。","correct":true},{"id":"foil-1","text":"My last gym closed ten years after I joined; once bitten, twice shy, I will not pay for a full year at the new gym.","reasonZh":"倒閉距入會只有兩個月，不是十年。","correct":false},{"id":"foil-2","text":"My last gym closed two months after I joined; once bitten, twice shy, I will not pay for a single visit at the new gym.","reasonZh":"原文拒絕整年預付，未說單次也不付。","correct":false},{"id":"foil-3","text":"My last gym gave me excellent service two months after I joined; once bitten, twice shy, I will not pay for a full year at the new gym.","reasonZh":"倒閉才是受損經驗，不是服務出色。","correct":false}]},{"id":"proverb-03-q15","number":15,"promptEn":"The Chens’ first house had several hidden water leaks. When they bought their second home, they paid someone to check it carefully.","promptZh":"陳家購買的第一間房屋有多處隱藏漏水問題。他們購買第二間房屋時，付費請人仔細檢查。","options":[{"id":"key","text":"After hidden leaks in their first house, the Chens paid someone to inspect their second home before buying it—once bitten, twice shy.","reasonZh":"陳家首間房有暗漏，買第二間時付費驗屋；不是檢查後才發現首間問題。","correct":true},{"id":"foil-1","text":"After hidden leaks in their first house, the Chens paid someone to inspect their first home before buying it—once bitten, twice shy.","reasonZh":"原文檢查的是第二間。","correct":false},{"id":"foil-2","text":"After hidden leaks in their first house, the Chens skipped inspection to save money when buying their second home—once bitten, twice shy.","reasonZh":"原文付費檢查，並非省略。","correct":false},{"id":"foil-3","text":"After no plumbing problems in their first house, the Chens paid someone to inspect their second home before buying it—once bitten, twice shy.","reasonZh":"首間有隱藏漏水，不能改為沒有問題。","correct":false}]},{"id":"proverb-03-q16","number":16,"promptEn":"A school bus company had repeatedly arrived late. Before signing another agreement, the school decided to check the company’s record carefully.","promptZh":"一間校巴公司曾多次遲到。學校決定在簽署另一份協議前，仔細查核該公司的紀錄。","options":[{"id":"key","text":"After the bus company repeatedly arrived late, the school decided to check its record before signing another agreement—once bitten, twice shy.","reasonZh":"校巴多次遲到後，學校決定簽新約前查紀錄；保留已作決定的時態。","correct":true},{"id":"foil-1","text":"After the bus company repeatedly arrived late, the school decided to ignore its record before signing another agreement—once bitten, twice shy.","reasonZh":"原文決定查核，不是忽略。","correct":false},{"id":"foil-2","text":"After the bus company repeatedly arrived late, the school decided to check its record only after signing another agreement—once bitten, twice shy.","reasonZh":"簽約前的預防不能改成簽後。","correct":false},{"id":"foil-3","text":"After the bus company always arrived early, the school decided to check its record before signing another agreement—once bitten, twice shy.","reasonZh":"原文多次遲到，不是每次提早。","correct":false}]},{"id":"proverb-03-q17","number":17,"promptEn":"Asha once developed a rash after using an unfamiliar skin cream. She now tests a small amount before using any new cream.","promptZh":"Asha 曾在使用一種陌生的護膚霜後出現紅疹。她現在使用任何新護膚霜前，都會先試用少量。","options":[{"id":"key","text":"Because an unfamiliar cream once caused a rash, Asha now tests a small amount before using any new cream—once bitten, twice shy.","reasonZh":"Asha 過去用陌生護膚霜出疹，現在每款新霜先試少量；這是在描述她的行為。","correct":true},{"id":"foil-1","text":"Because an unfamiliar cream once caused a rash, Asha now tests a small amount before using only the old cream—once bitten, twice shy.","reasonZh":"原文每款新的護膚霜，不是只試舊款。","correct":false},{"id":"foil-2","text":"Because an unfamiliar cream once caused a rash, Asha now tests a full faceful immediately before using any new cream—once bitten, twice shy.","reasonZh":"原文先少量試用，不是立即大量用。","correct":false},{"id":"foil-3","text":"Because an unfamiliar cream had never caused any reaction, Asha now tests a small amount before using any new cream—once bitten, twice shy.","reasonZh":"題目已有一次紅疹經驗。","correct":false}]},{"id":"proverb-03-q18","number":18,"promptEn":"The manager introduced the previous service too quickly, and many customers complained. This time, she will test the service first.","promptZh":"經理上次太快推出新服務，結果很多顧客投訴。今次她會先測試服務。","options":[{"id":"key","text":"The manager introduced the last service too quickly and received many complaints; this time she will test it first—once bitten, twice shy.","reasonZh":"上次服務推出過急被投訴，今次經理先測試；先前問題與改變均有交代。","correct":true},{"id":"foil-1","text":"The manager introduced the last service after extensive successful testing and received many complaints; this time she will test it first—once bitten, twice shy.","reasonZh":"原文推出過急，非充分測試成功後才推。","correct":false},{"id":"foil-2","text":"The manager introduced the last service too quickly and received many complaints; this time she will release it immediately without a test—once bitten, twice shy.","reasonZh":"原文今次會先測試。","correct":false},{"id":"foil-3","text":"The manager introduced the last service too quickly and received unanimous praise; this time she will test it first—once bitten, twice shy.","reasonZh":"上次收到投訴，不是全體讚賞。","correct":false}]},{"id":"proverb-03-q19","number":19,"promptEn":"Jay shared his password with a teammate, who then changed his account settings. Jay no longer shares his password with anyone.","promptZh":"Jay 把密碼告訴一名隊友，而對方其後更改了他的帳戶設定。Jay 現在不再與任何人分享密碼。","options":[{"id":"key","text":"After a teammate changed his account settings, Jay stopped sharing his password with anyone—once bitten, twice shy.","reasonZh":"隊友更改帳戶設定後，Jay 不再向任何人分享密碼；anyone 保留範圍。","correct":true},{"id":"foil-1","text":"After a teammate changed his account settings, Jay stopped sharing his password with only that teammate—once bitten, twice shy.","reasonZh":"原文不向任何人分享，不只限制那名隊友。","correct":false},{"id":"foil-2","text":"After a teammate kept every setting untouched, Jay stopped sharing his password with anyone—once bitten, twice shy.","reasonZh":"原文隊友改了設定。","correct":false},{"id":"foil-3","text":"After a teammate changed his account settings, Jay started publishing his password with anyone—once bitten, twice shy.","reasonZh":"停止分享與公開密碼相反。","correct":false}]},{"id":"proverb-03-q20","number":20,"promptEn":"The club’s outdoor event was cancelled because it had no plan for rain. The club now always prepares an indoor plan.","promptZh":"學會的戶外活動因沒有雨天安排而被取消。學會現在每次都會準備室內後備方案。","options":[{"id":"key","text":"The club’s event was cancelled without a rain plan, so it now always prepares an indoor plan—once bitten, twice shy.","reasonZh":"活動因沒有雨天方案取消，學會現在每次備室內方案；不是永不辦戶外活動。","correct":true},{"id":"foil-1","text":"The club’s event was cancelled without a rain plan, so it now occasionally considers an indoor plan—once bitten, twice shy.","reasonZh":"原文每次準備，不是偶爾考慮。","correct":false},{"id":"foil-2","text":"The club’s event was cancelled without a rain plan, so it now always prepares only an outdoor plan—once bitten, twice shy.","reasonZh":"原文新增室內後備方案。","correct":false},{"id":"foil-3","text":"The club’s event went ahead without disruption without a rain plan, so it now always prepares an indoor plan—once bitten, twice shy.","reasonZh":"原先活動取消，不是順利舉行。","correct":false}]},{"id":"proverb-03-q21","number":21,"promptEn":"A: Why are you asking the builder for a written price? B: The last builder charged me much more than we had agreed.","promptZh":"甲：你為甚麼要求建築工人提供書面報價？乙：上一名建築工人收取的費用比我們原先同意的高很多。","options":[{"id":"key","text":"“Once bitten, twice shy: the last builder charged much more than we agreed, so I am asking for a written price.”","reasonZh":"上次收費超出協議，所以這次先索取書面報價；沒有說新工人已經多收。","correct":true},{"id":"foil-1","text":"“Once bitten, twice shy: the new builder charged much more than we agreed, so I am asking for a written price.”","reasonZh":"多收的是上一位，不能指控新一位已多收。","correct":false},{"id":"foil-2","text":"“Once bitten, twice shy: the last builder charged much less than we agreed, so I am asking for a written price.”","reasonZh":"原文收得更多，不是更少。","correct":false},{"id":"foil-3","text":"“Once bitten, twice shy: the last builder charged much more than we agreed, so I am asking for a verbal promise only.”","reasonZh":"要求書面報價，非只要口頭承諾。","correct":false}]},{"id":"proverb-03-q22","number":22,"promptEn":"A: Are you going to use that travel website again? B: No. Last time, I arrived at the hotel and discovered that it had no record of my booking.","promptZh":"甲：你會再次使用那個旅遊網站嗎？乙：不會。上次我到達酒店後，才發現酒店沒有我的預訂紀錄。","options":[{"id":"key","text":"No, I will not use that travel website again—once bitten, twice shy. Last time, the hotel had no record of my booking.","reasonZh":"酒店沒有預訂紀錄，說話者不再用該網站；對象是同一網站。","correct":true},{"id":"foil-1","text":"No, I will not use every travel website again—once bitten, twice shy. Last time, the hotel had no record of my booking.","reasonZh":"原文只拒絕用那個網站。","correct":false},{"id":"foil-2","text":"No, I will not use that travel website again—once bitten, twice shy. Last time, the hotel had a confirmed record of my booking.","reasonZh":"原文無紀錄，不能改成確認成功。","correct":false},{"id":"foil-3","text":"No, I will not use that travel website again—once bitten, twice shy. Every time in my life, the hotel had no record of my booking.","reasonZh":"只有上次經驗，不能擴大到一生每次。","correct":false}]},{"id":"proverb-03-q23","number":23,"promptEn":"A friend shared Suki’s private secret with other people. Suki is now careful about trusting people too quickly.","promptZh":"一名朋友把 Suki 的私人秘密告訴其他人。Suki 現在不會太快信任別人。","options":[{"id":"key","text":"After a friend shared her private secret, Suki became careful about trusting people too quickly—once bitten, twice shy.","reasonZh":"Suki 被朋友洩密後較謹慎，不等於永遠不再信任任何人。","correct":true},{"id":"foil-1","text":"After a friend shared her private secret, Suki became determined never to trust anyone—once bitten, twice shy.","reasonZh":"謹慎的程度不能擴大為永不信人。","correct":false},{"id":"foil-2","text":"After a friend kept her private secret safe, Suki became careful about trusting people too quickly—once bitten, twice shy.","reasonZh":"原文朋友洩密，非保密。","correct":false},{"id":"foil-3","text":"Long before a friend shared her private secret, Suki became careful about trusting people too quickly—once bitten, twice shy.","reasonZh":"戒心是在洩密之後，不是很久之前。","correct":false}]},{"id":"proverb-03-q24","number":24,"promptEn":"Raj once paid an unknown seller in full, but the product never arrived. He now refuses to pay another unknown seller before receiving the item.","promptZh":"Raj 曾向一名陌生賣家支付全數款項，但貨品一直沒有送到。他現在拒絕在收到貨品前向另一名陌生賣家支付全數款項。","options":[{"id":"key","text":"Once bitten, twice shy: after his prepaid purchase never arrived, Raj will not pay another unknown seller in full before receiving the item.","reasonZh":"Raj 曾全額付款卻沒收貨，現在拒絕收貨前全付；未要求他停止購物。","correct":true},{"id":"foil-1","text":"Once bitten, twice shy: after his prepaid purchase never arrived, Raj will not pay another unknown seller in full after receiving the item.","reasonZh":"原文避免收貨前全付，不能改成收貨後也不付。","correct":false},{"id":"foil-2","text":"Once bitten, twice shy: after his prepaid purchase arrived early in perfect condition, Raj will not pay another unknown seller in full before receiving the item.","reasonZh":"舊交易沒有到貨，不是完美完成。","correct":false},{"id":"foil-3","text":"Once bitten, twice shy: after his prepaid purchase never arrived, Raj will not pay only his closest friend in full before receiving the item.","reasonZh":"原文新的陌生賣家，不是好友。","correct":false}]},{"id":"proverb-03-q25","number":25,"promptEn":"A restaurant owner added a new dish to the menu without testing it, and much of the food was wasted. She now prepares only a small amount of each new dish first.","promptZh":"一名餐廳東主未經測試便把一道新菜式加入餐單，結果浪費了大量食物。她現在會先試做少量新菜式。","options":[{"id":"key","text":"After much food was wasted, the owner now tests a small amount of each new dish before adding it to the menu—once bitten, twice shy.","reasonZh":"菜式未試就推出浪費很多，餐廳現在每款新菜先做少量測試。","correct":true},{"id":"foil-1","text":"After much food was wasted, the owner now tests a large untested batch of each new dish before adding it to the menu—once bitten, twice shy.","reasonZh":"先少量試做，不是未試便大量生產。","correct":false},{"id":"foil-2","text":"After much food was wasted, the owner now tests a small amount of only long-established dishes before adding it to the menu—once bitten, twice shy.","reasonZh":"原文針對新菜，不是已有老菜。","correct":false},{"id":"foil-3","text":"After every portion sold immediately, the owner now tests a small amount of each new dish before adding it to the menu—once bitten, twice shy.","reasonZh":"原先問題是浪費，不是全部賣光。","correct":false}]},{"id":"proverb-03-q26","number":26,"promptEn":"A student accidentally deleted the class’s only project file last year. The teacher now keeps two copies of every class file.","promptZh":"一名學生去年意外刪除了全班唯一的項目檔案。老師現在會為每個班級檔案保存兩個副本。","options":[{"id":"key","text":"Because a student deleted the only project file last year, the teacher now keeps two copies of every class file—once bitten, twice shy.","reasonZh":"去年唯一專題檔案被誤刪，老師現在所有班級檔案留兩份。","correct":true},{"id":"foil-1","text":"Because a student deleted the only project file last year, the teacher now keeps two copies of only that one project—once bitten, twice shy.","reasonZh":"原文每個班級檔案，不只上次專題。","correct":false},{"id":"foil-2","text":"Because a student deleted the only project file next year, the teacher now keeps two copies of every class file—once bitten, twice shy.","reasonZh":"刪檔已在去年發生，不是明年。","correct":false},{"id":"foil-3","text":"Because a student deleted the only project file last year, the teacher now keeps a single copy of every class file—once bitten, twice shy.","reasonZh":"原文明確是兩份。","correct":false}]},{"id":"proverb-03-q27","number":27,"promptEn":"Clara collected a parcel from a shop but later discovered that one item was missing. She now checks every parcel before leaving the shop.","promptZh":"Clara 從店舖領取包裹後，才發現其中一件貨品不見了。她現在離開店舖前都會檢查每個包裹。","options":[{"id":"key","text":"The missing item made Clara check every parcel before leaving the shop—once bitten, twice shy.","reasonZh":"Clara 收到缺件包裹後，現在每個包裹離店前檢查。","correct":true},{"id":"foil-1","text":"The missing item made Clara check only visibly damaged parcels before leaving the shop—once bitten, twice shy.","reasonZh":"原文每個包裹，不只外觀損壞的。","correct":false},{"id":"foil-2","text":"The missing item made Clara check every parcel after getting home—once bitten, twice shy.","reasonZh":"原文離店前，不是回家後。","correct":false},{"id":"foil-3","text":"The unexpected free gift made Clara check every parcel before leaving the shop—once bitten, twice shy.","reasonZh":"導致戒心的是缺件，不是禮物。","correct":false}]},{"id":"proverb-03-q28","number":28,"promptEn":"Joel thought a free trial would be easy to cancel, but the company charged him for three months. He now reads all the cancellation rules first.","promptZh":"Joel 以為免費試用可以輕易取消，但公司收取了他三個月的費用。他現在會先閱讀所有取消條款。","options":[{"id":"key","text":"Once bitten, twice shy: after being charged for three months, Joel now reads all the cancellation rules before starting a free trial.","reasonZh":"Joel 試用後被收三個月費用，現在先讀全部取消條款；不是單看價錢。","correct":true},{"id":"foil-1","text":"Once bitten, twice shy: after being charged for three months, Joel now reads only the advertised monthly price before starting a free trial.","reasonZh":"原文全部取消條款，不是月費廣告。","correct":false},{"id":"foil-2","text":"Once bitten, twice shy: after being charged for three days, Joel now reads all the cancellation rules before starting a free trial.","reasonZh":"被收費三個月，不是三天。","correct":false},{"id":"foil-3","text":"Once bitten, twice shy: after being charged for three months, Joel now reads all the cancellation rules after finishing a free trial.","reasonZh":"先閱讀才試用，不是結束後才看。","correct":false}]},{"id":"proverb-03-q29","number":29,"promptEn":"The group held last year’s picnic in an uncovered area, and everyone became too hot. This year, they have booked a covered area.","promptZh":"小組去年在沒有遮蓋的地方舉行野餐，所有人都熱得受不了。今年他們預訂了有遮蓋的地方。","options":[{"id":"key","text":"After last year’s picnic left everyone too hot, the group booked a covered area this year—once bitten, twice shy.","reasonZh":"去年無遮蓋野餐太熱，今年預訂有遮蓋位置；是針對實際不適作調整。","correct":true},{"id":"foil-1","text":"After last year’s picnic left everyone too hot, the group booked a another uncovered area this year—once bitten, twice shy.","reasonZh":"原文改為有遮蓋位置。","correct":false},{"id":"foil-2","text":"After last year’s picnic left everyone too cold, the group booked a covered area this year—once bitten, twice shy.","reasonZh":"原文是熱得受不了，不是太冷。","correct":false},{"id":"foil-3","text":"After last year’s picnic left everyone too hot, the group booked a covered area the year before that picnic—once bitten, twice shy.","reasonZh":"改變在今年，不是事故之前。","correct":false}]},{"id":"proverb-03-q30","number":30,"promptEn":"Mei accepted too many volunteer duties and became exhausted before she could finish them. She now accepts only one volunteer duty at a time.","promptZh":"Mei 接受了太多義務工作，在完成所有工作前便已筋疲力盡。她現在每次只會接受一項義務工作。","options":[{"id":"key","text":"For Mei, it was a case of once bitten, twice shy: after becoming exhausted, she began accepting only one volunteer duty at a time.","reasonZh":"Mei 工作過多而累垮，改成一次一項義工職務；沒有完全放棄義工。","correct":true},{"id":"foil-1","text":"For Mei, it was a case of once bitten, twice shy: after becoming exhausted, she began accepting several volunteer duties at a time.","reasonZh":"原文每次只接一項。","correct":false},{"id":"foil-2","text":"For Mei, it was a case of once bitten, twice shy: after finding every task effortless, she began accepting only one volunteer duty at a time.","reasonZh":"疲憊是教訓，並非輕鬆完成。","correct":false},{"id":"foil-3","text":"For Mei, it was a case of once bitten, twice shy: after becoming exhausted, she permanently stopped accepting only one volunteer duty at a time.","reasonZh":"她仍接受一項，不是永遠停止。","correct":false}]},{"id":"proverb-03-q31","number":31,"promptEn":"Although Chloe’s new landlord seems friendly, she asks for every agreement in writing because her previous landlord unfairly kept part of her deposit.","promptZh":"雖然 Chloe 的新業主看來十分友善，但她要求所有協議以書面確認，因為上一名業主曾不公平地扣起她部分按金。","options":[{"id":"key","text":"Although Chloe’s new landlord seems friendly, she asks for every agreement in writing after unfairly losing part of her previous deposit—once bitten, twice shy.","reasonZh":"新業主友善也不足以消除舊按金糾紛的戒心，她仍要求所有協議書面化。","correct":true},{"id":"foil-1","text":"Although Chloe’s new landlord seems friendly, she asks for only the smallest agreement in writing after unfairly losing part of her previous deposit—once bitten, twice shy.","reasonZh":"原文所有協議都要書面。","correct":false},{"id":"foil-2","text":"Although Chloe’s new landlord has already stolen her deposit, she asks for every agreement in writing after unfairly losing part of her previous deposit—once bitten, twice shy.","reasonZh":"新業主只是看來友善，沒有偷按金的證據。","correct":false},{"id":"foil-3","text":"Although Chloe’s new landlord seems friendly, she asks for every agreement in writing after fairly recovering all of her previous deposit—once bitten, twice shy.","reasonZh":"原文被不公扣部分款項，不是全數追回。","correct":false}]},{"id":"proverb-03-q32","number":32,"promptEn":"Aaron’s last online course was poorly taught. Before paying for another course, he now watches a sample lesson.","promptZh":"Aaron 上一個網上課程的教學質素很差。他現在支付另一個課程的費用前，會先觀看示範課堂。","options":[{"id":"key","text":"Because his last online course was poorly taught, Aaron watches a sample lesson before paying for another one—once bitten, twice shy.","reasonZh":"劣質舊課令 Aaron 先看新課示範再付款；還是願意考慮課程。","correct":true},{"id":"foil-1","text":"Because his last online course was poorly taught, Aaron watches a sample lesson only after paying for another one—once bitten, twice shy.","reasonZh":"原文付款前。","correct":false},{"id":"foil-2","text":"Because his last online course was poorly taught, Aaron watches only the course title before paying for another one—once bitten, twice shy.","reasonZh":"示範課堂不等於課程名稱。","correct":false},{"id":"foil-3","text":"Because his last online course was exceptionally well taught, Aaron watches a sample lesson before paying for another one—once bitten, twice shy.","reasonZh":"上次教學差，非特別好。","correct":false}]},{"id":"proverb-03-q33","number":33,"promptEn":"I know that airlines usually handle luggage properly. However, after an airline lost one of my bags, I began putting my contact details both inside and outside every bag.","promptZh":"我知道航空公司通常會妥善處理行李。不過，一間航空公司遺失我的其中一件行李後，我開始在每個行李袋的內外都放上聯絡資料。","options":[{"id":"key","text":"I know that airlines usually handle luggage properly, but after losing one bag, I now put my contact details both inside and outside every bag—once bitten, twice shy.","reasonZh":"說話者承認航空公司通常可靠，仍因一次遺失而在每件行李內外留聯絡資料。","correct":true},{"id":"foil-1","text":"I know that airlines usually handle luggage properly, but after losing one bag, I now put my contact details only outside every bag—once bitten, twice shy.","reasonZh":"原文內外都放，不能只放外面。","correct":false},{"id":"foil-2","text":"I know that airlines usually handle luggage properly, but after losing one bag, I now put my contact details both inside and outside just one bag—once bitten, twice shy.","reasonZh":"原文每件行李。","correct":false},{"id":"foil-3","text":"I know that airlines always lose all luggage, but after losing one bag, I now put my contact details both inside and outside every bag—once bitten, twice shy.","reasonZh":"原文通常妥善，不是總會全部遺失。","correct":false}]},{"id":"proverb-03-q34","number":34,"promptEn":"The team’s last order arrived several weeks late. If it uses the same seller again, it will place only a small first order.","promptZh":"團隊上一次的訂單遲了數星期才送到。如果再次使用同一名賣家，團隊只會先下小額訂單。","options":[{"id":"key","text":"If the team uses the same seller again, it will place only a small first order—once bitten, twice shy after the last order arrived several weeks late.","reasonZh":"團隊可能再用同一賣家，但首單會小；沒有說一定再訂或永久拒絕。","correct":true},{"id":"foil-1","text":"When the team definitely uses the same seller again, it will place only a small first order—once bitten, twice shy after the last order arrived several weeks late.","reasonZh":"If 是條件，不是確定會再次使用。","correct":false},{"id":"foil-2","text":"If the team uses the same seller again, it will place another large first order—once bitten, twice shy after the last order arrived several weeks late.","reasonZh":"原文小額首單。","correct":false},{"id":"foil-3","text":"If the team uses the same seller again, it will place only a small first order—once bitten, twice shy after the last order arrived several weeks early.","reasonZh":"原文遲了數星期，不是早到。","correct":false}]},{"id":"proverb-03-q35","number":35,"promptEn":"Nora has not stopped accepting invitations. However, after attending an event that was very different from its description, she now asks who will be there.","promptZh":"Nora 並沒有停止接受邀請。不過，她曾參加一個與宣傳描述完全不同的活動，所以現在會先詢問有哪些人出席。","options":[{"id":"key","text":"Nora still accepts invitations, but she now asks who will be there after attending a badly described event—once bitten, twice shy.","reasonZh":"Nora 仍接受邀請，只是經歷描述不符的活動後先問誰出席。","correct":true},{"id":"foil-1","text":"Nora refuses every invitation, but she now asks who will be there after attending a badly described event—once bitten, twice shy.","reasonZh":"原文沒有停止接受。","correct":false},{"id":"foil-2","text":"Nora still accepts invitations, but she now asks only whether entry is free after attending a badly described event—once bitten, twice shy.","reasonZh":"她問出席者，不是只問是否免費。","correct":false},{"id":"foil-3","text":"Nora still accepts invitations, but she now asks who will be there after attending an event exactly as advertised—once bitten, twice shy.","reasonZh":"原先經驗與描述不符。","correct":false}]},{"id":"proverb-03-q36","number":36,"promptEn":"A company’s previous project with another firm was never completed. The company may work with the firm again, but only through a short trial agreement.","promptZh":"一間公司的上一個合作項目一直沒有完成。公司可能會再次與該機構合作，但只會先簽訂短期試行協議。","options":[{"id":"key","text":"The company may work with the firm again, but only through a short trial agreement—once bitten, twice shy after the unfinished project.","reasonZh":"上次合作未完成，公司可能再合作但只試短期；may 和 only 都保留。","correct":true},{"id":"foil-1","text":"The company has definitely agreed to work with the firm again, but only through a short trial agreement—once bitten, twice shy after the unfinished project.","reasonZh":"可能不等於已答應。","correct":false},{"id":"foil-2","text":"The company may work with the firm again, but only through an unrestricted ten-year agreement—once bitten, twice shy after the unfinished project.","reasonZh":"原文只短期試行，不是十年無限制。","correct":false},{"id":"foil-3","text":"The company may work with the firm again, but only through a short trial agreement—once bitten, twice shy after the successfully completed project.","reasonZh":"上一項目沒完成。","correct":false}]},{"id":"proverb-03-q37","number":37,"promptEn":"An old app lost many of Luis’s photographs. Even though a new app has good reviews, he wants to wait for more updates before using it.","promptZh":"一個舊應用程式遺失了 Luis 的很多照片。即使一個新應用程式獲得良好評價，他仍希望等待更多更新後才使用。","options":[{"id":"key","text":"Even though the new app has good reviews, Luis is waiting for more updates after an older app lost his photographs—once bitten, twice shy.","reasonZh":"Luis 的舊程式丟照片，雖然新程式好評仍等待更新；不是斷言新程式也會丟失。","correct":true},{"id":"foil-1","text":"Even though the new app has good reviews, Luis is installing it immediately after an older app lost his photographs—once bitten, twice shy.","reasonZh":"原文想等待。","correct":false},{"id":"foil-2","text":"Even though the new app has no reviews at all, Luis is waiting for more updates after an older app lost his photographs—once bitten, twice shy.","reasonZh":"原文已有好評。","correct":false},{"id":"foil-3","text":"Even though the new app has good reviews, Luis is waiting for more updates after this new app lost his photographs—once bitten, twice shy.","reasonZh":"丟照片的是舊程式，不是已證實新程式丟失。","correct":false}]},{"id":"proverb-03-q38","number":38,"promptEn":"The family had a very bad meal during its last holiday. It has not stopped eating out, but it now checks recent restaurant reviews.","promptZh":"這個家庭上次旅行時吃了一頓非常差的飯。他們並沒有停止外出用膳，但現在會查看餐廳的近期評論。","options":[{"id":"key","text":"The family has not stopped eating out, but it now checks recent restaurant reviews after a bad holiday meal—once bitten, twice shy.","reasonZh":"一家人仍外出用膳，只是因上次差的旅遊餐點而看近期評價。","correct":true},{"id":"foil-1","text":"The family has stopped eating out entirely, but it now checks recent restaurant reviews after a bad holiday meal—once bitten, twice shy.","reasonZh":"原文明說仍外出。","correct":false},{"id":"foil-2","text":"The family has not stopped eating out, but it now checks only old advertisements after a bad holiday meal—once bitten, twice shy.","reasonZh":"原文近期評論，不是舊廣告。","correct":false},{"id":"foil-3","text":"The family has not stopped eating out, but it now checks recent restaurant reviews after a pleasant holiday meal—once bitten, twice shy.","reasonZh":"戒心來自差的餐點。","correct":false}]},{"id":"proverb-03-q39","number":39,"promptEn":"The school once hired a coach who frequently failed to attend training. It knows that not every coach is unreliable, but it now interviews each one carefully.","promptZh":"學校曾聘請一名經常缺席訓練的教練。校方知道並非每名教練都不可靠，但現在會仔細面試每一名教練。","options":[{"id":"key","text":"After hiring a coach who frequently missed training, the school knows one poor coach does not make every coach unreliable, but interviews each one carefully—once bitten, twice shy.","reasonZh":"學校不把一名缺席教練推廣為全部不可靠，卻加強每次面試。","correct":true},{"id":"foil-1","text":"After hiring a coach who frequently missed training, the school knows one poor coach proves every coach unreliable, but interviews each one carefully—once bitten, twice shy.","reasonZh":"原文明確避免以偏概全。","correct":false},{"id":"foil-2","text":"After hiring a coach who frequently missed training, the school knows one poor coach does not make every coach unreliable, but interviews only the first applicant briefly—once bitten, twice shy.","reasonZh":"原文每一位仔細面試。","correct":false},{"id":"foil-3","text":"After hiring a coach who never missed training, the school knows one poor coach does not make every coach unreliable, but interviews each one carefully—once bitten, twice shy.","reasonZh":"原文教練經常缺席。","correct":false}]},{"id":"proverb-03-q40","number":40,"promptEn":"Grace gave money to an organisation that falsely claimed to be a charity. She now checks every organisation carefully before donating.","promptZh":"Grace 曾捐款給一個假稱是慈善機構的組織。她現在捐款前會仔細查核每個組織。","options":[{"id":"key","text":"After giving money to a false charity, Grace now checks every organisation carefully before donating—once bitten, twice shy.","reasonZh":"Grace 被假慈善組織騙過，現在每次捐前查核對方；沒有停止捐款。","correct":true},{"id":"foil-1","text":"After giving money to a false charity, Grace now checks only familiar organisations carefully before donating—once bitten, twice shy.","reasonZh":"原文每個組織。","correct":false},{"id":"foil-2","text":"After giving money to a false charity, Grace now checks every organisation carefully after donating—once bitten, twice shy.","reasonZh":"原文先查後捐。","correct":false},{"id":"foil-3","text":"After giving money to a verified legitimate charity, Grace now checks every organisation carefully before donating—once bitten, twice shy.","reasonZh":"原先組織是假稱慈善，不是已驗證的合法機構。","correct":false}]},{"id":"proverb-03-q41","number":41,"promptEn":"Another seller had previously disappeared after taking the shop owner’s money. When a new seller asked for full payment before delivery, the owner offered only a small deposit.","promptZh":"另一名賣家先前收取店主的款項後便失去聯絡。當一名新賣家要求在送貨前支付全數款項時，店主只提出支付小額訂金。","options":[{"id":"key","text":"When the new seller asked for full payment before delivery, the shop owner offered only a small deposit—once bitten, twice shy after another seller had disappeared with her money.","reasonZh":"舊賣家收錢失聯，新賣家要全款時店主只提小額訂金；不是拒絕所有交易。","correct":true},{"id":"foil-1","text":"When the new seller asked for full payment before delivery, the shop owner offered the full amount immediately—once bitten, twice shy after another seller had disappeared with her money.","reasonZh":"原文只小額訂金。","correct":false},{"id":"foil-2","text":"When the new seller asked for full payment before delivery, the shop owner offered only a small deposit—once bitten, twice shy after this new seller had disappeared with her money.","reasonZh":"失聯的是之前另一賣家，不能指控新賣家已失聯。","correct":false},{"id":"foil-3","text":"When the new seller asked for full payment after delivery, the shop owner offered only a small deposit—once bitten, twice shy after another seller had disappeared with her money.","reasonZh":"新賣家要求送貨前付款。","correct":false}]},{"id":"proverb-03-q42","number":42,"promptEn":"A: Why do you insist on buying travel insurance for every holiday? B: We once lost a large amount of money when a holiday had to be cancelled.","promptZh":"甲：你為甚麼堅持每次旅行都購買旅遊保險？乙：我們曾因一次旅行需要取消而損失大量金錢。","options":[{"id":"key","text":"“Once bitten, twice shy: we once lost a large amount when a holiday had to be cancelled, so we now buy travel insurance for every holiday.”","reasonZh":"說話者曾因取消旅行損失很多，現在每次買保險；原文沒指定事故年份。","correct":true},{"id":"foil-1","text":"“Once bitten, twice shy: we once lost a large amount when a holiday had to be cancelled, so we now buy travel insurance for only this one holiday.”","reasonZh":"原文明說每次旅行。","correct":false},{"id":"foil-2","text":"“Once bitten, twice shy: we once lost a large amount when a holiday went exactly as planned, so we now buy travel insurance for every holiday.”","reasonZh":"原先損失來自取消，不是完全按計劃。","correct":false},{"id":"foil-3","text":"“Once bitten, twice shy: we have never lost any money when a holiday had to be cancelled, so we now buy travel insurance for every holiday.”","reasonZh":"原文已有重大損失。","correct":false}]},{"id":"proverb-03-q43","number":43,"promptEn":"The town’s previous improvement plan was announced and then quietly abandoned. Residents will not support another plan unless it includes clear dates.","promptZh":"鎮上先前的改善計劃在公布後被悄悄擱置。除非另一個計劃列出明確日期，否則居民不會支持。","options":[{"id":"key","text":"The residents will not support another town plan without clear dates after the previous one was quietly abandoned—once bitten, twice shy.","reasonZh":"前計劃公布後擱置，居民要求新計劃列清楚日期才支持。","correct":true},{"id":"foil-1","text":"The residents will not support another town plan even with clear dates after the previous one was quietly abandoned—once bitten, twice shy.","reasonZh":"without 指欠缺日期時不支持，even with 把符合條件也排除。","correct":false},{"id":"foil-2","text":"The residents will not support another town plan without clear dates after the previous one was fully completed on time—once bitten, twice shy.","reasonZh":"原先計劃被放棄，不是準時完成。","correct":false},{"id":"foil-3","text":"The residents have already approved another town plan without clear dates after the previous one was quietly abandoned—once bitten, twice shy.","reasonZh":"原文尚待條件，不是已通過。","correct":false}]},{"id":"proverb-03-q44","number":44,"promptEn":"A venue owner once took the band’s money but cancelled the booking. The band manager will now book a venue only after receiving a written agreement and will pay only a small deposit.","promptZh":"一名場地東主曾收取樂隊的款項後取消預訂。樂隊經理現在只會在取得書面協議後預訂場地，而且只會支付小額訂金。","options":[{"id":"key","text":"The band manager will book only after receiving a written agreement and pay only a small deposit—once bitten, twice shy after a venue owner took payment but cancelled the booking.","reasonZh":"樂隊之前付款被取消，現在書面協議與小額訂金兩項都要保留。","correct":true},{"id":"foil-1","text":"The band manager will book only after receiving a friendly verbal promise and pay only a small deposit—once bitten, twice shy after a venue owner took payment but cancelled the booking.","reasonZh":"原文要書面協議。","correct":false},{"id":"foil-2","text":"The band manager will book only after receiving a written agreement and pay the full fee in advance—once bitten, twice shy after a venue owner took payment but cancelled the booking.","reasonZh":"樂隊經理現在只願付小額訂金，不會再次預付全數場租。","correct":false},{"id":"foil-3","text":"The band manager will book only after receiving a written agreement and pay only a small deposit—once bitten, twice shy after a venue owner took payment but honoured the booking.","reasonZh":"上次場主取消，並非履約。","correct":false}]},{"id":"proverb-03-q45","number":45,"promptEn":"Although the new flat looked fine, the couple tested every tap because their previous home had serious water problems.","promptZh":"雖然新單位看來沒有問題，但這對夫婦仍測試了每個水龍頭，因為他們上一個住所曾有嚴重水管問題。","options":[{"id":"key","text":"Although the new flat looked fine, the couple tested every tap after experiencing serious water problems in their previous home—once bitten, twice shy.","reasonZh":"雖然新單位外觀良好，夫婦因舊居水管問題仍測試每個水龍頭。","correct":true},{"id":"foil-1","text":"Although the new flat looked fine, the couple tested only the front-door lock after experiencing serious water problems in their previous home—once bitten, twice shy.","reasonZh":"原文檢查水龍頭，不是門鎖。","correct":false},{"id":"foil-2","text":"Although the new flat had already flooded, the couple tested every tap after experiencing serious water problems in their previous home—once bitten, twice shy.","reasonZh":"新單位只是外觀沒問題，沒有已水浸的資料。","correct":false},{"id":"foil-3","text":"Although the new flat looked fine, the couple tested every tap after experiencing no water problems in their previous home—once bitten, twice shy.","reasonZh":"舊居確有嚴重水管問題。","correct":false}]},{"id":"proverb-03-q46","number":46,"promptEn":"A: You seem unwilling to trust any online seller now. B: That is not true. However, one seller took my money and sent nothing, so I check the details first.","promptZh":"甲：你現在似乎不願信任任何網上賣家。乙：不是這樣。不過，一名賣家曾收取我的款項後沒有寄出任何貨品，所以我現在會先核對資料。","options":[{"id":"key","text":"I still trust reliable online sellers, but after one seller took my money and sent nothing, I now check the details first—once bitten, twice shy.","reasonZh":"說話者仍信可靠賣家，只是受騙後先查資料；不是一律不信。","correct":true},{"id":"foil-1","text":"I distrust every online seller, but after one seller took my money and sent nothing, I now check the details first—once bitten, twice shy.","reasonZh":"原文明確否認完全不信任。","correct":false},{"id":"foil-2","text":"I still trust reliable online sellers, but after one seller took my money and sent nothing, I now pay immediately without checking—once bitten, twice shy.","reasonZh":"原文先查資料。","correct":false},{"id":"foil-3","text":"I still trust reliable online sellers, but after one seller took my money and sent everything promptly, I now check the details first—once bitten, twice shy.","reasonZh":"舊賣家沒有寄貨，不是準時寄齊。","correct":false}]},{"id":"proverb-03-q47","number":47,"promptEn":"The bus for last year’s school trip failed to arrive. This year, the teacher checked the booking twice and saved the driver’s telephone number.","promptZh":"去年的學校旅行巴士沒有到達。今年，老師核對了兩次預訂，並保存了司機的電話號碼。","options":[{"id":"key","text":"This year, the teacher checked the school-trip bus booking twice and saved the driver’s telephone number—once bitten, twice shy after last year’s bus failed to arrive.","reasonZh":"去年的巴士失約，今年老師查訂位兩次並存司機電話；兩項防範都保留。","correct":true},{"id":"foil-1","text":"This year, the teacher checked the school-trip bus booking just once and saved the driver’s telephone number—once bitten, twice shy after last year’s bus failed to arrive.","reasonZh":"原文兩次。","correct":false},{"id":"foil-2","text":"This year, the teacher checked the school-trip bus booking twice and deleted the driver’s telephone number—once bitten, twice shy after last year’s bus failed to arrive.","reasonZh":"原文保存聯絡號碼。","correct":false},{"id":"foil-3","text":"This year, the teacher checked the school-trip bus booking twice and saved the driver’s telephone number—once bitten, twice shy after last year’s bus arrived early.","reasonZh":"去年巴士沒來。","correct":false}]},{"id":"proverb-03-q48","number":48,"promptEn":"Rain completely ruined the club’s last outdoor fair. The club may organise another one, but only if it can reserve a covered area.","promptZh":"大雨完全破壞了學會上一次的戶外市集。學會可能會再次舉辦，但前提是能夠預訂有遮蓋的地方。","options":[{"id":"key","text":"The club may hold another outdoor fair, but only if it can reserve a covered area—once bitten, twice shy after rain ruined the last one.","reasonZh":"上次雨毀市集，學會可能再辦但要能訂有蓋地方；不是一定取消。","correct":true},{"id":"foil-1","text":"The club has permanently cancelled another outdoor fair, but only if it can reserve a covered area—once bitten, twice shy after rain ruined the last one.","reasonZh":"原文仍有可能再辦。","correct":false},{"id":"foil-2","text":"The club may hold another outdoor fair, but even if it cannot reserve a covered area—once bitten, twice shy after rain ruined the last one.","reasonZh":"有蓋地方是必要條件，不能移除。","correct":false},{"id":"foil-3","text":"The club may hold another outdoor fair, but only if it can reserve a covered area—once bitten, twice shy after the last one had perfect weather.","reasonZh":"原文上次被雨破壞。","correct":false}]},{"id":"proverb-03-q49","number":49,"promptEn":"The company released its previous app update too quickly, and many customers complained. Even with a close deadline, the manager now refuses to release an update before testing it.","promptZh":"公司上一次太快推出應用程式更新，結果很多顧客投訴。即使限期迫近，經理現在也拒絕在完成測試前推出更新。","options":[{"id":"key","text":"After the last rushed update caused many complaints, the manager refuses to release another before testing it, even with a close deadline—once bitten, twice shy.","reasonZh":"上次更新太急被投訴，即使限期近也先測試；不是一趕時間就跳過。","correct":true},{"id":"foil-1","text":"After the last rushed update caused many complaints, the manager refuses to release another before testing it, but only when there is no deadline—once bitten, twice shy.","reasonZh":"原文即使趕也如此，不限於無限期時。","correct":false},{"id":"foil-2","text":"After the last rushed update caused many complaints, the manager refuses to release another after testing it, even with a close deadline—once bitten, twice shy.","reasonZh":"拒絕的是未測就發佈，不是測完後也不發佈。","correct":false},{"id":"foil-3","text":"After the last rushed update caused unanimous praise, the manager refuses to release another before testing it, even with a close deadline—once bitten, twice shy.","reasonZh":"原先版本引來投訴，不是全體讚美。","correct":false}]},{"id":"proverb-03-q50","number":50,"promptEn":"A: Would you invest in your friend’s new café? B: I might, but my previous investment was never repaid. I would need to see a clear business plan first.","promptZh":"甲：你會投資朋友的新咖啡店嗎？乙：可能會，但我上一次投資的款項一直沒有歸還。我需要先看到一份清楚的營運計劃。","options":[{"id":"key","text":"I might still invest in the café, but only after seeing a clear business plan because my previous investment was never repaid—once bitten, twice shy.","reasonZh":"舊投資沒回款，說話者仍可能投咖啡店，但要先看清楚計劃。","correct":true},{"id":"foil-1","text":"I will certainly invest in the café, but only after seeing a clear business plan because my previous investment was never repaid—once bitten, twice shy.","reasonZh":"might 保留可能性。","correct":false},{"id":"foil-2","text":"I might still invest in the café, but without seeing a clear business plan because my previous investment was never repaid—once bitten, twice shy.","reasonZh":"先看計劃是條件，不能刪去。","correct":false},{"id":"foil-3","text":"I might still invest in the café, but only after seeing a clear business plan because my previous investment was fully repaid early—once bitten, twice shy.","reasonZh":"原文舊款從未歸還。","correct":false}]},{"id":"proverb-03-x01","number":51,"theme":"science","promptEn":"A contaminated sample ruined one experiment. The lab now checks seals before every new trial.","promptZh":"受污染樣本毀了一次實驗，實驗室現在每次新試驗前都檢查封口。","options":[{"id":"key","text":"Once bitten, twice shy: after contamination ruined a trial, the lab now checks seals before every new one.","reasonZh":"先前污染導致針對性檢查，every 的頻率保留。","correct":true},{"id":"foil-1","text":"Once bitten, twice shy: after contamination ruined a trial, the lab now checks seals only after each trial.","reasonZh":"原文新試驗前檢查。","correct":false},{"id":"foil-2","text":"Once bitten, twice shy: after perfect results completed a trial, the lab now checks seals before every new one.","reasonZh":"原先是損失，不是成功。","correct":false},{"id":"foil-3","text":"Once bitten, twice shy: after contamination ruined a trial, the lab now abandons all experiments before every new one.","reasonZh":"仍做試驗，只加檢查。","correct":false}]},{"id":"proverb-03-x02","number":52,"theme":"performance","promptEn":"A dancer slipped on a wet stage once. Before her next performance, she asks for the floor to be checked.","promptZh":"舞者曾在濕舞台滑倒，下次演出前要求檢查地面。","options":[{"id":"key","text":"After slipping once, she asks for a floor check before performing again—once bitten, twice shy.","reasonZh":"先前滑倒與檢查地面直接相關，沒有說永久停演。","correct":true},{"id":"foil-1","text":"After slipping once, she asks for a floor check after every performance only—once bitten, twice shy.","reasonZh":"原文演出前。","correct":false},{"id":"foil-2","text":"After watching a comedy, she asks for a floor check before performing again—once bitten, twice shy.","reasonZh":"戒心來自滑倒，不是看喜劇。","correct":false},{"id":"foil-3","text":"After slipping once, she refuses ever to dance again before performing again—once bitten, twice shy.","reasonZh":"原文仍準備演出。","correct":false}]},{"id":"proverb-03-x03","number":53,"theme":"security","promptEn":"A phishing message fooled an employee last month. He now verifies the sender before opening unexpected attachments.","promptZh":"員工上月被釣魚訊息騙過，現在開啟意外附件前會核對寄件者。","options":[{"id":"key","text":"Once bitten, twice shy: fooled last month, he now checks the sender before opening unexpected attachments.","reasonZh":"保留先前受騙及先查再開的順序。","correct":true},{"id":"foil-1","text":"Once bitten, twice shy: fooled last month, he now checks the sender after opening unexpected attachments.","reasonZh":"預防在開附件前。","correct":false},{"id":"foil-2","text":"Once bitten, twice shy: fooled for the first time tomorrow, he now checks the sender before opening unexpected attachments.","reasonZh":"事件已在上月發生。","correct":false},{"id":"foil-3","text":"Once bitten, twice shy: fooled last month, he now trusts every sender immediately before opening unexpected attachments.","reasonZh":"原文加強查核，不是全信。","correct":false}]},{"id":"proverb-03-x04","number":54,"theme":"animals","promptEn":"A volunteer was scratched while rushing to lift a frightened cat. She now waits for the cat to approach.","promptZh":"義工急着抱起受驚的貓而被抓傷，現在會等貓主動靠近。","options":[{"id":"key","text":"After being scratched, she waits for the cat to approach—once bitten, twice shy, even without a literal bite.","reasonZh":"諺語不要求字面咬傷；抓傷引起謹慎亦可。","correct":true},{"id":"foil-1","text":"After being scratched, she waits for the cat to approach—once bitten, twice shy, only if the cat also bit her.","reasonZh":"不需要另一件咬傷事件。","correct":false},{"id":"foil-2","text":"After being scratched, she rushes to grab the cat again—once bitten, twice shy, even without a literal bite.","reasonZh":"原文改為等待。","correct":false},{"id":"foil-3","text":"Before ever meeting a cat, she waits for the cat to approach—once bitten, twice shy, even without a literal bite.","reasonZh":"先前已有負面經驗。","correct":false}]},{"id":"proverb-03-x05","number":55,"theme":"cooking","promptEn":"A cook burned a batch by guessing the oven setting. For the next batch, he checks the recipe temperature first.","promptZh":"廚師猜焗爐設定而燒焦一批食物，下批先查食譜溫度。","options":[{"id":"key","text":"Once bitten, twice shy: after burning a batch, he checks the recipe temperature before baking the next one.","reasonZh":"壞經驗令他不再隨便猜溫度；仍會烘焙。","correct":true},{"id":"foil-1","text":"Once bitten, twice shy: after burning a batch, he checks the recipe temperature after serving the next one.","reasonZh":"原文先查再焗。","correct":false},{"id":"foil-2","text":"Once bitten, twice shy: after winning a baking prize, he checks the recipe temperature before baking the next one.","reasonZh":"原先燒焦，不是得獎。","correct":false},{"id":"foil-3","text":"Once bitten, twice shy: after burning a batch, he guesses the setting again before baking the next one.","reasonZh":"原文改變了猜測習慣。","correct":false}]},{"id":"proverb-03-x06","number":56,"theme":"accessibility","promptEn":"An event’s advertised step-free route was blocked last time. The organiser now visits the route before confirming a venue.","promptZh":"上次活動聲稱無梯級的路線被阻塞，主辦人現在確認場地前親自查路線。","options":[{"id":"key","text":"After the blocked route last time, the organiser checks access in person before confirming a venue—once bitten, twice shy.","reasonZh":"針對之前的失誤查實通道，不是放棄無障礙要求。","correct":true},{"id":"foil-1","text":"After the blocked route last time, the organiser checks access in person only after the event a venue—once bitten, twice shy.","reasonZh":"原文確認前。","correct":false},{"id":"foil-2","text":"After the blocked route last time, the organiser checks access by trusting the same advert alone before confirming a venue—once bitten, twice shy.","reasonZh":"原文親自去，不是只信廣告。","correct":false},{"id":"foil-3","text":"After the fully accessible route last time, the organiser checks access in person before confirming a venue—once bitten, twice shy.","reasonZh":"原先問題是阻塞。","correct":false}]},{"id":"proverb-03-x07","number":57,"theme":"space","promptEn":"A telescope team lost observing time when a battery failed. It now tests the battery before each remote session.","promptZh":"望遠鏡團隊因電池故障失去觀測時間，現在每次遠端觀測前先測電池。","options":[{"id":"key","text":"Once bitten, twice shy: after the battery failure, the team tests it before each remote session.","reasonZh":"故障導致定期測試，並非每次都已故障。","correct":true},{"id":"foil-1","text":"Once bitten, twice shy: after the battery failure, the team tests it only after all sessions end.","reasonZh":"原文每次前。","correct":false},{"id":"foil-2","text":"Once bitten, twice shy: after the perfect battery performance, the team tests it before each remote session.","reasonZh":"原先確有故障。","correct":false},{"id":"foil-3","text":"Once bitten, twice shy: after the battery failure, the team assumes it will always fail before each remote session.","reasonZh":"測試是防範，不是斷言永遠壞。","correct":false}]},{"id":"proverb-03-x08","number":58,"theme":"community","promptEn":"A neighbourhood group trusted an unconfirmed hall booking and lost its meeting space. It now asks for written confirmation.","promptZh":"街坊小組信了未確認的禮堂預訂而失去聚會場地，現在會要求書面確認。","options":[{"id":"key","text":"Having lost its meeting space, the group now requests written confirmation—once bitten, twice shy.","reasonZh":"失去場地後要求證明，是相應防範。","correct":true},{"id":"foil-1","text":"Having lost its meeting space, the group now requests another vague verbal assurance—once bitten, twice shy.","reasonZh":"原文書面，不是含糊口頭保證。","correct":false},{"id":"foil-2","text":"Having always secured its meeting space, the group now requests written confirmation—once bitten, twice shy.","reasonZh":"原先失去場地，不是一向成功。","correct":false},{"id":"foil-3","text":"Having lost its meeting space, the group now permanently refuses written confirmation—once bitten, twice shy.","reasonZh":"原文索取確認，不是拒絕任何確認。","correct":false}]},{"id":"proverb-03-x09","number":59,"theme":"workplace","promptEn":"A freelancer previously worked unpaid extra hours on an unclear brief. She might accept a new project, but only with a clear scope.","promptZh":"自由工作者曾因工作要求不清而無償加班；她可能接新項目，但必須先有清楚範圍。","options":[{"id":"key","text":"She might accept the project only with a clear scope after the unpaid overtime—once bitten, twice shy.","reasonZh":"might 及 only with 保留有條件的可能性，不是全面拒絕。","correct":true},{"id":"foil-1","text":"She has definitely accepted the project only with a clear scope after the unpaid overtime—once bitten, twice shy.","reasonZh":"原文只是可能。","correct":false},{"id":"foil-2","text":"She might accept the project without checking the scope after the unpaid overtime—once bitten, twice shy.","reasonZh":"清楚範圍是條件。","correct":false},{"id":"foil-3","text":"She might accept the project only with a clear scope after the generous payment for every hour—once bitten, twice shy.","reasonZh":"原先無償加班，不是每小時獲厚酬。","correct":false}]},{"id":"proverb-03-x10","number":60,"theme":"travel","promptEn":"A cyclist followed a route marked easy and faced an unsafe climb. He still cycles, but checks elevation before new routes.","promptZh":"單車手跟隨標示容易的路線卻遇上危險斜坡；他仍踩單車，但新路線先查高度變化。","options":[{"id":"key","text":"He still cycles but checks elevation after the unexpectedly unsafe climb—once bitten, twice shy.","reasonZh":"仍繼續活動而增加查核，謹慎並不等於放棄。","correct":true},{"id":"foil-1","text":"He has given up cycling forever but checks elevation after the unexpectedly unsafe climb—once bitten, twice shy.","reasonZh":"原文明說仍踩車。","correct":false},{"id":"foil-2","text":"He still cycles but chooses routes without looking after the unexpectedly unsafe climb—once bitten, twice shy.","reasonZh":"現在會先查。","correct":false},{"id":"foil-3","text":"He still cycles but checks elevation after the unexpectedly safe and effortless ride—once bitten, twice shy.","reasonZh":"原先是危險斜坡。","correct":false}]}],"guide":{"meaning":{"zh":"曾吃過虧，所以再遇類似事情時更加謹慎或有所卻步。","en":"A previous unpleasant experience makes someone more cautious or reluctant in a similar situation."},"model":{"zh":"上次租來的帳篷漏水後，Lena 這次先檢查接縫：吃過一次虧，便格外小心。","en":"Lena checks the seams before renting another tent after the last one leaked—once bitten, twice shy."},"picture":{"zh":"把上次的壞經驗想成提醒燈：下次走到類似路口，你先停一停、看清楚。","en":"Think of the bad experience as a warning light: at a similar junction next time, you pause and look carefully."},"boundary":{"zh":"bitten 不必是真被咬，twice 也不是精確次數。謹慎不一定等於永久放棄，更不能把一次壞經驗說成所有人都不可靠。","en":"No literal bite or exact count is required. Caution need not mean giving up forever, and one bad experience does not prove everyone is unreliable."},"where":{"zh":"適合解釋自己或別人為何猶豫。別用來嘲笑受驚的人；嚴重經歷往往需要更直接的體諒。","en":"Use it to explain hesitation. Do not mock someone’s fear; serious experiences may call for more direct empathy."},"tone":{"zh":"日常、可帶體諒或自嘲；shy 在這裏是有所戒心，不一定是性格害羞。","en":"Conversational, sometimes sympathetic or self-deprecating; “shy” here means wary, not necessarily socially timid."},"checks":[{"zh":"之前真的有不愉快經歷嗎？","en":"Was there an earlier unpleasant experience?"},{"zh":"現在的謹慎與那次經歷有關嗎？","en":"Is the present caution connected to that experience?"},{"zh":"我有把「小心」擴大成「永不再試」嗎？","en":"Am I exaggerating caution into never trying again?"}],"readAloud":{"zh":"上次快遞把包裹留在雨中後，我現在要求簽收：吃過虧便更謹慎。","en":"After a courier left my parcel in the rain, I now request a signature—once bitten, twice shy."},"choices":{"2":{"prompt":{"zh":"哪個情況有足夠線索支持這句諺語？","en":"Which situation supplies enough evidence for the proverb?"},"options":[{"zh":"上次翻譯漏掉截止日期後，編輯現在在刊印前特別核對每個日期。","en":"After a translation omitted a deadline, the editor now checks every date before publication.","reasonZh":"先前失誤帶來有關的防範，兩個環節都有。","correct":true},{"zh":"編輯第一次接觸翻譯工作，因為好奇而讀稿。","en":"The editor reads a translation out of curiosity on her first day in the job.","reasonZh":"沒有之前的壞經驗，也沒有因此變謹慎的線索。","correct":false},{"zh":"編輯很喜歡上次的譯稿，所以立即再次聘用同一人。","en":"The editor loved the last translation and immediately hires the same person again.","reasonZh":"這是成功經驗帶來信任，不是吃虧後的戒心。","correct":false}]},"3":{"prompt":{"zh":"朋友曾在群組被人公開嘲笑，現在不願發言。哪個回應最體諒？","en":"A friend was publicly mocked in a group and now hesitates to post. Which response is most considerate?"},"options":[{"zh":"「吃過那次虧，你現在小心一點很合理。我們可以先用私人訊息。」","en":"“Once bitten, twice shy—it makes sense to be cautious after that. We can use private messages first.”","reasonZh":"承認原因並提供選擇，沒有嘲笑或催迫。","correct":true},{"zh":"「Once bitten, twice shy！你連發一句話也怕，真沒用。」","en":"“Once bitten, twice shy! You’re useless if you’re afraid to post one line.”","reasonZh":"諺語不能替羞辱合理化，這會加重對方的壓力。","correct":false},{"zh":"「Once bitten, twice shy，意思是你天生害羞，與上次事件無關。」","en":"“Once bitten, twice shy means you’re naturally timid; it has nothing to do with last time.”","reasonZh":"把後天經驗造成的戒心誤作天生性格。","correct":false}]},"5":{"prompt":{"zh":"登山隊上次跟着過時地圖走錯路，今次出發前核對新地圖。哪句自然又準確？","en":"A hiking team got lost using an old map. This time it checks an updated map before setting off. Which line fits?"},"options":[{"zh":"「上次走錯路後，我們今次先核對地圖；once bitten, twice shy。」","en":"“After getting lost last time, we’re checking the map before setting off—once bitten, twice shy.”","reasonZh":"保留壞經驗及相應檢查，沒有說全隊永不登山。","correct":true},{"zh":"「上次走錯路後，我們今次完全不看地圖；once bitten, twice shy。」","en":"“After getting lost last time, we’re skipping the map entirely—once bitten, twice shy.”","reasonZh":"原文是核對地圖，不是取消檢查；防範行動被倒轉。","correct":false},{"zh":"「上次每一步都走對，所以今次不用核對地圖；once bitten, twice shy。」","en":"“Every step was right last time, so we need no map check—once bitten, twice shy.”","reasonZh":"既移除了壞經驗，也否定今次的檢查。","correct":false}]},"6":{"prompt":{"zh":"一次不佳的維修經驗後，Arun 仍會聘維修師傅，但先看評價。這句諺語能說明甚麼？","en":"After a poor repair, Arun still hires repairers but checks reviews first. What can the proverb explain?"},"options":[{"zh":"先前經驗令他增加檢查，並不表示他不再信任任何師傅。","en":"The experience made him add a check, without distrusting every repairer.","reasonZh":"他仍會聘人，證明謹慎可以與繼續嘗試並存。","correct":true},{"zh":"他必須再受騙一次，才符合 twice 的字面次數。","en":"He must be cheated once more to satisfy the literal count “twice.”","reasonZh":"twice 不是規定受騙次數；諺語描述戒心。","correct":false},{"zh":"一次差的維修證明所有師傅都會騙他。","en":"One poor repair proves that every repairer will cheat him.","reasonZh":"一次經驗不能推出全體都不可靠。","correct":false}]}}}}};
